window.QUIZ_NATIONAL = (window.QUIZ_NATIONAL||[]).concat([{"q":"소나무 숲이 우거진 동산 기슭에 남향으로 자리잡고 있는 집으로 조선 중기의 문신 계서 성이성(1595∼1664)이 조선 광해군 5년(1613)에 지었다고 전한다. 성이성은 문과에 급제한 후 6개 고을의 수령을 지냈고, 3차례나 어사로 등용되었을 정도로 청렴한 관리로 이름이 높았다. 사랑채는 후에 넓히거나 다시 지은 것으로 추측된다. 아래쪽 마당 끝에 대문간채를 두고 그 북쪽 높은 곳에 사랑채와 안채가 하나로 연결되어 'ㅁ'자형 집을 이루고 있다. 대문간을 들어서면 비교적 넓은 사랑마당이 있고 맞은편 높은 곳 서쪽에 중문간채가 있다.","a":"봉화 계서당 종택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635273.jpg"},{"q":"신라 최초의 김씨 왕으로 백제의 여러차례 공격을 막아내고 농업을 장려한 신라 13대 왕인 미추이사금(재위 262∼284)의 무덤이다. 『삼국사기』에는 ○○○○과 관련된 전설이 전해지고 있다. 신라 유례왕 14년(297) 이서고국(伊西古國) 사람이 수도인 금성을 공격하여 위급한 상황에 처하자 대나무잎을 귀에 꽂은 군사가 나타나 적을 물리치고 사라졌다. 누군가 ○○○○에 댓잎을 수북이 쌓인 것을 보고 ○○○이 죽어서도 신라를 도와주었다하여 ○○○○을 죽장릉(竹長陵), 죽현릉(竹現陵)이라 부른다고 한다.","a":"경주 미추왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627779.jpg"},{"q":"□ 입지 현황 및 역사문화환경 ○○○○○는 신라의 동악(東岳)인 토함산(土含山) 서측 기슭에 위치하며, 남향으로 배치되어 있다. ○○○의 지형은 북측이 높고 남측이 낮은 북고남저(北高南低)와 동측이 높고 서측이 낮은 동고서저(東高西低)으로 지형에 따라 석축을 가구식으로 조화롭게 쌓았으며, 동측 사역에는 자하문, ○○○, 무설전을 남북 축선에 배치하면서 회랑을 둘러 공간을 구성하고 있다. ○○○의 동·서측면에는 익랑(翼廊)이 놓여 동·서 회랑과 연결되고 남회랑의 동측 모서리에는 좌경루(左經樓)가 있고, 서측 모서리에는 범영루(泛影樓)가 배치되어 있다.","a":"경주 불국사 대웅전","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622310.jpg"},{"q":"○○○○○은 1454(단종 2)년경에 이계양(繼陽, 1424-1488)에 의해 건립되었고, 본채는 정면 7칸, 측면 6칸으로 북부지방 일반 양반가옥과 유사하며, 특히 퇴계 이황이 출생한 태실은 내정 중앙에 자리하여 안채 툇간마루와 연결되는 한칸 규모 온돌방과 반칸 폭의 누마루로 구성 되어 잘 보존되고 있음.","a":"안동 진성이씨 온혜파 종택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2018111316160400.jpg"},{"q":"○○○○는 신라 소지왕 7년(485) 극달화상이 세웠다고 전하는 절이다. 이 건물은 사역(寺域) 동쪽에 있는 대웅전(大雄殿)이 과거 어느 시기에 불에 타버려 근래까지 대웅전으로 사용하고 있었으나 2011년까지 해체보수 결과 조선 영조 37년(1761년) ○○○으로 상량하였다는 기록이 발견되어 ○○○으로 명칭을 변경하였다. 앞면 1칸·옆면 2칸 규모이지만 앞면 1칸 사이에 사각형의 사이기둥을 세워 3칸 형식을 띠고 있는 것이 독특하다.","a":"대구 북지장사 지장전","c":"보물","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615252.jpg"},{"q":"ㅇ ○○○○는 광복 후 민주주의와 공산주의가 대립하던 시기에 지역 방어를 위해서 지역 주민들의 자금으로 축조된 시설물로 건립 당시에 1층은 총과 탄환, 기타 장비를 보관하였고 2층은 숙직실, 3층은 기관총과 다른 장비를 이용하여 사격장소로 사용되었다고 하나 현재는 3층이 유실되어 있음. ㅇ 광복이후 어지러운 당시의 치안 상태를 잘 보여주는 시설물로 빨치산 활동과 경찰에 의한 공비토벌 등 한국현대사에서 나타난 혼란과정의 한 단면을 볼 수 있는 유구로 역사적 가치가 있음.","a":"임실 회문망루","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2031367.jpg"},{"q":"정유재란 때 전라도지방의 관문이었던 ○○○을 끝까지 지키다가 숨진 ○○출신 의사(義士) 7명의 무덤이다. ○○○은 경상도지방에서 전라도지방으로 통하는 관문으로서 군사전략상 매우 중요한 곳이었다. 안음의 황석산성·진안 웅치·운봉 팔량치와 함께 영남과 호남 사이의 4대 관문의 하나로, 고려때부터 이곳에 진영이 설치되어 왜군의 침략을 막았다. 1597년 정유재란이 일어났을 때 왜군은 호남지방을 목표로 하여 이곳을 집중공격하였다. 그러자 왕득인이 의병을 일으켜 적에게 대항하였으나 결국 숨지고 말았다.","a":"구례 석주관 칠의사묘","c":"사적","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627043.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하는데, 우리나라 천태종의 근본경전으로 부처가 되는 길이 누구에나 열려 있다는 것을 기본사상으로 하고 있다. 화엄경과 함께 우리나라 불교사상 확립에 크게 영향을 미쳤으며, 우리나라에서 유통된 불교경전 가운데 가장 많이 간행된 경전이다. 이 책 ○○○○○은 휴대하기 편리하게 하기 위해 작게 만든 책이며, 작은 글자로 7권 전부를 95판(板) 100장(張)으로 새기고 찍어낸 것이다.","a":"묘법연화경(1981)","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613649.jpg"},{"q":"사명대사(1544~1610)는 임진왜란 때 의병과 승병을 일으켜 나라에 큰 공을 세운 인물이다. 이 유물은 사명대사가 착용했던 가사와 ○○이다. 가사는 승려들이 입던 법의(法衣)로 ○○을 입고 그 위에 왼쪽 어깨에서 오른쪽 겨드랑이 밑으로 걸쳐 입덧 옷이다. ○○은 검은색이나 흰색으로 만든 길이가 길고 소매가 넓은 옷으로 가사와 함께 승려가 입는 법복 중 하나이다. 사명대사 금란가사는 황금색의 중국 비단으로 만들었는데, 현재는 담황색으로 변색되고 훼손도 심하여 본래의 모습을 파악하기가 힘들다.","a":"사명대사의 금란가사와 장삼","c":"국가민속문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635799.jpg"},{"q":"괘불이란 야외에서 큰 법회나 의식을 열 때 사용하던 대형 불화를 말하며, 이 괘불은 ○○○○○을 주존으로 그린 것이다. 중앙의 ○○○○○을 중심으로 6대 보살, 10대 제자, 제석천과 범천, 사천왕, 천자, 아수라, 용왕 등이 좌우 대칭으로 화면 가득히 그려진 모습이다. ○○○○○은 용화수가지를 양 손에 받쳐 들고 있는 모습으로 손이 다른 신체 부분에 비해 크게 그려져 있다. 부처의 몸에서 나오는 빛을 상징하는 광배(光背)는 둥근 머리광배와 배(舟) 모양의 몸광배로 구분되는데 머리광배에는 작은 부처 여러 구를 그려 넣었다.","a":"마곡사 석가모니불 괘불탱","c":"보물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618022.jpg"},{"q":"조선시대 고종(재위 1863∼1907)이 사용하던 활이라고 전하며, 당시 활 만드는 장인 장문환이 제작하였다고 한다. 활의 전체길이는 124㎝이고, 오금너비는 3㎝이다. 한국의 전통적인 ○○은 명성이 높고 독특한 자료로 만들었다. 글자 그대로 쇠뿔의 장점을 최대한으로 활용하여 제작한 것으로 한국의 대나무, 물소뿔, 쇠심, 구지뽕나무, 참나무, 화피의 6가지 재료로 구성된다. 이 ○○은 벚나무 껍질로 만든 화피 위에 채색을 하였으며, 시위고리를 거는 새코머리는 가죽으로 감싸서 3가지 색의 천으로 발랐고 그 밑에는 아(亞)자 무늬를 새긴 검정색 종이로 감쌌다.","a":"각궁","c":"국가민속문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633090.jpg"},{"q":"○○○는 정면 3칸, 측면 3칸 규모의 출목 2익공 5량가의 맞배지붕 건물로, 평면구성은 전면에 퇴칸을 설정하지 않고 전후 평주 사이에 벽과 출입문을 설치하여 사당 내부 공간을 넓게 확보한 점이 눈에 띄며, 출목 2익공의 세부 형상은 17세기의 시대특징을 간직하고 있으며 내부 지붕틀은 대들보와 종보를 걸고 장식이 가미된 대공을 설치함.","a":"구미 금오서원 상현묘","c":"보물","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122910565600.jpg"},{"q":"1923년 건립된 이 건물은 충북 지역 선교의 거점 역할을 목적으로 세워진 성당으로 ○○○ 성당의 특징인 한옥 성당의 모습을 잘 나타내고 있다. 정면 4간, 측면 8간 규모로 동쪽에 출입구, 서쪽에 제단을 두었으며, 내부는 두 개의 열주에 의해 신랑(身廊, Nave)과 측랑(側廊, Aisle)이 뚜렷하게 구별되는 전형적인 바실리카식 공간으로 이루어졌다. 목조 한옥의 구조를 성당 건축에 적용한 예이며, 충북 지역 최초의 ○○○ 건축물이자 이후 ○○○ 성당 건축물의 본보기가 되고 있다.","a":"대한성공회 진천성당","c":"국가등록문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668475.jpg"},{"q":"조선 중기의 집으로 영조 52년(1776)에 삼수부사를 지낸 유이주가 지었다고 한다. 풍수지리설에 의하면 이곳은 산과 연못으로 둘러싸여 있어 ‘금환락지(金環落地)’라 하는 명당자리로 불려왔다. 집의 구성은 총 55칸의 목조기와집으로 사랑채, 안채, 행랑채, 사당으로 구성되어 있다. 사랑채는 T자형으로 누마루 형식을 취하고 있다. 일반적으로 사랑채에는 큰 부엌이 없는데 이곳에는 안채 통로까지 겸한 큰 부엌이 마련되어 있다. 또한 사랑채와 직각을 이룬 누마루가 있어 전체 살림을 한눈에 관찰하도록 되어있어 특이하다.","a":"구례 운조루 고택","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634553.jpg"},{"q":"○○○은 제주시 용담동을 가로질러 흐르는 한내 옆에 있었던 신당으로 고종 19년(1882)에 훼철(毁撤)되었다. ○○○에는 당나무에 종이돈, 염색한 옷감 등을 걸어 신체(神體)를 삼는 ○○○내의 다른 당들과는 달리 12위 신의 모습들을 그려 모셨는데, 현재는 10폭만이 남아 있다. 남신상 6폭과 여신상 4폭으로 남신은 제석위, 원망위, 수령위, 천자위, 감찰위, 상사위 등이 있고, 여신은 본궁위, 중전위, 상군위, 홍아위 등이다.","a":"제주도 내왓당 무신도","c":"국가민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1636036.jpg"},{"q":"정유재란 때 충무공 이순신(1545∼1598) 장군과 명나라 장수 진린(陳璘)의 군사들이 힘을 합해 왜군을 물리쳤던 장소이다. 충무공은 무과에 급제하여 전라좌도 수군절도사를 지내던 때에 왜적의 침입을 대비하여 여수를 중심으로 배를 만들고 군비를 늘리는 등 일본의 침략에 대비하였다. 선조 25년(1592)에 임진왜란이 터지자 옥포대첩, 노량해전, 당항포해전, 한산대첩 등 곳곳에서 전승을 거두었고, 정유재란 때에는 명량대첩 등에서 승리를 거두었다. 그가 죽은 후 1604년 선무공신 1등에 올랐고, 영의정에 추증되었으며, ‘충무(忠武)’라는 시호가 내려졌다.","a":"완도 묘당도 이충무공 유적","c":"사적","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627055.jpg"},{"q":"용범은 동(銅)으로 된 도구를 만들기 위해 필요한 틀로써 ○○○, 주형이라고 한다. 우리 나라에서는 돌로 된 ○○○이 주로 사용되었다. 숭실대학교에 소장되어 있는 이 ○○○은 활석으로 만든 것으로 광복 후 전라남도 ○○군에서 발굴된 것으로 전해지고 있다. 1) 세형동검용범일조(細形銅劍鎔范一組) 두 쪽을 합쳐 사용하게 되어 있으며, 한 쪽의 크기가 34.5㎝×7.4㎝×4㎝이다. 이 ○○○에서 만들 수 있는 동검의 길이는 33㎝이다. 많이 사용하여 돌이 까맣게 타 있고 부분적으로 떨어진 곳도 있다.","a":"전 영암 거푸집 일괄","c":"국보","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611784.jpg"},{"q":"○○○○○에 세워진 이 ○○은 전체 높이 6.4m로 한국에서 가장 커다란 규모이다. ○○은 부처의 광명을 상징한다 하여 광명등(光明燈)이라고도 하는데, 대개 사찰의 대웅전이나 탑과 같은 중요한 건축물 앞에 배치된다. 불을 밝혀두는 화사석(火舍石)을 중심으로, 아래로는 3단의 받침돌을 두고, 위로는 지붕돌을 올린 후 꼭대기에 머리장식을 얹어 마무리한다. 8각 바닥돌 위의 아래받침돌에는 엎어놓은 연꽃무늬를 큼직하게 조각해 놓았고, 그 위로는 장고 모양의 가운데 기둥을 세워두었다.","a":"구례 화엄사 각황전 앞 석등","c":"국보","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612398.jpg"},{"q":"경주시 황남동 미추왕릉 지구에 있는 삼국시대 신라 무덤인 ○○○○의 북쪽 무덤에서 발견된 금 ○○○와 띠드리개(요패)이다. ○○○○은 남·북으로 2개의 봉분이 표주박 모양으로 붙어있다. 과대는 직물로 된 띠의 표면에 사각형의 금속판을 붙인 ○○○로서 길이 120㎝, 띠드리개 길이 22.5∼77.5㎝이다. 28장의 판(板)으로 만들어진 이 ○○○는 주위에 있는 작은 구멍들로 미루어 가죽같은 것에 꿰매었던 것으로 짐작된다. ○○○ 아래에 매달려 있는 13개의 띠드리개는 경첩으로 ○○○와 연결하였다.","a":"황남대총 북분 금제 허리띠","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612867.jpg"},{"q":"이 건물은 조선 성종 10년(1479) 박팽년의 손자인 박일산이 세운 별당건축이다. 지금 있는 건물은 선조 25년(1592) 임진왜란 때 불타서 일부만 남았던 것을 광해군 6년(1614)에 다시 지은 것이다. 일명 ‘일시루(一是樓)’라고도 한다. 현재 대청에는 임진왜란 후 치찰사로 온 윤두수의 한시를 새긴 현판과, 정유재란 후 명군 선무관이 남긴 액자 들이 있다. 네모난 모양의 단 위에 서 있으며 앞면 4칸 ·옆면 2칸 크기로, 동쪽 2칸은 대청마루이고, 서쪽 2칸은 방으로 꾸몄다. 대청 앞면은 개방되어 있는데 옆면과 뒷면에는 문을 달았을 것으로 추정한다.","a":"달성 태고정","c":"보물","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615232.jpg"},{"q":"이 건물은 대칭형으로 단순하게 구성된 전형적인 소규모 관공서 건물로, ○○○○○로 사용하기 위해 1955년에 건립하였다. 건물 외부는 제주의 전통적, 토속적 건축 재료인 현무암을 일정한 규격으로 가공해 쌓았으며, 외벽 모서리에서 벽체를 약간 안쪽으로 기울게 처리하는 등 투박하면서도 단정한 모습의 특색있는 건축 형태를 가지고 있다.","a":"남제주 구 대정면사무소","c":"국가등록문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669564.jpg"},{"q":"영조의 막내딸 화길옹주가 구민화에게 시집가자 왕이 그를 위하여 지어준 집이다. 북한강변에 위치한 산골짜기에 자리잡고 있어 자연적인 조경이 잘 이루어져 있다. ○○이라는 칭호는 나라에서 재목과 목수를 보내어 집을 지었기 때문에 생겼다. 전형적인 'ㅁ'자형의 안채는 남향으로 자리하였는데, 대문을 들어선 정면으로 부엌·안방·대청이 있고 꺾어져서 오른쪽에는 건넌방·부엌, 왼쪽에는 아랫방과 사랑뒷마루, 대문 옆으로는 광 ·책방이 자리잡고 있다. 안채의 서남쪽 귀퉁이에 있는 'ㄱ'자형의 사랑채는 안채의 사랑뒷마루와 연결이 되어있다. 사랑방을 제외한 나머지는 모두 마루를 깔았다.","a":"남양주 궁집","c":"국가민속문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633746.jpg"},{"q":"ㅇ ○○○○○는 부자식 자기수위계를 설치하여 한강의 수위를 관측하던 시설로 정통(井筒)과 ○○○로 이루어진 타워 및 강안(江岸)에서 ○○○를 연결하는 교각 등이 하나의 세트를 구성되지만 현재 교각은 소실되어 남아 있지 않음 ㅇ 건립 당시의 토목기술 및 수위측정방식 등을 알 수 있는 시설물로 가치가 있음","a":"고양 행주수위관측소","c":"국가등록문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2031567.jpg"},{"q":"○○은 조선 14대 선조(宣祖)와 첫 번째 왕비 의인왕후 박씨(懿仁王后 朴氏), 두 번째 왕비 인목왕후 김씨(仁穆王后 金氏)의 능으로 ○○○○○에서 세 번째로 조성된 능이다. 능의 형식은 같은 능역에 하나의 ○○○을 두고 서로 다른 언덕에 봉분을 조성한 동원이강릉(同原異岡陵)이다. 원래 ○○ 능역에는 1600년(선조 33) 의인왕후의 유릉(裕陵)이 먼저 조성되었다.","a":"구리 동구릉 목릉 정자각","c":"보물","nc":"","r":"경기도","s":"구리시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616223.jpg"},{"q":"석가가 영축산에서 설법하는 모습인 ○○○상을 그린 괘불이다. 괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞뜰에 걸어놓고 예배를 드리는 대형 불교그림을 말한다. ○○○에 있는 이 괘불의 크기는 전체 1,208.0×769.4cm , 화면 1,013.1×732.3cm이다. 석가불을 중심으로 문수보살·보현보살과 사천왕상 등이 배치되었다. 화면 중앙의 석가불은 높다랗게 만들어진 단의 연꽃받침 위에 앉아 있으며, 마귀를 물리친다는 의미로 손가락이 땅으로 향한 손모양을 취하고 있다.","a":"화엄사 영산회 괘불탱","c":"국보","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612567.jpg"},{"q":"「○○○○○」은 통일신라 말이나 고려초에 건립된 것으로 추정되며 경북지역에 집중된 모전석탑의 양식을 지니고 있다. 경북지역 전탑과 모전석탑은 초층탑신의 1면에만 감실을 마련하는 것이 특징인데 감실 좌우 문설주에 당초문을 조각하여 예술성을 높인 점은 이 석탑에만 나타나는 특이한 모습이다. 또한 벽돌모양으로 석재를 다듬을 경우 각진 위치에 자리하는 모서리 돌들을 둥글게 처리하여 탑의 조형에 부드러움을 주고자 한 의지를 느낄 수 있는 점도 특이한 사례이다.","a":"영양 현리 오층모전석탑","c":"보물","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020072712561600.JPG"},{"q":"○○○○○은 ○○ 최초의 근대식 개인 종합병원으로 당시 ○○부립병원, 철도병원과 함께 지역에서 중요한 의료기관 건물로 근대 의료사적으로 가치가 있음 1927년 2월, 12월에 각각 건립된 두동이 하나로 합쳐진 건물로 내부 평면이 사각형, 마름모꼴 형태의 다양한 실들로 구성되어 있으며 최초 건립되었던 1, 2, 3층에는 목조계단과 장식, 디테일 등 목재로 마감된 원형이 잘 남아 있음","a":"부산 구 백제병원","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2241680.jpg"},{"q":"육민관(育民館)이 1946년 강원지역 최초의 사학으로 설립된 이후 1954년 현재의 위치에 ○○○○○를 개교하면서 국제연합 한국재건단(UNKRA)의 원조와 제1야전군사령부의 도움을 받아 건축한 건물이다. 당시 ‘ㅡ’자형의 일반적 학교건물과 다르게 중앙부 현관(porch)을 중심으로 양쪽 날개부가 각각 16도 정도 꺾여 배치되며 전체적으로 항공기 날개 형태와 유사한 매우 독특한 평면과 외관을 형성하고 있다.","a":"원주 육민관고등학교 창육관","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017121111133800.JPG"},{"q":"수원교구 내 현존하는 한옥 ○○로서 역사가 오래되고 지역적 상황을 잘 담아내고 있으며 근대기 천주교가 정착해 가는 과정에서 그 기능을 담아내기 위해 한옥이 변모해 가는 흔적을 잘 보여주고 있다.","a":"용인 고초골 공소","c":"국가등록문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018040915483100.jpg"},{"q":"○○○에 자리잡고 있는 고려전기의 탑비로 ○○○를 중흥한 정진대사의 것이다. 정진대사(878∼956)는 통일신라 말에서 고려 초에 활약한 승려로, 효공왕 4년(900) 당나라에 들어가 25년간 유학하고 경애왕 1년(924)에 돌아와 신라 경명왕의 극진한 예우를 받았다. 고려 태조 18년(935)에는 ○○○를 두번째로 크게 짓고, 불교의 중흥에 이바지하기도 하였다. 특히 고려 전기의 태조·혜종·정종을 선문(禪門)에 들게 한 장본인으로, 79세의 나이로 입적하자 왕은 ‘정진’이라는 시호와 ‘원오’라는 탑이름을 내리었다.","a":"문경 봉암사 정진대사탑비","c":"보물","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620443.jpg"},{"q":"○○○○○는 조선 후기 대동법을 시행하였던 김육(金堉)의 아들 ○○○○○ 우명(右明 : 1619~1675)이 죽었을 때 시신을 향리로 운구하기 위해 나라에서 하사한 것이다. 이 ○○는 묘소 북방 골짜기에 초가를 지어 보관하며 마을에서 공동으로 사용했었다. ○○는 긴 멜대를 중심으로 한 기본 틀 위에 관을 싣는 몸체를 조성하고 맨 위에는 햇빛을 가리기 위해 밝은 천을 넓게 펼친 모습이다. 몸체에는 봉황머리와 용이 정교하게 조각되고, 검은 천 위에 색띠와 술을 늘어뜨렸는데 망자의 명복을 빌고 슬픔을 덜려는 의미로 보여진다.","a":"청풍부원군 상여","c":"국가민속문화유산","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633809.jpg"},{"q":"대안사에 있는 탑비로, 고려시대 승려 광자대사 윤다(允多)의 탑비이다. 광자대사는 대안사를 두 번째로 크게 번성케 한 스님으로, 경문왕 4년(864)에 태어나, 8세에 출가하였다. 사방을 다니다가 동리산에서 수도를 하였고, 그 뒤 가야갑사(迦耶岬寺)에서 계(戒)를 받아, 다시 동리산으로 돌아와서 승려가 되었다. 혜종 2년(945)에 82세로 입적하니, 왕은 시호를 ‘광자’라 내리었다. 비는 비문이 새겨진 몸돌이 파괴되어 일부 조각만이 남아 있으며, 거북받침 위에 머릿돌만 얹혀져 있는 상태이다.","a":"곡성 태안사 광자대사탑비","c":"보물","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618975.jpg"},{"q":"○○○은 희릉(禧陵), 효릉(孝陵), 예릉(睿陵)의 3기의 능으로 구성되어 있다. 중종 계비 장경왕후의 무덤인 희릉이 처음 들어선 이후 인종과 인종비 인성왕후의 무덤 효릉, 철종과 철종비 철인왕후의 무덤인 예릉이 들어서면서 ○○○이란 명칭으로 불리게 되었다. ○○○에는 3기의 왕릉 이외에도 3기의 원과 1묘(회묘), 왕자·공주·후궁 등의 묘 46기, 태실54기가 자리 잡고 있다. 1645년(인조 23) 소현세자가 죽자 소현세자를 이곳에 안장하고 소현묘(昭顯廟)라고 칭하였으나 1870년(고종 7)에는 소경원(昭慶園)으로 개호하였다.","a":"고양 서삼릉","c":"사적","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625595.jpg"},{"q":"절에 행사가 있을 때, 그 입구에는 당이라는 깃발을 달아두는데, 이 깃발을 달아두는 장대를 당간이라 하며, 이를 양쪽에서 지탱해 주는 두 기둥을 당간지주라 한다. 당간이 서 있는 ○○시 상당구 남문로는 예전에 용두사라는 절이 자리잡고 있던 곳이다. 용두사는 고려 광종 13년(962)에 창건되었으나 고려말의 잦은 전쟁과 난으로 인해 폐허가 되었고, 절이 있던 터는 현재 ○○시내의 가장 번화한 거리로 변하였다. 이 당간은 밑받침돌과 이를 버티고 있는 두 기둥이 온전히 남아 예전의 모습을 잘 간직하고 있다.","a":"청주 용두사지 철당간","c":"국보","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612150.jpg"},{"q":"이 ○○은 전형적인 농촌마을에 자리잡고 있으며, 수목이 우거진 낮은 언덕을 배경으로 하여 남쪽을 바라보고 자리잡고 있다. 유래에 대해서는 자세하게 전해지지 않으며, 현재 소유자의 8대조가 매입한 건물로 ○○○이란 당호는 7대조 임노운(林魯運)의 호에서 따온 것이라 한다. 건물은 ‘ㅁ’자형으로 앞면에 사랑채와 대문간채가 ‘ㅡ’자형으로 되어 있고, 뒤에는 ‘ㄷ’자형의 안채가 붙어 있다. 큰사랑방은 접객 및 가장의 거처로 뒷벽에는 벽감*을 달아내어 선조의 위패를 모셨고, 작은사랑은 맏아들의 거처이자 제례를 지내는 공간으로 사용하였다.","a":"예천 물체당 고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635310.jpg"},{"q":"○○○ 1948년, 장실 1921년, 우물 1921년, 보호각 1948년 무렵 건립 ○○○은 ○○○ 교주 이상룡(李象龍)의 사저(私邸)였으나, 1940년에 벼락으로 모두 타 버린 뒤 1948년에 현재의 건물이 다시 세워졌다. 이 건물 안에는 ○○○ 경전과 금강경탑 다라니 원판 등 관련 기록물 등이 보관되어 있다. 왼쪽에 있는 장실은 교주의 거처로 사용하였던 곳으로, ○○○ 본부 건물 중에서 가장 오래되었다. 대청 다락방에는 미륵불을 봉안하고 있고, 부엌에는 조왕단이 마련되어 있다.","a":"대전 수운교 용호당","c":"국가등록문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667971.jpg"},{"q":"청룡사는 언제 창건되었는지 뚜렷하게 알 수 없고, 현재 절의 옛모습을 짐작해 볼 방법이 없다. 옛터에는 ○○과 함께 보각국사의 사리탑과 탑비만이 서 있을 뿐이며, 현재의 청룡사는 옛터의 북쪽에 자리잡아 오늘에 이르고 있다. 이 ○○은 보각국사의 명복을 빌어 주기 위해 그의 사리탑 앞에 세워진 것으로, 불을 밝혀두는 화사석(火舍石)을 중심으로 아래에는 이를 받쳐주는 3단의 받침을 두고, 위로는 지붕돌과 머리장식을 얹었다. 3단의 받침 가운데 아래받침돌은 앞을 향해 엎드려 있는 ○○를 조각하였는데, 이 때문에 ○○○○이라 부른다.","a":"충주 청룡사지 보각국사탑 앞 사자 석등","c":"보물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617103.jpg"},{"q":"『○○○○○』은 법어(法語), 즉 부처님의 말씀이나 가르침을 적어놓은 것으로 승려들의 수행에 있어 길잡이 구실을 하며, 우리나라에서는 조선시대에 널리 유통되었다. 원나라 ○○○○ 덕이(德異)의 법어 6편과 고려 나옹화상 혜근(慧勤)의 법어 1편을 1책으로 묶은 것이다. ○○○○ 덕이는 고려의 혜감국사 만항(萬恒), 보감국사 혼구(混丘)와 깊은 교류가 있던 인물로, 고려말이후 한국 불교계에 커다란 영향을 끼쳤다.","a":"몽산화상법어약록(언해)(1984-3)","c":"보물","nc":"","r":"서울특별시","s":"동대문구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613873.jpg"},{"q":"선비들이 모여서 학문을 닦고 제사를 지내던 곳이다. 선조 23년(1590)에 하서 김인후(1510∼1560)를 추모하기 위해서 그의 고향인 기산리에 세워졌다. 1597년 정유재란으로 불타 없어졌으나 인조 2년(1624)에 다시 지었다. 현종 3년(1662)에 임금께서 ‘○○○○’이라고 쓴 현판을 직접 내려보내 주셨으며, 1672년에 지금의 자리로 옮겨 세웠다. 공부하는 곳을 앞쪽에, 제사지내는 곳을 뒤쪽에 배치한 전학후묘(前學後廟)의 형태로서 휴식처가 되는 확연루를 시작으로 수업을 받는 청절당, 그 뒤에 학생들이 생활하는 공간인 동재와 서재가 자리잡고 있다.","a":"장성 필암서원","c":"사적","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627082.jpg"},{"q":"당간은 사찰에서 불교의식이 있을 때 달던 당(幢)이라는 기를 달던 깃대를 말하며, ○○○○는 이 당간을 양쪽에서 지탱시켜주는 두 돌기둥을 이른다. 이 ○○○○는 망덕사터 서쪽에 65㎝ 간격으로 서로 마주보고 서 있다. 표면에 아무런 조각과 장식을 두지 않는 대신, 지주 바깥면의 모서리를 윗부분부터 줄어들게 하여 장식적인 효과를 내었다. 기둥머리는 안쪽 측면에서 바깥면으로 내려오면서 곡선을 그리며 외부로 6㎝쯤 깎여져 경사를 이루고 있고, 안쪽 윗면에 당간을 고정시키기 위한 네모난 홈을 만들었다. 각 면에 비록 조각은 없으나 소박하고 웅장한 기풍을 나타내고 있다.","a":"경주 망덕사지 당간지주","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620192.jpg"},{"q":"경상북도 ○○군 월항면 대산1리의 ○○○○은 조선 세종때 진주목사를 역임한 이우(李友)가 입향(入鄕)하여 거주한때로부터 570여년을 내려오면서 성산이씨가 집성하여 살고있는 전통깊은 마을이다. 경상북도 문화유산으로 지정된 건축물이 9동에 이르고 있으며, 건축물의 대부분이 18세기 후반에서 19세기 초반에 걸쳐 건립되었으나, 전체적인 마을구성이 풍수에 따른 전통적인 모습을 보여주고 있을뿐만 아니라 상류주택과 서민주택의 배치 및 평면도 지역적인 특성을 잘 나타내고 있는 점 등으로 볼 때 국가유산적 가치가 충분하다.","a":"성주 한개마을","c":"국가민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635656.jpg"},{"q":"영암사터에 세워진 통일신라시대의 ○○으로, 1933년경 일본인들이 불법으로 가져가려는 것을 마을 사람들이 막아 면사무소에 보관하였다가 1959년 절터에 암자를 세우고 원래의 자리로 옮겨 놓았다. ○○은 일반적으로 불을 밝혀두는 화사석(火舍石)을 중심으로 하여, 아래로는 이를 받치기 위한 3단의 받침을 두고, 위로는 지붕돌을 얹었다. 이 ○○은 사자를 배치한 가운데받침돌을 제외한 각 부분이 모두 통일신라시대의 기본형태인 8각으로 이루어져 있다. 아래받침돌에는 연꽃모양이 조각되었고 그 위로 사자 두 마리가 가슴을 맞대고 서 있다.","a":"합천 영암사지 쌍사자 석등","c":"보물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622499.jpg"},{"q":"근대문명의 기반이 된 전기의 생산 및 공급과 관련하여 일제강점기 소규모 전기회사들의 합병및 해방 후 한국전력으로 이어지는 역사를 보여주는 건축물로서 역사적 가치를 갖고 있고, 모더니즘 경향의 외관과 계단실 등의 처리가 특징적이다.","a":"군산 구 남조선전기주식회사","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018081416534700.jpg"},{"q":"○○○은 본관이 전주(全州)로 1682년 춘당대시에 병과로 급제하였으며 동래부사, 해주목사, 황해도관찰사, 충청감사 등을 역임한 인물이다. <○○○○○>은 높은 오사모에 녹색 단령을 입고 좌안칠분면의 자세로 교의에 앉은 모습이며 배경은 없다. 얼굴은 가는 선묘를 사용했으며 홍조를 표현하고 명암을 살짝 가했다. 육리문은 없으며 수염이 길고 구불거리게 묘사되었다. 단령은 비교적 가늘고 짙지 않은 먹선으로 윤곽과 의습선을 표현하였고 명암을 조금씩 가했다. 쌍학흉배는 밝은 녹색을 바탕으로 단정학과 오색구름을 세필로 화려하게 그렸고, 삽화금대도 정교하게 묘사하였다.","a":"이덕성 초상 및 관련 자료 일괄","c":"보물","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615116.jpg"},{"q":"『홍치십사년신유○○○○』은 연산군 7년(1501)에 시행한 생원·진사의 합격자 명부이다. 진사시 일소(一所)의 주시관(主試官)은 우참찬 유순(柳洵)과 호조참판 김심(金諶), 이조정랑 남곤(南袞) 등 6명이고, 이소(二所)의 주시관은 대사헌 성현(成俔) 등 6명이다. 생원시의 장원은 이수정(李守貞)이고, 진사시의 장원은 김안국(金安國)이었다. 이 책에 수록된 인물중 시관이었던 남곤(南袞)과 진사방의 1등 5인중 한 명인 김안로(金安老)의 성명에는 사마시 합격자 발표 이후에 죄인이 된 관계로 모두 먹으로 칠해져 있다.","a":"사마방목","c":"보물","nc":"","r":"대구광역시","s":"달서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615295.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하며, 부처가 되는 길이 누구에게나 열려 있다는 것을 중요사상으로 하고 있다. ○○○○○은 천태종의 근본경전으로 화엄종과 함께 우리나라 불교사상 확립에 크게 영향을 끼쳤다. ○○○○○, 3(白紙墨書妙法蓮華經 卷一, 三)은 흰종이에 먹으로 직접 글씨를 쓴 것으로, 전체 ○○∼7중에서 ○○과 권3이 남아있다. 각 권은 병풍처럼 펼쳐서 볼 수 있는 형태로 되어있으며, 접었을 때의 크기는 ○○이 세로 37.5㎝, 가로 13.5㎝ 이고 권3이 세로 34.7㎝, 가로 12.5㎝이다.","a":"백지묵서 묘법연화경 권1, 3","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620740.jpg"},{"q":"○○○○○은 풍산 유씨의 동족마을로 빼어난 자연경관과 민속·유교 전통을 잘 유지하고 있는 조선시대 양반촌이다. 이 건물은 퇴계 선생의 제자로 원주목사를 지낸 겸암 유운룡 선생(1539∼1601)이 서재로 사용하던 집이다. 조선 선조 16년(1583)경에 지었다고 하며 ○○○○ 북촌의 서북편 경암정과 부용대를 바라볼 수 있는 곳에 자리잡고 있다. 집 이름은 부용대 절벽 아래 깊은 곳을 ‘빈연’이라 부른데서 따왔다고 한다. 앞면 3칸·옆면 2칸 크기로 지붕은 옆면에서 볼 때 여덟 팔'(八)'자 모양과 비슷한 팔작지붕이다.","a":"안동 하회마을 빈연정사","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635045.jpg"},{"q":"1974년 충청남도 ○○시 ○○면 송정리의 한 절터에서 출토된 보살상으로, 높이는 25㎝이며, 현재 국립○○박물관에 소장되어 있다. 머리에는 삼면보관(三面寶冠)을 쓰고 있는데, 가운데에 작은 부처가 표현되어 있어 관음보살을 형상화한 것임을 알 수 있다. 이마는 머리카락이 반쯤 내려와 덮고 있으며, 양 옆으로 땋은 머리는 귀를 덮고 어깨까지 길게 내려왔다. 4각형에 가까운 얼굴은 눈·코·입을 큼직하고 시원스럽게 표현했으며, 입가에는 약간의 미소를 머금고 있다.","a":"공주 의당 금동보살입상","c":"국보","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612301.jpg"},{"q":"대적광전을 중심으로 하여 동·서쪽에 서 있는 쌍탑으로, 신라 헌안왕 3년(859)에 도선국사가 세웠다는 설이 전해온다. 앞 뜰이 좁아서 탑과 법당과의 거리가 가깝다. 동탑은 단층의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로 기단의 각 면에는 모서리기둥을 얕게 새겼다. 탑신부에서는 1층 몸돌이 위가 좁고 밑이 넓은 독특한 형태를 보이고 있는데, 각 면에는 4각형의 감실(龕室:불상을 모시는 방)을 두고 그 안에 여래좌상을 도드라지게 새겼다. 2·3층의 몸돌에는 각 모서리 마다 기둥 모양을 새겨 놓았다. 지붕돌은 얇고 넓으며, 받침은 4단으로 구성되어 있다.","a":"김천 청암사 수도암 동·서 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620699.jpg"},{"q":"조선 중기의 유명한 유학자인 ○○ 선생의 유적지이다. ○○ 선생은 많은 벼슬이 내려졌으나 모두 거절하고, 학문연구와 후진양성에 평생을 보냈다. ○○○○은 두 곳으로 나뉘는데 사리(絲里)에는 산천재, 별묘, 신도비, 묘비가 있고, 원리(院里)에는 덕천서원과 세심정이 있다. 산천재는 선생이 학문을 닦고 연구하던 곳으로 명종 16년(1561)에 세웠고, 순조 18년(1818)에 고쳐졌다. 규모는 앞면 2칸, 옆면 2칸이다. 덕천서원은 선조 9년(1576)에 세웠고, 앞면 5칸, 옆면 2칸의 현재 건물은 1926년에 고쳐 지은 것이다.","a":"산청 조식 유적","c":"사적","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628316.jpg"},{"q":"『○○○○○』은 선조~광해군 때의 명필이던 남창(南窓) ○○○이 1614년에 북애(北崖) 이증(李增, 1525~1600)의 절구와 율시 9편을 행서로 필사한 것이다. 이증은 한산이씨로 예조판서로서 아천군(鵞川君)에 봉해지고 의간공(懿簡公)에 추증되었다. 이에 관해서는 말미의 제사(題辭)에 그 사연이 적혀 있는데, ○○○이 이증의 아들 만사(晩沙) 이경함(李慶涵,1553~1627)과 교분이 있어 필사에 응하였던 것이다.","a":"김현성 필적","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616160.jpg"},{"q":"『○○○○○』는 당나라의 법장(643∼712)이『대승기신론』을 해석한 주석서로서 고려후기에 간행된 목판본으로 上下 2권2책이다. 책머리에는 ‘○○○○○’의 권수제와 그 아래에 소자로 ‘병서(幷序)’라 기재되어 있고, 다음 행에 ‘서대원사사문법장술(西大原寺沙門法藏述)’이라는 저자 사항이 있다. 판식을 보면 중앙의 판심에 위쪽에만 가느다란 흑 어미가 보이고 판심제 ‘의기(義記)’ 와 권·장차가 기록되어 있고, 사주는 단변이고, 계선이 없고, 1면은 9행 20자 배자되어 있다. 고려후기에 간행된 판본에서 흔히 보이는 판식의 특징이 나타나 있다.","a":"대승기신론의기 권상, 하","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616182.jpg"},{"q":"1950년대 강원특별자치도 지역 성당 건축의 전형을 보여주는 건물로 외관의 뾰족한 종탑과 지붕 장식, 첨두형 아치 창호, 부축벽을 이용한 입면구성 및 내부의 정교한 몰딩구성 등 의장기법에서 보존가치가 높다.","a":"강릉 임당동성당","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668453.jpg"},{"q":"서울시 광진구 아차산(해발 285m)일대에 있는 삼국시대 산성이다. 성 전체 길이는 1,125m이며, 성벽의 높이는 평균 10m 정도이다. 동·서·남쪽에 문이 있던 흔적과 물길이 남아있고, 문 앞을 가려 보호하는 곡성이 남아있다. 그 밖에 여러 건물터가 남아있는데, 많은 토기와 기와조각이 수습되었다. ○○○○에는 2가지 슬픈 역사가 전해온다.","a":"아차산성","c":"사적","nc":"","r":"서울특별시","s":"광진구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624739.jpg"},{"q":"○○ 벽도산의 서쪽을 향한 바위에 삼존불(三尊佛)을 조각한 마애불(磨崖佛)이다. 이 불상은 가까운 곳에 있는 ○○ 굴불사지 석조사면불상(보물)의 양식을 그대로 계승하고 있는 통일신라시대의 대표적인 작품으로 서방 극락세계를 다스린다는 아미타불을 가운데에 새기고, 양쪽에 관음보살과 대세지보살을 새겼다. 아미타불의 머리는 아주 큼직하며, 정수리 부근에는 상투 모양의 머리(육계)가 낮게 있어 모자를 쓴 듯한데, 이는 굴불사지의 석조사면불상과 같은 양식이다. 얼굴은 볼에 살이 올라서 매우 풍만하게 보이며 미소가 남아 있다.","a":"경주 율동 마애여래삼존입상","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620270.jpg"},{"q":"철화○○는 ○○의 표면에 산화철이 함유된 자토로 그림을 그리고 ○○유를 씌워 구운 것으로, 기형과 문양이 북송(北宋) 자주요(磁州窯)와 닮은 점이 많다고 알려져 있다. 유약은 대부분 산화번조(酸化燔造)되어 황갈색을 띠는 경우가 많으며, 문양은 선이 굵고 대담하게 표현하여 매우 활기차 보인다. 이 ○○은 구연이 평평하게 벌어지고 둥근 어깨와 몸통의 선이 거의 일직선으로 내려가 굽에 연결되는데, 이러한 형태를 중국 ○○의 특징으로 보는 관점에서 아직 고려화가 덜된 초기적인 형태라는 평가를 받고 있다.","a":"청자 철화초충조문 매병","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614785.jpg"},{"q":"○○○는 신라 신문왕 10년(690)에 창건되었고, 조선 중기까지만 해도 50여채의 건물과 12암자 등을 갖춘 큰 절이었다고 전해진다. 탑은 절 안의 법당 앞에 세워져 있다. 이 탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 쌓아올린 형식으로 신라석탑의 일반적인 양식을 따르고 있다. 넓고 긴 돌로 탑의 구역을 마련하고, 바닥돌은 사방으로 하나씩 4장의 돌을 붙여서 짰다. 아래층 기단의 맨윗돌은 꽤 두꺼운 편이며, 돌의 가운데에 2단의 괴임돌을 두었다.","a":"경산 불굴사 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620922.jpg"},{"q":"이 범종은 일본인 다카하라 히미코 여사가 선대로부터 물려받아 소장해 오던 중 1999년 11월 국립문화유산연구원을 통해 기증·반환한 것으로, 종을 매다는 용뉴 부분의 훼손이 있기는 하나 거의 완전한 형태를 갖추고 있다. 종의 윗면은 수평에 가까우며, 어깨부분인 상대와 맨아래 부분인 하대에는 띠를 돌리고 그 안쪽으로 반원무늬와 덩굴무늬가 장식되어 있다. 상대와 연결된 사다리꼴 모양의 연곽 테두리에도 덩굴무늬를 얕게 조각하였으며, 연곽 안에는 작은 꽃받침을 갖춘 연뢰(蓮蕾)가 돌출되어 있다.","a":"전 낙수정 동종","c":"보물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618689.jpg"},{"q":"○○○○는 전면에서 볼 때 ○○○이 좌측에 자리하고 우측에 ○○○이 위치하는 좌묘후학의 배치법을 지니고 있다. ○○○은 다포형식으로 우리나라 향교 가운데 문묘, 익산향교 ○○○ 외에 그 예가 드문 다포형식으로 조선중기의 수법들이 잘 보존되고 있다. 특히 다포건축이면서 천장을 설치하지 않았고, 다포이면서도 유교건축에 맞게 내부구성을 매우 간략하게 처리한 점 등은 주목된다. ○○○은 전면 퇴칸을 두고 가운데 마루가 깔린 전형적인 중당협실형의 평면구성이다. 온돌방 상부는 다락을 설치하여 수장공간으로 활용한 듯하며 창호의 구성에서 고식들이 남아있다.","a":"성주향교 대성전 및 명륜당","c":"보물","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622258.jpg"},{"q":"○○○○○은 줄여서 ‘화엄경’이라고 부르기도 하며, 부처와 중생이 둘이 아니라 하나라는 것을 중심사상으로 하고 있다. 화엄종의 근본경전으로 법화경과 함께 한국 불교사상 확립에 중요한 영향을 끼친 경전이다. ○○○○○책은 당의 실차난타가 번역한『화엄경』○○ 80권 가운데 권5와 권6의 내용을 옮겨 적은 것으로, 검푸른 빛이 도는 종이에 은가루를 이용해 글씨를 썼다. 병풍처럼 펼쳐서 볼 수 있는 형태이며, 접었을 때의 크기는 세로 31.1㎝, 가로 10.5㎝이다.","a":"감지은니 대방광불화엄경 주본 권5~6","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613816.jpg"},{"q":"신라 제44대 민애왕(838∼839)의 무덤으로 높이 3.8m, 지름 12.5m이다. 여러차례 도굴을 당하였으나 1984년 9월에 국립○○박물관에서 무덤과 주변을 발굴조사하여 규모를 밝히고, 현재의 모습으로 정비하였다. 조사결과에 의하면 무덤 밑부분 바깥쪽으로 일정한 간격의 12개의 구멍이 있었다. 구멍에는 곱돌로 만든 12마리 동물의 얼굴에 사람의 모습을 하고 있는 십이지신상을 하나씩 묻었다. 조사 당시에는 쥐·소·닭·돼지 4개만 발견되었다. 나머지는 무덤의 외부받침석이 만들어질 때 파손되고, 없어진 것으로 추정되었다.","a":"경주 전 민애왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627819.jpg"},{"q":"진평왕 9년(587)에 세운 ○○○에 모셔진 보살상으로 유리상자를 씌워 모셔 놓았다. 불상 속에서 나온 관음보살원문(觀音菩薩願文)의 기록으로 미루어보아 조선 중종 11년(1516) 불상에 새로 금을 칠하기 이전인 15세기 후반에 만들어진 것으로 추정된다. 머리에는 화려한 관을 쓰고 있으며, 양쪽 귀에 걸친 머리카락은 여러 가닥으로 흩어져 어깨를 덮고 있다. 귀는 약간 짧고 목에는 3줄로 새겨진 삼도(三道)가 명확하게 있다. 양 어깨를 감싸고 입은 옷은 팔에 걸쳐 내려 무릎을 덮고 있으며, 전신에 걸쳐 화려한 구슬 장식이 있다.","a":"문경 대승사 금동관음보살좌상","c":"보물","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621922.jpg"},{"q":"『○○○○○』는 조선 왕조 목조(穆祖)로부터 태종(太宗)까지 6대의 사적(事跡)과 그에 대응되는 중국 역대 제왕의 사적(事蹟)을 대구로 하여 읊은 노래와 그 주석을 실은 책이다. 125장의 한글가사와 그에 해당하는 한시(漢詩)를 본문으로 하고, 각장마다 주해를 붙인 체재로 되어 있다. 본문은 조선의 건국이 천명에 의한 것임과 후대 임금에게 경계하는 내용을 담고 있다. 편찬하고 간행한 목적과 그 경위에 대해서는 책에 함께 실려 있는 1445년(세종 27) 정인지(鄭麟趾)의 서문과 권제(權踶) 등의 전문, 그리고 1447년의 최항(崔恒)의 발문에 자세하게 서술되어 있다.","a":"용비어천가 권3, 4","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614862.jpg"},{"q":"지리산 자락에 있는 ○○○는 신라 진흥왕 5년(544)에 연기조사(緣起祖師)가 세운 절로, 호남 제일의 사찰답게 많은 부속 건물과 국보 ○○○○○ 각황전 앞 석등, 보물 ○○○○○ 동 오층석탑, 보물 ○○○○○ 서 오층석탑, 보물 ○○○○○ 원통전 앞 사자탑 등의 중요한 유물들이 전해온다. 탑은 소나무 숲으로 둘러싸인 절 서북쪽의 높은 대지에 석등과 마주보고 서 있으며, 2단의 기단(基壇)위에 3층의 탑신(塔身)을 올린 형태이다. 아래층 기단의 각 면에는 천인상(天人像)을 도드라지게 새겼는데, 악기와 꽃을 받치고 춤추며 찬미하는 등의 다양한 모습이 그려져 있다.","a":"구례 화엄사 사사자 삼층석탑","c":"국보","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612422.jpg"},{"q":"○○○는 법주사에 딸린 작은 절이다. 통일신라 혜공왕 11년(775)에 진표율사가 지었다고 하는데 편안한 마음으로 제자를 길렀다 해서 ○○○라는 이름을 붙였다고 한다. 고려 충숙왕 12년(1325)에 원명국사가 다시 짓고 인조 4년(1626)에 송암대사가 수리하였다고 하며 한말에 고쳐 세워 오늘에 이르고 있다. 지금 있는 ○○○은 확실하게 지은 시기를 알 수는 없지만, 1979년 해체·수리 때 발견한 기와의 기록으로 미루어 조선 인조 때의 건물로 보인다.","a":"청주 안심사 대웅전","c":"보물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617110.jpg"},{"q":"○○ 이진래 ○○의 서쪽에 자리잡고 있는 집으로 서쪽 담장을 따라 들어가면 조그만 초가대문이 나타나고 그 서쪽 대나무숲 가운데 크지 않은 사랑채가 있다. 사랑마당 서쪽에는 행랑채가 있고, 사랑채 뒤에 안채가 있으며, 안마당의 서쪽에 곳간채가 있다. 동쪽에는 곳간채가 등지고 있어서 장독대만을 배치하였다. 남아있는 기록으로 보아 1891년에 지었음을 알 수 있으나 각각의 건물이 지어진 연대는 서로 다른 것으로 보인다. 안채, 사랑채, 곳간채가 ㄷ자형으로 배치되어 있는 집이다. 안채는 초가집으로 서쪽부터 툇마루가 있고 그 옆의 앞쪽에는 작은방, 뒤쪽에는 뒷방이 있다.","a":"보성 이준회 고택","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634650.jpg"},{"q":"○○○○○ 일대의 구릉 위에 있는 가야 때 무덤들이다. 여러 차례에 걸친 발굴조사로 40여 기의 무덤이 확인되었으나, 대부분의 무덤은 아직도 땅 밑에 남아있다. 무덤의 형태는 땅을 파서 넓은 방을 만들고 나무관을 넣은 덧널무덤(토광목곽묘), 땅속에 네모난 돌로 벽을 쌓고 천장을 덮어 만든 구덩이식 돌방무덤(수혈식석실묘), 땅속에 시체를 바로 묻는 널무덤을 비롯해 여러 가지 형식의 무덤들이 있다. 이 무덤들에는 도굴되지 않은 큰 무덤이 많아 2000점 이상의 다양한 유물이 출토되었다.","a":"부산 복천동 고분군","c":"사적","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625137.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하며 천태종의 근본경전으로, 부처가 되는 길이 누구에게나 열려있다는 것을 기본사상으로 하고 있다. 화엄경과 함께 한국 불교사상 확립에 크게 영향을 끼쳤으며, 우리나라에서 유통된 불교경전 가운데 가장 많이 간행되었다. 이 책은 후진의 구마라습이 한문으로 번역한 것을 문종 1년(1451)에 태종의 빈(嬪)인 명빈 김씨가 태종, 세종, 세종의 비인 소헌왕후, 그리고 부모의 명복을 빌기 위해 간행한 것이다. 목판에 새겨 닥종이에 찍은 것으로, 권 제5 ·6·7의 3권이 1책으로 되어있다.","a":"묘법연화경 권5~7(1991)","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614582.jpg"},{"q":"한센인들이 직접 공사에 참여하여 지은 벽돌조 성당 건축물로, 그들의 육체적·정신적 아픔의 치유를 위한 영적 장소가 되었던 건물이며, ○○○라는 지역적 특징 속에서 한센인과 함께 한 역사적 가치가 있음","a":"고흥 소록도 병사성당","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2016061517383400.JPG"},{"q":"○○ 송화산 동쪽 구릉 위에 자리잡고 있는 신라 장군 ○○○의 무덤이다. ○○○은 삼국통일에 중심 역할을 한 사람으로, 김춘추(후에 태종무열왕)와 혈연관계를 맺으며 정치적 발판을 마련하였고, 여러 전투와 내란에서 큰 공을 세웠다. 660년에 귀족회의의 우두머리인 상대등이 되어 백제를 멸망시켰으며, 668년에는 신라군의 총사령관인 대총관(大摠管)이 되어 고구려를 멸망시키고 당의 침략을 막아 신라 삼국통일의 일등공신이 되었다. 무덤은 지름이 30m에 달하는 커다란 규모이며, 봉분은 둥근 모양이다.","a":"경주 김유신묘","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627559.jpg"},{"q":"조선후기 함경도(咸鏡道) 지역의 군현 지도를 모은 지도첩으로, 채색필사본이다. 18세기 영조(英祖) 연간에 비변사(備邊司)에서 제작한 것으로 추정되며, 눈금이 있는 방안지(方眼紙)에 지도가 그려져 있다. 본 지도첩은 5책으로 구성되어 있는데, 제1~4책에는 함경도 내 18개 부(府)·군(郡)·현(縣)의 지도가 실려 있는데, 갑산·단천·북청·삼수·이성 등 5개 군현의 지도는 빠져 있다. 제5책에는「함경도지도」·「함경북도지도」·「함경남도지도」가 수록되어 있다.","a":"함경도전도","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614919.jpg"},{"q":"이 마을의 ○○은 대개 토석담으로 담 하부는 방형에 가까운 큰 자연석을 사용하여 대부분 메쌓기 방식으로 쌓았다. 그 위에는 하부의 자연석보다 작은 20cm내외의 돌을 담 안팎에 사용하여 진흙과 교대로 쌓아 올렸고, 대부분 ○○ 상부에는 한식기와를 이었다. 활처럼 휘어진 전통○○길이 전통고가와 어우러져 고즈넉하고 아늑한 느낌을 준다","a":"거창 황산마을 옛 담장","c":"국가등록문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669473.jpg"},{"q":"○○○○○내 발견 유물일괄은 1970년 기울어졌던 ○○○○○을 해체 복원할 때 발견된 것으로 모두 9종 12점이다. 이들 일괄유물은 대체로 10∼11세기 경에 제작된 유물들이어서 석탑이 건립될 때 함께 납입된 것으로 추정된다. 일괄 유물로는 은제도금여래입상과 청동사리외합을 비롯하여 은제내합, 호리병 모양의 수정사리병, 금동제 사각향갑, 청동거울, 전신사리경 두루마리, 수라향갑 주머니, 명주보자기 등이 발견되었다. ○○○○○내 발견 유물일괄은 고려시대 초기의 금속공예사의 현황과 불교사상의 변화 연구하는데 중요한 위치를 차지하는 것으로 평가된다.","a":"월정사 팔각구층석탑 사리장엄구","c":"보물","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616929.jpg"},{"q":"1900년에 건립된 제1○○○는 우리나라 최초의 철로인 경인철도 건설시 건립된 한강 최초의 다리다. 6.25전쟁으로 세 교량 모두 폭파된 것을 1957년에 제3○○○를, 1969년에 제1,2○○○를 복구하였다. 일제강점기에 일제의 식민지배와 수탈에 이용된 현장, 6.25 전란의 고난을 상징, 산업 경제발전과 교통혁명의 상징이다.","a":"서울 한강철도교","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667058.jpg"},{"q":"고려 ○○의 전성기인 12세기경에 만들어진 ○○○○○로, 높이 17㎝, 밑지름 10.3㎝, 굽지름 9.9㎝의 크기이다. 연꽃 위에 앉아있는 거북을 형상화했는데 물을 넣는 수구(水口), 물을 따르는 부리, 몸통, 손잡이로 구성되어 있다. 얼굴 모습은 거북이라기보다 오히려 용에 가깝다. 이마 위의 뿔과 수염, 갈기, 눈, 이빨, 비늘 등이 모두 정교하면서도 부드럽게 숙련된 솜씨로 만들어졌다. 두 눈의 눈동자는 검은색 안료를 사용하여 점을 찍었으며, 아래와 위의 이빨은 가지런하게 표현되어 있다. 목과 앞 가슴의 비늘은 음각했으며, 발톱은 실감나도록 양각해 놓았다.","a":"청자 구룡형 주전자","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611514.jpg"},{"q":"○○○○은 조선 선조 23년(1590)에 창건되고, 현종 3년(1662)에 왕에게서 사액을 받은 서원이다. 여기에는 김인후(1510∼1560)와 양자징(1523∼1594) 두 분의 위패를 모시고 있다. 김인후는 조선 중기의 유학자이자 문신으로, 1540년 문과에 급제하여 벼슬길에 올랐다. 을사사화가 일어나자 병을 핑계삼아 나아가지 않고 고향인 장성으로 돌아갔다. 시와 문장에 뛰어나 10여권의 시문집을 남겼고, 그의 성리학 이론은 유학사에 있어서 중요한 위치를 차지한다.","a":"필암서원 문적 일괄","c":"보물","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619302.jpg"},{"q":"­이 건물은 근대 한옥 변천사적으로 가치가 높고 1920년대 ○○시장 전경 사진중에 현존하는 유일한 건물이다. 건축당시 ‘남일당(南一堂) 한○○’으로 사용되었으며, 이후 건축주가 바뀌면서 ‘○○○○○ 대○○’으로 상호를 변경하여 운영되었고, 현재는 후손이 관리하고 있다.","a":"강경 구 연수당 건재 약방","c":"국가등록문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668547.jpg"},{"q":"ㅇ ○○○○○은 총 4기의 분구묘(墳丘墓)로 이루어져 있으며, 이번에 사적으로 지정된 고분은 발굴조사가 완료된 1호분과 정밀지표조사, 정밀실측이 이루어진 2호분이다. 서로 맞닿아 있는 1호분과 2호분은 보존상태가 양호하고 육안으로도 그 형태가 뚜렷이 확인된다. 특히, 동서 70m, 남북 52m, 최고 높이 9m에 달하는 1호분은 전북 지역 최대 규모의 분구묘로 꼽힌다.","a":"고창 봉덕리 고분군","c":"사적","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2754583.jpg"},{"q":"조선의 서북지방과 중국의 만주 일대를 그린 관방지도(關防地圖)로, 18세기 중엽에 제작되었다. 청나라의 침입에 대한 방어를 목적으로 제작된 군사 지도로, 제목의 ‘피아(彼我)’는 중국 청나라와 조선을 의미한다. 지도는 백두산(白頭山)과 압록강·두만강을 중심으로 만주 흑룡강부터 서쪽 산해관(山海關)에 이르는 지역을 포괄하고 있다. 조선의 북부지방의 하계망과 산맥 및 주요 산, 군현, 도로망과 주요지점 등이 자세하게 묘사되어 있고, 특히, 압록강과 두만강 국경지대의 세밀한 교통망과 군사요지가 잘 나타나 있다.","a":"서북피아양계만리일람지도(2008)","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614903.jpg"},{"q":"○○ 궁남지(宮南池) 동쪽에 위치한 ○○○은 백제 이궁지(離宮址)인 망해정(望海亭)이 있었다고 전해지고 있는 곳으로서, 지난 '86년에 충남대박물관의 발굴조사 결과 건물지 초석과 와편들이 다량 출토된 유적지이다. 2000. 5월부터 8월까지 국립○○문화유산연구소가 실시한 추가 발굴조사한 결과에서도 백제에서 조선시대에 걸친 건물지, 분묘, 목책시설 등 다양한 유구 및 유물(건물지5, 석곽묘11기, 토광묘<민묘>18기, 석축시설, 출토유물 50점 등)이 확인되어 이 일대가 백제시대 이후 계속적으로 거주지 또는 묘역으로 활용되었음을 알려주는 중요한 유적이다.","a":"부여 화지산 유적","c":"사적","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626673.jpg"},{"q":"석가가 영축산에서 설법하는 장면을 그린 ○○○○○으로, 괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞 뜰에 걸어놓고 예배를 드리는 대형 불교그림이다. 이 괘불은 길이 10.50m, 폭 8.97m로 본존불인 석가불은 중앙에 화면 가득 그리고 석가불 좌우로 문수보살과 보현보살을 배치하였으며, 그 뒤로 다보여래와 아미타여래, 관음보살, 세지보살 등의 4보살이 서 있는 7존 형식구도를 이루고 있다. 각 존상들은 둥근 얼굴에 원만한 체구를 지니며 뺨과 눈자위, 턱밑, 손과 발은 옅은 분홍색으로 처리해 밝아 보인다.","a":"내소사 영산회 괘불탱","c":"보물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618676.jpg"},{"q":"조선 초기에 제작된 ○○○○ 병으로 높이 28㎝, 아가리 지름 5.8㎝, 밑지름 17㎝이다. 이 병은 면상감법으로 이루어진 작품으로, 면상감법이란 청자상감이 ○○○○로 변해가는 과정에서 나온 새로운 장식기법의 하나이다. 몸통에는 힘차면서도 거침없는 솜씨로 덩굴 꽃무늬를 흰색으로 상감하고, 꽃잎과 덩굴 사이에는 선명한 검은 색을 상감하여 흰 면상감의 특이한 효과를 더하고 있다. 담녹색의 투명한 광택이 흐르고 있고, 어두운 회색빛 바탕 흙의 질감 위에 상감 문양이 맑게 어우러져 투시되고 있다. 전체 형태는 몸통이 둥글고 허리가 가늘며, 굽다리가 넓다.","a":"분청사기 상감모란문 매병","c":"보물","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620630.jpg"},{"q":"완양부원군○○○○○는 선조 37년(1604) 10월에 ○○○에게 상장과 훈장을 내린 교서이다. 명주에 두꺼운 선지를 포개 붙여 만든 것으로 가로 230cm, 세로 36cm의 두루마리이며, 앞뒤 공백인 부분까지의 길이는 총 298.3cm이다. 임진왜란 평정에 큰 공훈을 세운 사람들에게 내려진 훈호는 호성(扈聖) ·선무(宣武) 두 가지로 나누고 있는데, 임진왜란 당시 서울에서 의주까지 시종 왕을 호종한 사람을 ○○○○으로, 왜병을 정벌한 장수들과 원병과 양곡 요청을 위해 명나라에 왕래한 사신을 선무공신으로 책봉하였다.","a":"이충원 호성공신교서","c":"보물","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615879.jpg"},{"q":"○○은 선사시대에 인류가 조개를 먹고 버린 껍데기와 생활쓰레기가 쌓여 이루어진 것으로 조개더미 유적이라고도 하는데 당시의 생활모습을 알 수 있는 유적이다. ○○평야의 중심부에 있는 낮은 구릉에 있고, 구릉의 꼭대기는 평평한 지형을 이루고 있다. 비탈진 곳에 조개더미들이 쌓여있는데 A지구, B지구, C지구라 부른다. 쌓임층은 가장 위에 겉흙층이 있고, 그 아래에 조가비층이 있으며, 바닥에는 부식토층이 깔려 있다.","a":"창원 성산 패총","c":"사적","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628290.jpg"},{"q":"일산역은 1동, 1층 규모로 건축면적 174.48㎡다. 일산역은 경의선로의 역사로 1933년에 건립되었으며, 1933년 10월 21일 영업을 개시하였다. 지붕형태는 일자형 평면에 십자형 박공지붕을 올려놓은 모양으로 정면에서 보이는 박공부위는 비교적 폭이 넓은 반면에 높이는 낮아 1930년대에 건설된 경의선의 다른 역들과 비교된다. 구조는 목조이며 외벽 마감은 철망 모르타르로 변형되어 있다. 일산역 신축으로 간이역은 폐역되었으며, 한국철도공사에서는 역사를 일반인들에 임대 예정인 것으로 알려져 있다.","a":"고양 구 일산역사","c":"국가등록문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668080.jpg"},{"q":"<○○○○○>는 조선시대 공물과 세금 등의 경제를 담당하던 호조 관리들의 계회모임을 그린 것으로, 비단바탕에 가로 59㎝, 세로 121㎝이다. 보통 ○○○의 상단에는 모임의 명칭이 쓰여져 있는데 이 그림은 명칭이 빠져있다. 참석자들은 안홍·이지신·김익 등으로 의관을 바르게 하고 안쪽 가운데 인물을 중심으로 좌우로 둥그렇게 앉아 있는데, 안쪽에서 멀어질수록 인물들을 작게 표현함으로 계원들의 서열을 나타내었다.","a":"호조낭관계회도","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614144.jpg"},{"q":"○○○ 장군은 17세의 어린 나이로 임진왜란 때 권율 장군의 지휘 아래 전쟁에 참가했으며, 무과에 급제한뒤 인조 2년(1624) 이괄의 난을 수습하여 진무공신으로 봉해졌다. 그 후 정묘호란에서 공을 세우고 포도대장, 경상도 절도사 등을 역임했으나 병자호란이 일어나기 몇 개월 전에 병으로 세상을 떠났다. 그는 천문·지리·역술·의술 등 여러 면에 걸쳐 뛰어났으며, 청렴하기로도 이름이 높았다. ○○○ 장군의 ○○들은 서산군 지곡면에 있는 ○○○ 장군의 사당에 보관하고 있었으나, 1975년 도난당하고 2달 만에 다시 찾았는데, 그 때 투구가 없어져 사진만이 남게 되었다.","a":"정충신장군 유품","c":"국가민속문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2023031709592800.jpg"},{"q":"○○○○○는 경상북도 월성군 양북면의 ○○○에 모셔진 조선시대 건칠보살좌상이다. 건칠불이란 나무로 골격을 만든 뒤 삼베를 감고 그 위에 진흙을 바른 다음 속을 빼낸 불상을 말하는데, 우리나라에는 남아 있는 예가 매우 적어 이 불상의 가치가 더욱 크다. 타래머리 위에 보관(寶冠)을 따로 만들어 올렸으며 관 표면에는 덩쿨무늬가 화려하게 새겨져 있다. 얼굴은 둥글고 풍만하며 눈·코·입 등이 단아하게 묘사되어 보살상의 특징있는 얼굴을 만들어 내고 있다. 양 어깨에는 천의(天衣)를 걸치고 있으며, 목에는 3가닥의 장식이 달린 목걸이를 하고 있다.","a":"경주 기림사 건칠보살반가상","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620861.jpg"},{"q":"○○○는 불명산 시루봉 남쪽에 있는 절로 본사인 금산사에 딸린 절이다. 절을 지을 당시의 자세한 기록은 없으나 원효와 의상이 유학하고 돌아와 수도하였다는 기록으로 보아 신라 문무왕 이전에 지은 것으로 보인다. 1981년 해체·수리 때 발견한 기록으로 조선 숙종 37년(1711)까지 여러번에 걸쳐 수리가 있었음을 알 수 있었다. ○○○는 ○○○ 경내에 있는 극락전 정문과 같은 성격의 누이다. 지금 있는 건물은 조선 광해군 3년(1611)에 세운 것으로 그 뒤에도 여러 차례 수리한 건물이다.","a":"완주 화암사 우화루","c":"보물","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618429.jpg"},{"q":"○○ 남산의 북쪽에 있는 신라 산성으로 ‘신라 ○○○○’이라고도 한다. 신라 진평왕 13년(591)에 쌓았다고 전하며, 신라 문무왕 19년(679)에 성을 크게 고쳐 쌓았는데, 지금 성벽이 잘 남아있는 부분은 이때 쌓은 것으로 보인다. 남산 꼭대기를 중심으로 돌로 쌓았으며, 성 안에는 3개의 커다란 창고가 있어 무기와 식량을 저장하고 전쟁에 대비하였다.","a":"경주 남산신성","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627562.jpg"},{"q":"이 상은 윤왕좌(輪王坐)의 보살상으로 금동불로는 규모가 비교적 큰 편이다. 보살상의 세부 표현과 양식은 전반적으로 고려시대의 특징을 잘 계승하고 있으나, 타원형의 양감있는 얼굴모습, 유두를 두드러지게 표현한 점, 몸 전면에 영락이 표현되지 않은 점, 몸을 감고 있는 천의자락의 선이 경직되게 표현된 점 등은 조선전기의 특징으로 여겨진다. 이 보살상은 조선 전반기의 금동상으로서 규모가 큰 편이고 보관 등에 다소 파손된 부분이 있으나 전체적으로 원래의 모습을 잘 보존하고 있다.","a":"해남 대흥사 금동관음보살좌상","c":"보물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619971.jpg"},{"q":"참법이란 경전을 읽으면서 죄를 참회하는 불교의식을 말하며, 서방 극락정토의 아미타불을 대상으로 삼는 것을 미타참법(彌陀懺法)이라고 한다. 이 책은 미타참법의 절차를 수록한 것으로 성종 5년(1474)에 세조비인 정희대왕대비가 성종비인 공혜왕후 한씨의 명복을 빌기 위해 간행한 것이다. 닥종이에 찍은 목판본으로 권6에서 권10까지를 1권의 책으로 엮었으며, 크기는 세로 33.4㎝, 가로 22㎝이다. 책 끝에 있는 김수온의 글을 통해 공혜왕후 한씨뿐만 아니라 선대왕과 왕비들의 명복도 함께 빌기 위해 간행했음을 알 수 있다.","a":"예념미타도량참법 권6~10(1992)","c":"보물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616001.jpg"},{"q":"높은 장대석 기단으로 감싸고 있는 ­전통한식 목조가옥이다. ­조선조 제23대 순조의 부마 창녕위 김병주의 ○○로서, 한일합병 후 김병주의 손자 김석진이 일본의 남작작위를 거절하고 순국자결한 역사적 의미를 가진 건축물이다. 순조의 부마 김병주 ○○로 지어진 부분을 안채로 삼고, 사랑채는 다른 곳에서 이축한 것으로 전해지고 있으며, 한국전쟁시 피폭되어 ○○와 행랑을 다시 지었다.","a":"서울 창녕위궁 재사","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666887.jpg"},{"q":"고려 희종 (재위 : 1204∼1211)의 무덤이다. 희종은 신종의 첫째 아들로 어머니는 정선태후 김씨이며, 부인은 성평왕후 왕씨이다. 1204년 왕위에 올랐고, 최충헌을 제거하려다 실패하여 희종 7년(1211)에 왕의 자리에서 쫓겨나 ○○ 교동으로 갔다. 고종 24년(1237) 57세의 나이로 죽자 낙진궁으로 옮겼으며, 10월에 덕정산 남쪽에서 장례를 지내고 ○○이라 하였다. 조선 현종 때 ○○유수 조복양이 찾아내어 다시 무덤을 쌓았는데, 그 뒤 석물도 부서지고 무너진 무덤을 1974년 손질하여 고쳤다.","a":"강화 석릉","c":"사적","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625295.jpg"},{"q":"○○○ 대웅전(국보)에 모셔져 있는 목조 삼세불좌상 ○○○○○과 연화대좌, 수미단 등이다. 삼세불좌상은 ○○○의 중흥조(中興祖)인 만공(滿空)선사가 전북 남원에 있는 만행산 ‘귀정사(歸淨寺)’로부터 옮겨온 것이라고 한다. 중앙의 석가모니불을 중심으로 오른쪽에는 약사불, 왼쪽에는 아미타불이 자리하고 있다. 석가모니불은 주존으로서 굽어보는 듯한 자세에 당당한 어깨와 넓은 무릎을 하여 안정되어 보인다. 육계의 구분이 불분명한 머리에는 중앙계주와 정상계주가 표현되어 있으며, 네모꼴의 각진 얼굴에는 근엄한 듯 부드러운 미소가 엿보인다.","a":"예산 수덕사 목조석가여래삼불좌상 및 복장유물","c":"보물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618059.jpg"},{"q":"이 책은 당의 반라밀제(般剌密帝)가 번역하고 송나라 계환(戒環)이 주해(註解)한『○○○○○大佛頂如來密因修證了義諸菩薩萬行首楞嚴經』10권 가운데 권1～10으로 15세기 전반에 간행된 판본이다. 이 판본은 권1∼10의 내용을 2책으로 엮었으며, 판심에는 ‘능(楞)’ 권차(卷次), 장차(張次)가 있다. 권두에는 “○○○○○변상(大佛頂首楞嚴經變相)”이란 제목 하에 2장의 변상도가 있고 이어 권1∼10의 말미에 이르기까지 세필의 구결(口訣)이 있으며, 판각이 정교하여 인쇄도 깨끗하다.","a":"대불정여래밀인수증요의제보살만행수능엄경(2009)","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614939.jpg"},{"q":"‘○○○○○’은 5미터가 넘는 대형의 마애상으로 상 전면이 흰색 호분이 칠해져 있어 일반적으로 ‘보도각 백불(普渡閣白佛)’ 또는 ‘백의관음(白衣觀音)으로 불렸다. 이 ○○○○○에 관해서 성현(成俔, 1439-1504년)의 『용재총화(慵齋叢話)』에 정확히 기록하고 있는 것이 확인된다. ○○○○○의 상호(相好)는 사실적이고, 설법인(說法印)의 수인의 형태도 유려하며, 어깨에 드리워진 천의(天衣)와 가슴에 대각선으로 걸쳐있는 넓은 띠주름도 유연하게 흘러 내려 훌륭한 조각 표현을 보여준다.","a":"서울 옥천암 마애보살좌상","c":"보물","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615048.jpg"},{"q":"고려시대 만들어진 ○○○○○로 크기는 높이 20.1㎝, 아가리지름 20.7㎝, 밑지름 14.8㎝이다. 몸통에는 앞뒤로 모란이 한 줄기씩 장식되어 있다. 모란꽃은 잎맥까지도 세세하게 묘사되어 있는데, 몸체의 한 면마다 가득히 큼직한 문양을 넣어 인상적이고 시원한 느낌을 준다. 특히 꽃은 흰색으로 잎은 검은색으로 상감하였는데, 꽃을 중심으로 잎을 좌·우·상·하로 대칭되게 배열하였다. 유약은 맑은 녹색이 감도는 회청색으로 매우 얇고 고르게 칠해져 있다.","a":"청자 상감모란문 항아리","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611517.jpg"},{"q":"○○○는 고려시대의 승려 일연이『삼국유사』를 저술하였던 곳으로, 지금도 절 안에는 3층 석탑을 비롯하여 금당 앞 석등, 석조사천왕상, 원응국사비, 석조여래좌상 등의 문화유산들이 보존되어 있다. 대웅보전 앞에 동·서로 서 있는 이 두 탑은 2단의 기단(基壇)위에 3층의 탑신(塔身)을 올린 모습으로 규모와 양식이 서로 같다. 각 층의 기단에 기둥모양을 본떠 새기고, 특히 윗층 기단에는 8부중상(八部衆像)을 새겨 놓았는데 모두 앉아 있는 모습이다. 탑신은 몸돌과 지붕돌이 각각 하나의 돌로 이루어져 있는데 몸돌은 모서리마다 기둥모양이 새겨져 있다.","a":"청도 운문사 동·서 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621433.jpg"},{"q":"○○는 조선왕조의 왕과 왕비, 그리고 죽은 후 왕으로 추존된 왕과 왕비의 신위를 모시는 사당이다. ○○에는 본래의 건물인 정전과 별도의 사당인 영녕전을 비롯하여 여러 부속건물이 있다. 태조 3년(1394)에 한양으로 도읍을 옮기면서 짓기 시작하여 그 이듬해(태조 4년)에 완성되었다. 태조는 4대(목조, 익조, 도조, 환조)의 추존왕을 정전에 모셨으나, 세종 때 정종이 죽자 모셔둘 신실이 없어 중국 송나라 제도를 따라 세종 3년(1421) 영녕전을 세워 4대 추존왕의 신위를 옮겨 모셨다. 정전과 영녕전은 1592년 임진왜란 때 불에 탄 것을 1608년에 다시 지었다.","a":"종묘","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624572.jpg"},{"q":"소뿔 모양의 잔으로 뿔 끝을 검은색으로 자연스럽게 채색하여 사실성을 강조한, 길이 17㎝, 아가리 지름 5.3㎝의 ○○이다. 원래 이러한 ○○은 삼국시대의 가야, 신라 무덤에서 발견되는 우각형도기배라는 종류의 그릇에서 그 기원을 찾을 수 있다. 그 후 고려 시대에도 청자우각형배와 같은 예가 있어서 아주 오래 전부터 제작되었음을 알 수 있다. 순백의 바탕흙에 묽은 청색을 띠는 ○○유약을 전체에 곱게 칠한 것으로, 광주 번천리, 관음리 가마에서 제작된 것으로 추정된다. 조선 초기의 작품으로는 드물며, 중요한 자료가 된다.","a":"백자 철채 뿔잔","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614431.jpg"},{"q":"○○○○○는 1920년대에 건립된 것으로 추정되는 목조 4동, 조적조 2동으로 구성되어 있고, 건축물의 외벽 및 내벽 일부와 지붕 트러스, 차양 등이 잘 남아 있으며, 측벽상부의 고창, 지붕상부의 환기시설 등 창고건축의 전형적인 형태를 갖고 있다. 일제강점기 당시 쌀 보관 창고로 쓰이는 등 호남평야 쌀 수탈의 역사를 간직하고 있는 증거물로 역사적 가치가 높다.","a":"완주 구 삼례 양곡창고","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2135588.jpg"},{"q":"1983년에 발견된 것으로 돌기둥 4면에 불상이 새겨져 있는 백제시대 유일의 사면불(四面佛)이다. 사면불은 일명 ‘사방불’이라고도 하는데, 동·서·남·북의 방위에 따라 사방 정토에 군림하는 신앙의 대상인 약사불, 아미타불, 석가불, 미륵불을 뜻한다. 남면에는 본존불로 생각되는 여래좌상이 있고, 나머지 면에는 여래입상이 각각 1구씩 새겨져 있다. 머리 부분은 많이 훼손된 채 서향과 북향만이 남아있고, 따로 끼울 수 있도록 되어있는 손은 모두 없어졌다. 4구의 불상은 모두 양 어깨에 옷을 걸치고 있으며 가슴부분에 띠매듭이 보인다.","a":"예산 화전리 석조사면불상","c":"보물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617923.jpg"},{"q":"이 건물은 일제강점기에 이 근처에 있던 통조림 공장의 직원 사택으로 건립하였다. 주변에 같은 구조로 지은 주택이 골목 좌우에 2열로 배치되어 있으며, 내부는 변화하는 생활 방식에 따라 부분적으로 변형되었지만, 박공지붕과 측면의 부섭지붕, 널빤지로 만든 ○○○ 판벽 등 외관은 예전 모습을 잘 유지하고 있다.","a":"순천 옥천동 일본식 가옥","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668958.jpg"},{"q":"조선 10대 ○○○과 거창군부인 신씨(1476~1537)의 묘이다. ○○○은 9대 성종과 폐비 윤씨의 아들로 태어나 1494년 왕위에 올랐다. 즉위 초에는 성종 대의 평화로움이 그대로 이어졌다. 사치풍조를 잠재우기 위해 구체적인 금지 조항을 만들어 단속하였고, 종묘에 신주를 모시는 제도를 새롭게 정비하였으며, 비융사를 설치하여 철갑옷과 무기를 만들어 생산하는 등 국방정책에도 힘을 썼다.","a":"서울 연산군묘","c":"사적","nc":"","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2021070909361500.jpg"},{"q":"ㅇ ○○○○○ 앞마당에 위치한 도현화상(道現和尙) 공덕비에 기록된 연혁은 1911년 일본인 승려 도현화상이 ○○에 포교소 개설, 1917년 흥선사로 개창, 해방 후 만암 스님이 ○○○○○으로 개명하였다 ㅇ 해방 이후 만암 스님은 ○○○○○에서 불교정화운동에 앞장섰으며, 법정스님이 출가이전 대학생 신분으로 ○○○○○에서 불교정화운동 실무를 돕던 중 고은 문인이 출가 당시 일초 스님으로 방문하여 두 분이 최초의 인연을 가졌던 곳으로도 알려져있다.","a":"목포 정광정혜원","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017103021381300.JPG"},{"q":"경상남도 ○○군 단성면 ○○○의 절터에 묻혀 있던 것을 1957년에 경남 진주의 금선암(金仙庵)으로 옮긴 것이다. 불상을 안치한 대좌(臺座)와 불상 뒤의 광배(光背)를 모두 갖추고 있으나 무릎 부분을 비롯하여 많은 부분이 깨진 상태이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 머리에 비해서 얼굴이 지나치게 길다. 어깨는 넓고 당당하나 허리를 너무 잘록하게 표현하여 어색한 느낌이 드는데, 이러 불상의 모습은 통일신라 후기에 유행하던 특징이기도 하다.","a":"산청 사월리 석조여래좌상","c":"보물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622515.jpg"},{"q":"조계산에 있는 ○○○는 우리나라 3대 사찰 중 하나로 매우 유서 깊은 절이다. ‘송광’이라는 절 이름은 조계산의 옛 이름인 송광산에서 따 왔다고 하는데 절을 언제 세웠는지는 정확한 자료가 없어 알 수 없다. ○○○은 모든 질병을 고쳐 주는 부처인 약사여래를 모신 불전으로서, 규모가 ○○○에서 가장 작은 법당이다. 앞면·옆면이 모두 1칸으로 간결하며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 현재 있는 우리나라 법당 중 가장 작은 이 ○○○은 조각 수법으로 보아 조선 중기인 17세기 무렵의 건물로 추정한다.","a":"순천 송광사 약사전","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619026.jpg"},{"q":"조선 태조 이성계의 초상화를 모신 곳이다. 태종은 1410년 ○○·경주·평양에 태조의 모습을 그린 초상화를 모시고 어용전이라 하였다. 그 후 태종 12년(1412)에 태조 진전이라 부르다가 세종 24년(1442)에 와서 ○○는 ○○○, 경주는 집경전, 평양은 영숭전으로 달리 이름을 지었다. ○○○은 임진왜란 때 불탄 것을 광해군 6년(1614)에 다시 고쳐 지었다. 건물의 구성은 본전·헌·익랑 들로 이루어져 있고 이를 내삼문과 외삼문으로 둘렀다. <br/><b>※(○○○ → ○○○○○)으로 명칭변경 되었습니다.(2011.07.28 고시)</b>","a":"전주 경기전","c":"사적","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626918.jpg"},{"q":"이 책은 송나라 여조겸의 교편(校編)이며, 조선 태종 3년(1403)에 주조한 동활자인 계미자를 사용하여 태종년간에 간행한 것이다. 계미자는 고려와 조선시대의 글자주조술과 조판술의 발달사연구에 귀중한 자료인데 사용했던 기간이 짧아 전해지는 본이 희귀하다. 구성을 보면 ○○는 2∼29장으로 구성되었으나 1장이 결락되어 28장만 남아있으며, 권5는 1∼19장 모두 현재 전하고 있다. 책의 상태를 보면 습기로 인해 표지가 퇴색했으며, 문자가 보이지 않는 곳도 있다. 책의 앞뒤의 염황색 표지를 대어 염청색의 면으로 보강하였다.","a":"동래선생교정북사상절 권4, 5","c":"국보","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611609.jpg"},{"q":"1955년 건립된 이 건물은 ○○ 출신 건축가 정옥진이 설계한 건물로서 ○○○○○에서 가장 먼저 지어졌다. 중앙에 3층의 본채와 양 옆 1층에 날개처럼 덧 달아낸 대강의실 등 모두 세 부분으로 구성되어 있다. 중앙 부분에는 첨두형 아치로 출입문을 만들고 장방형 창과 원형 창 그리고 아치 형상의 창문을 조화롭게 배치하였다. 한국전쟁 뒤 물자와 인력이 부족한 어려운 상황에서 자체 벽돌 공장을 세워 놓고 필요한 벽돌을 제작하여 건물을 세웠다.","a":"광주 전남대학교 인문대학 1호관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667875.jpg"},{"q":"백제시대에 창건한 사찰로 전해지고 있는 ○○○○○는 통일신라시대 진표율사의 중창불사 이후 1400여년의 역사를 가지고 있는 미륵신앙의 본산으로 법맥을 이어오고 있으며, 후백제 견훤의 유배지로도 알려진 사찰이다. 고려시대에는 혜덕왕사가 법상종 관련 불서의 간행 및 유포에 힘쓰는 한편 ○○○를 중창하였으며, 임진왜란 당시에는 호국사찰로서의 역할을 다하였다. 국보 미륵전을 비롯하여 고려시대 석조문화유산 및 조선후기의 목조건축 등 다량의 국가지정문화유산이 보존되어 있는 호국사찰로 역사적·문화사적 의의 등 학술적인 측면에서 중요한 가치를 지니고 있다.","a":"김제 금산사 일원","c":"사적","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627009.jpg"},{"q":"○○○ 보광명전에 봉안되어 있는 삼신불회도는 1755년 처일(處一)의 주도로 총 19명의 화승이 모여 제작한 불화이다. 18세기의 삼신불화는 비로자나와 석가, 노사나를 세 폭으로 나누어 그리는 3폭 형식이 유행하였지만, 이 불화는 거대한 화폭에 비로자나불과 석가모니불, 노사나불 등 삼신불을 중심으로 여러 권속들을 함께 그린 1폭 형식을 취하고 있다. 이러한 구성은 물론 1650년에 제작된 갑산 삼신불괘불탱에서 확인되지만 19세기에 이르러 본격적으로 유행한 형식이다.","a":"청도 운문사 비로자나삼신불회도","c":"보물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622273.jpg"},{"q":"동해안의 수려한 자연환경 속에 자리한 전통 한옥마을로, 14세기 경부터 강릉 함씨와 강릉 최씨, 용궁 김씨 등이 모여 사는 집성촌이다. 고려 말에 함부열이 조선의 건국에 반대하여 은거한데서 비롯되며, 임진왜란으로 폐허화된 후 150여년에 걸쳐 형성된 마을이다. 함씨·최씨·진씨가 주를 이루고 이밖에 이씨·박씨·김씨·한씨·윤씨 등이 살고 있다. 19세기를 전후하여 지어진 기와집들은 모두 강원특별자치도 북부지방에서만 볼 수 있는 양통집이다. 이는 긴겨울의 추위를 견디기 위한 구조로, 특히 부엌 앞 처마에 외양간이 있는 것이 특징이다.","a":"고성 왕곡마을","c":"국가민속문화유산","nc":"","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633840.jpg"},{"q":"­ 이 시설물은 중앙선을 운행하던 증기기관차에 물을 공급하기 위해 설치한 ○○○이다. ○○○ 맨 꼭대기에 물탱크가 있고 그 아래로 물을 끌어올리는 펌프 시설이 있었다. 꼭대기에는 환기창이 4개 있는 등 1940년대 ○○○의 전형적인 모습을 보여주고 있다. 1950년대에 디젤기관차가 등장하면서 사라졌지만, 근대화 과정에서 중요한 기능을 한 증기기관차 관련 철도 시설물로 가치가 높다.","a":"원주역 급수탑","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668332.jpg"},{"q":"○○○○○은 별자리를 돌에 새겨 놓은 천문도이다. 둥글게 그린 하늘 안에 1,467개의 별이 그려져 있고 아래에는 천문도를 만들게 된 경위와 참여자 명단이 적혀 있다. 구도상 약간의 차이가 있을 뿐 내용은 태조 4년(1395)에 처음 만든 것과 완전히 같고, 설명문으로는 권근의 글이 실려있다. 전체의 구성이 처음 새긴 것보다 더 좋고 당당하다. 1395년 처음 새긴 것을 돌이 닳아 잘 보이지 않게 되어 숙종 13년(1687)에 다시 새겨 놓은 것으로, 천문도를 제작하게 된 이유와 과정 등은『증보문헌비고』,『상위고』와『서운관지』에 잘 나타나 있다.","a":"복각천상열차분야지도 각석","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614050.jpg"},{"q":"○○○○은 18세기 중엽에 중건한 정면 3칸, 측면 3칸의 다포(多包)식 팔작지붕 건물로서, 18~19세기 영동지방의 중요한 왕실 원당사찰로서 세부의장 및 공포형식이 우수하고 기단과 계단, 창호 등 높은 품격의 요소들을 잘 보존하고 있다. 특히 기단의 모란, 사자 문양과 계단 소맷돌의 삼태극, 용두 문양 조각들은 다른 사찰에서는 찾아보기 어려운 귀한 사례이다. 이처럼 ○○○○○은 형태, 구조, 장식 측면에서 뛰어날 뿐만 아니라 보존상태 또한 양호하여 국가지정유산(보물)으로 역사적, 건축적, 예술적 가치가 충분하다.","a":"속초 신흥사 극락보전","c":"보물","nc":"","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2018060417470200.JPG"},{"q":"○○○은 근정전 서측에 있는 건물로써, 북쪽으로는 경회루가 자리 잡고 있다. ○○○이 있는 권역은 세종 연간에는 학문을 연구하며, 왕에게 주요 정책을 자문하고 건의하던 기관으로 한글을 창제하는 등 문치의 본산이었던 집현전이 있던 궐내각사의 지역에 해당하며, 동쪽으로 사정전의 왕의 영역과 신하들의 영역이 만나는 접점인 이곳에 궐내의 관청인 각사들이 자리 잡고 있다. ○○○은 고종 때 중건되어 잠시 왕의 편전으로도 사용되었으며, 1894년 갑오개혁 때에는 대한제국의 군국기무처를 여기에 두고, 이후 내각청사로 사용되었다.","a":"경복궁 수정전","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615018.jpg"},{"q":"이 시설물은 한국전쟁 직후 주민들이 콘크리트로 건축한 화기진지(火器陣地) 용도의 자주적 방어시설로, 주민들이 경찰을 지원하여 북한군 게릴라들의 침투를 막는 데 크게 기여한 곳이다. 콘크리트 4면체 형으로 높이는 7m이며 4면에 근대적인 사격용 총안 시설을 2개씩 설치해 놓았다. 지붕과 내부에 ○○ 위로 접근할 수 있도록 설치한 사다리 시설 등은 소실되었지만 ○○에서 부항파출소로 통하는 지하 통로 입구는 그대로 잘 남아 있다.","a":"김천 부항지서 망루","c":"국가등록문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669154.jpg"},{"q":"○○○○○은 고려말기 문신이었던 최해(崔瀣,1288∼1340) 선생이 고려시대 선비들의 뛰어난 시문을 뽑아서 펴낸 시선집인 『○○○○○』가운데 남아있는 권 7∼9이다. 최해는 최치원의 후손으로, 문과에 급제하고 원나라의 과거에도 급제하는 등 학문에 뛰어났다. 성격이 곧고 강직하였고, 벼슬에서 물러난 후에는 책을 쓰는데 힘써 『○○○○』외에도 문집으로 『졸고천백』2책을 남겼다. 『○○○○』은 최해의 『○○○○서(序)』에서 시를 「오칠」, 문을 「천백 」, 변려문을 「사육」이라 하고, 이를 총괄하여 그 제목을 『○○○○』이라 하였다.","a":"동인지문오칠 권7~9","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614525.jpg"},{"q":"○○○○○은 신라 진흥왕대에 창건하고 광해군 5년(1613)에 재건한 ○○○에 있는 불상으로 청동 표면에 도금한 것이다. 머리에 두건(頭巾)을 쓰고 있으며, 이마에 두른 굵은 띠는 귀를 덮고 배에까지 내려오고 있다. ○○○ 도솔암에 있는 ○○○지장보살좌상(보물)과 같은 형태의 불상이다. 넓적하고 살찐 얼굴에 눈·코·입이 작게 묘사되었다. 굵게 주름진 삼도(三道)가 표현된 목은 짧아서 움츠린 듯한 느낌을 준다. 가슴은 당당한 모습이지만 두꺼운 옷에 싸여 몸의 굴곡은 나타나 있지 않다.","a":"고창 선운사 금동지장보살좌상","c":"보물","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618277.jpg"},{"q":"○○○○○은 1599년(선조 32) 전라좌수영 객사로 건립한 건물로서 임진왜란과 정유재란을 승리로 이끈 수군 중심기지로서의 역사성과 1718년(숙종 44) 전라좌수사 이제면(李濟冕)이 중창한 당시의 면모를 간직하고 있으며, 건물규모가 정면 15칸, 측면 5칸, 건물면적 240평으로 현존하는 지방관아 건물로서는 최대 규모이다. ○○○의 평면은 68개의 기둥으로 구성되었는데 동·서측 각각 2번째 협칸의 전면 내진주를 이주(移柱)하여 내진주 앞쪽에 고주(高柱)로 처리하였다. 이 고주는 곧바로 종보를 받치고 있고 대량은 맞보로 고주에 결구하여 그 위에 퇴보를 걸었다.","a":"여수 진남관","c":"국보","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612571.jpg"},{"q":"색민(色旻)이 으뜸화원을 맡아 조성한 괘불로서 중앙의 석가모니불을 비롯하여 왼쪽에는 여의를 든 문수보살을, 오른쪽에는 연꽃을 든 보현보살을, 그리고 석가모니불의 두광 좌우로 관음보살과 아미타불을 배치하여 오존도(五尊圖) 형식을 보이고 있다. 이러한 도상적 특징은 내소사 괘불을 비롯하여 안정사 괘불, 청곡사 괘불, 운흥사 괘불, 다보사 괘불 등 18세기 호남지역에서 성행한 『오종범음집(五種梵音集)』에 근거한 도상을 간략화한 것으로 생각된다.","a":"해남 대흥사 영산회 괘불탱","c":"보물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619981.jpg"},{"q":"조선 후기 우리나라의 아름다운 강산을 실제로 보고 그리는 진경산수화풍을 연 겸재 ○○이 영조 10년(1734)에 내금강의 모습을 그린 작품이다. 내금강의 실경을 수묵담채로 그렸으며 크기는 가로 94.5㎝, 세로 130.8㎝이다. 전체적으로 원형구도를 이루고 있고 위에서 아래로 내려다 본 모습이다. 눈덮인 봉우리들은 위에서 아래로 내려긋는 수직준법을 이용하여 거칠고 날카로운 모습으로 표현하였고, 이와 함께 위쪽에는 비로봉이 우뚝 솟아 있으며, 화면 중심으로는 만폭동 계곡이 위에서 아래로 가로지르고 있다.","a":"정선 필 금강전도","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611691.jpg"},{"q":"이성계의 역성혁명에 반대하여 풍산으로 내려온 이웅의 후손으로 숙종 때 사람인 이문한이 지은 것으로 추정된다. 집의 이름을 '○○○'이라 한 것은 '외당에 독서실을 만들어 하루하루를 반성한다'는 뜻으로 현판을 달았기 때문이다. 참나무숲이 우거진 뒷동산을 배경으로 비교적 높은 곳에 세워진 'ㅁ'자형 집으로 조선시대 전통 민가의 대표적인 양식을 보여주는 곳이다. 집 구성은 안채와 사랑채가 한몸을 이루고 있다. 안채는 중앙에 안방과 마루가 있고 왼쪽 뒤쪽으로 골방이 있으며, 안방에 접해서 부엌이 있다. 그 앞으로 고방과 외양간이 있고, 마루의 오른쪽에는 2칸의 방이 있다.","a":"안동 일성당 고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635386.jpg"},{"q":"불경은 크게 경(經), 율(律), 론(論)의 삼장(三藏)으로 나눌 수 있는데, ○○○○은 삼장 가운데 논(論)에 해당한다. 용수(龍樹)가 저술한 것으로, 당시(200년경)의 불교사상을 알 수 있는 불교 백과사전의 역할을 하는 대논문이다. 후진의 구마라습(鳩摩羅什)이 번역한 것으로 전체 지도론 100권 중 ○○○에 해당한다. 다갈색의 종이 위에 은색으로 불경을 옮겨 적은 것으로, 병풍처럼 펼쳐서 볼 수 있는 형태이며, 접었을 때의 크기는 세로 31㎝, 가로 11.2㎝이다. 앞뒤의 표지와 앞의 6장이 떨어져 나가 현재는 13장만 남아있다.","a":"상지은니 대지도론 권28","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614564.jpg"},{"q":"경기도 광주 춘궁동에 있는 3층 석탑으로 2단의 기단(基檀) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단부의 바닥돌과 아래층 기단의 가운데돌은 한돌로 짜여졌는데, 안타깝게도 대부분이 땅속에 파묻혀 있고, 아래층 기단 맨윗돌 일부가 깨지고 없어졌다. 윗층 기단과 탑신부의 각 층 몸돌에는 기둥 모양이 새겨져 있다. 지붕돌은 아래면이 반듯하고 윗면도 완만한 경사를 보이지만, 지붕돌 네 귀퉁이에서의 치켜올림이 뚜렷해 경쾌한 느낌이다. 이 탑은 1층 탑신과 2·3층 탑신의 크기가 줄어드는 비율이 따라 지붕돌도 작아지고 있어 전체적으로 매우 안정된 느낌을 주고 있다.","a":"하남 동사지 삼층석탑","c":"보물","nc":"","r":"경기도","s":"하남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615642.jpg"},{"q":"중국 요나라 성종 15년(997)에 행균스님이 편찬한 한자의 자전이다. 이 책은 재래 중국의 자전과 달리 부수 별로 먼저 배열하고, 또 같은 각수 안에서는 운(韻)별로 배열하여 여러 가지를 병용하는 방법을 취하였고, 정자 이외의 속자까지도 전부 망라하여 해설을 붙인 것이다. 이 책을 우리나라에서 언제 중간했는지는 알 수 없으며, 단지 나주에서 권득령의 책임 하에 간행되었음을 알 수 있다. 이 책의 원형인 『○○○○』은 중국에서는 벌써 없어지고 남송 때에 와서 『○○○감』으로 이름이 바뀌어 나왔으므로, 요나라 때의 원판본은 일찍부터 전해지지 않는다.","a":"용감수경 권3~4","c":"국보","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611926.jpg"},{"q":"이 시설은 ○○ 지역에 식수를 공급하기 위해 1909년에 건립된 상수도 수원지로, 이후 산업용 용수 공급을 하였고, 현재 어린이 대공원 내 교육관광 자원으로 쓰이고 있다. 대한제국 정부와 ○○의 일본거류민단이 공사비 공동부담과 공동 경영 계약을 체결하고 건설한 것으로서, 정초석에는 대한제국 연호로 써서 준공 시기를 알리는 “隆熙3년 竣工”이란 기록 외에도 영문으로 건설에 참여한 일본인 기술자 이름 등이 기록되어 있다.","a":"부산 구 성지곡수원지","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"부산진구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667749.jpg"},{"q":"조선 태조 6년(1397) 10월에 공신도감(功臣都監)에서 왕의 명령을 받아 ○○○에게 내린 문서로, 공신임을 입증하는 내용을 담고 있다. 크기는 가로 140㎝, 세로 30.5㎝이며, 원래는 함경남도 단천군 파도면 심씨 집안에서 물려 내려오던 것이다. ○○○○○ 제도는 조선시대에 개국공신을 늘리려는 의도에서 만들어진 일종의 새로운 포상제도로, 1392년부터 1397년까지 여러 차례에 걸쳐 1,400여 명에게 봉해졌다.","a":"심지백 개국원종공신녹권","c":"국보","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611957.jpg"},{"q":"이 건물은 충남금융조합연합회 회관으로 건립한 이후 ○○○○○, 공주시청(1986~1989년) 등으로 사용하였다. 2층짜리 붉은 벽돌 건물로, 현관이 돌출되어 있고 전면 중앙 부분에 원기둥이 4개 있으며, 엔타블러처(Entablature)로 장식하여 정면성을 강조하였고, 전체적으로 좌우 대칭의 균형미를 보여주고 있다. 공주시 구 도심을 활성화하려는 문화 사업의 하나로 2010년에 '디자인카페'로 활용하다가 2014년 리모델링을 통해 공주역사영상관으로 개관하였다.","a":"구 공주읍사무소","c":"국가등록문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668638.jpg"},{"q":"○○○ 전 대통령이 1958년 5월부터 1961년 8월 국가재건최고회의 의장 관사로 이주할 때까지 가족과 함께 생활했고 1979년 서거 후에는 유족들이 살았던 집으로, ○○○ 전 대통령이 5.16군사정변을 계획하고 지휘한 장소로서 한국 현대정치사에서 있어 중요한 역사의 현장이다.","a":"서울 신당동 박정희 가옥","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667202.jpg"},{"q":"○○○는 672년(신라 문무왕 12) 능인대사(能仁大師)에 의하여 창건되었다는 전설이 전하는데,<극락전 중수상량문>등 발견된 구체적인 자료를 통해 보면 7세기 후반 능인대사에 의해 창건된 것으로 추정된다. ○○○○은 스님들이 불교의 기초 교학을 배우는 곳이다.『양법당중수기』등의 기록에 따르면 같은 경내에 있는 극락전과 대웅전을 17세기에 고쳐 지었을 때 ○○○○도 함께 고쳤을 것으로 추정한다. 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양과 비슷한 맞배지붕이다.","a":"안동 봉정사 화엄강당","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620955.jpg"},{"q":"「○○○○○」는 16세기를 대표하는 명필 고산(孤山) ○○○가 당나라 이군옥(李羣玉)의 오언율시를 쓴 것이다. 그는 낙동강 지류 천보탄(天寶灘) 가에 매학정(梅鶴亭)을 짓고 살았던 처사(處士)로서 회소(懷素)의 방일한 ○○를 애호하고 또 회소를 바탕으로 독특한 서풍을 보인 명나라 동해옹(東海翁) 장필(張弼, 1425~1487)을 따랐다. 이 ○○는 회소와 장필을 배워 활달하고 운동세가 많은 획법과 변화로운 짜임을 잘 구사한 예이다.","a":"황기로 초서 - 이군옥시","c":"보물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616944.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하는데, 천태종의 근본경전으로 화엄경과 함께 한국 불교사상 확립에 크게 영향을 끼친 경전이다. ○○○○○ 중 권5에서 권7에 해당하는 이 책은 태종 5년(1405)에 성달생·성개 형제가 죽은 아버지의 명복을 빌기 위해 옮겨 쓴 것을 도인(道人) 신문(信文)이 목판에 새겨 찍어낸 것이다. 닥종이에 찍은 목판본으로 3권을 하나의 책으로 엮었으며, 책의 크기는 세로 29㎝, 가로 30.5㎝이다.","a":"묘법연화경 권5~7(1988-2)","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614340.jpg"},{"q":"대구광역시 ○○군 팔공산 절벽의 자연동굴에 만들어진 통일신라 초기의 ○○사원으로, 인공적으로 만들어진 경주 ○○암 ○○보다 연대가 앞선다. 이 ○○에는 700년경에 만들어진 삼존석불이 모셔져 있다. 가운데 본존불은 사각형의 대좌(臺座) 위에 양 발을 무릎 위에 올리고 발바닥이 위로 향한 자세로 앉아 있는 모습이다. 민머리 위에는 상투 모양의 큼직한 머리(육계)가 있으며, 얼굴은 몸에 비하여 큰 편으로 삼국시대 불상에서 보이던 친근한 미소 대신 위엄있는 모습을 하고 있다.","a":"군위 아미타여래삼존 석굴","c":"국보","nc":"","r":"대구광역시","s":"군위군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612818.jpg"},{"q":"경상남도 3대 절 중 하나로 유명한 ○○○는『삼국유사』의 기록에 따르면 의상대사가 통일신라 문무왕 18년(678)에 처음으로 지었다고 한다. 또한 옛날 일본인이 침입했을 때에는 이곳의 승려들이 전쟁에 직접 참여하여 함께 싸우기도 했던 곳 가운데 하나로도 알려져 있다. 이 건물을 세운 시기를 알 수는 없으나 조선 광해군 6년(1614)에 묘전화상이 절내 여러 건물을 고쳐 지을 때 함께 세운 것으로 추측한다. 정조 5년(1781)에 백암선사가 현재의 건물로 보수했다. 앞면 3칸 규모이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"부산 범어사 조계문","c":"보물","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615112.jpg"},{"q":"1914년 건립 이 건물은 일제 강점기 당시 진해에 자리 잡은 일본 해군 기지인 ○○○○○로 건립되어 현재 대한민국 해군의 진해기지 ○○○로 사용되고 있다. 정면 중앙부에 2층 높이의 현관 포치(porch)가 돌출되어 있고, 그 위쪽에 사각 기둥 형태의 필라스터(pilaster)를 세우고 삼각형의 페디먼트(pediment)를 올려 정면성을 강조하였다. 1층 외벽에 화강석을 사용하여 전반적으로 안정된 느낌을 주며, 창의 상하 인방 및 좌우에 붉은 벽돌과 흰색의 화강석을 사용하여 화려하게 꾸몄다. 진해 지역이 일본의 해군 기지로 이용된 침략의 역사를 보여주고 있다.","a":"구 진해요항부 사령부","c":"국가등록문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669392.jpg"},{"q":"녹권이란 공신으로 인정하는 증서를 말하는데, 이 녹권은 선조 37년(1604)에 선조가 임진왜란 때 의주로 피난할 때 호종((扈從:임금의 수레를 모시어 쫓음)하였던 청원군 ○○에게 내린 ○○○○이다. ○○는 선조 5년(1572) 문과에 급제하여, 임진왜란이 일어나자 임금을 호종하여 의주로 모셨으며, 경기도 관찰사가 되어 서울을 탈환하고자 시민들과 함께 싸우다가 왜병들의 습격을 받고 사망하였다. 교서에는 ○○가 임진왜란 때 왕을 의주까지 호종했던 공훈과 경기도 관찰사에 제수되어 서울을 수복코자 하였으나 왜병의 습격에 전사한 그에게 2등공신을 제수한다는 내용이 담겨있다.","a":"심대 호성공신교서","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616029.jpg"},{"q":"○○○에서 발견된 신라 때 내관으로 쓰였던 모자형 관이다. ○○○은 경주 고분 제155호 무덤으로 불리던 것을 1973년 발굴을 통해 금관, 팔찌 등 많은 유물과 함께 천마도가 발견되어 ○○○이라 부르게 되었다. 금모(金帽)란 금으로 만든 관(冠) 안에 쓰는 모자의 일종으로 높이 16㎝, 너비 19㎝인 이 금모는 널<관(棺)> 바깥 머리쪽에 있던 껴묻거리(부장품) 구덩이와 널 사이에서 발견되었다. 각각 모양이 다른 금판 4매를 연결하여 만들었는데, 위에는 반원형이며 밑으로 내려갈수록 넓어진다. 아랫단은 활처럼 휘어진 모양으로 양끝이 쳐진 상태이다.","a":"천마총 관모","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612861.jpg"},{"q":"○○상감이란 흙으로 그릇을 빚어 표면에 무늬나 그림을 새기고, 그 자리를 백토나 자토로 메운 뒤 유약을 발라 구운 후, 투명한 ○○ 유약을 통해 흰색 또는 검은색 무늬가 보이도록 한 것으로, 12세기 전반에 발생하여 12세기 중엽에 전성기를 이루었다. ○○○○○는 높이 32.2㎝, 아가리 지름 7㎝, 밑지름 14.5㎝인 이 병은 고려시대에 많이 만들어진 상감○○○○들에 비해, 어깨가 처져서 부드러운 느낌을 주며 밑이 넓어서 안정감이 있다. 유약은 잘 녹아서 투명하며, 색깔도 매우 아름답다.","a":"청자 상감운학모란국화문 매병","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613479.jpg"},{"q":"○○은 중앙부와 양단부를 뒤로 돌출시킨 E자형 평면으로 중앙부와 양단부 전면에 삼각형의 박공을 두어 정면성을 강조하였으며, 인근에서 산출되는 석재를 사용하여 하단부는 큰 혹두기 방식으로 다듬어 구조체의 질감을 강조하고 상부는 잔다듬으로 비교적 매끈하게 처리하는 등 다양한 형식의 석재 표면 다듬기가 특징적임.","a":"목포 문태고등학교 본관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2126162.jpg"},{"q":"○○○의 법당 남쪽에 서 있는 석탑으로, 3단의 기단(基壇) 위로 3층의 탑신(塔身)을 올린 모습이다. 기단의 각 층에는 4면의 모서리와 가운데에 기둥 모양을 본떠 새겨 두었다. 탑신은 몸돌과 지붕돌이 각각 하나의 돌로 되어 있으며, 각 층의 몸돌에도 모서리마다 기둥 모양을 본떠 새겼다. 지붕돌은 밑면의 받침이 각 층마다 4단이고 처마 밑은 수평이다. 또한 윗면에는 경쾌한 곡선이 흐르고, 네 귀퉁이에서의 치켜올림도 우아하다.","a":"구례 연곡사 삼층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618803.jpg"},{"q":"이 책은 1470년(성종 원년) 4월에 세조의 왕비인 정희대왕대비가 발원하여 돌아가신 세조, 예종, 의경왕의 명복을 빌기 위해 간행한 ○○○○○ 7권 가운데 권 1～2 이다. 이 책은 권돈일, 고말종, 장막동, 우인수, 최금동, 이영산, 최덕산 등 당대의 일류 각수(刻手)들에 의해 이루어져 새김이 매우 정교하다. 우리나라에서 유통된 법화경은 대부분 계환의 해석이 붙어 있는 것을 사용하였는데, 이때 새긴 법화경은 천도의식용으로 사용하기 위해 원문만 새긴 것이다.","a":"묘법연화경 권1~2","c":"보물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618009.jpg"},{"q":"○○○는 손꼽히는 참선도량 중 하나로서 지리산의 절경과 잘 어우러진 사찰이다. 경내의 사리전 앞에 서 있는 이 탑은 2단의 기단(基壇) 위에 8층의 탑신(塔身)을 세운 모습으로, 꼭대기의 머리장식은 일부만 남아있다. 기단의 위층은 이 탑에서 가장 주목되는 부분으로 모서리에 기둥 모양을 본떠 새기는 대신 인물상(人物像)을 두었고, 4면에 사천왕상(四天王像)을 새겨 놓았다. 탑신의 각 지붕돌은 처마가 두꺼우며 네 귀퉁이에서 약간 들려있다. 8층 지붕돌에는 금방이라도 고즈넉한 경내를 깨울 듯 풍경이 달려 있다.","a":"산청 대원사 다층석탑","c":"보물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622879.jpg"},{"q":"○○ 남산 기슭에 흩어져 있던 것을 1923년 지금의 자리에 모아 세웠다. 이 석불들은 기본양식이 똑같아 처음부터 삼존불(三尊佛)로 모셔졌던 것으로 보인다. 중앙의 본존불은 머리에 상투 모양의 머리(육계)가 있는데, 특이하게도 이중으로 되어 있으며, 표면이 매끄럽게 표현되었다. 어린아이 표정의 네모난 얼굴은 풍만하며, 둥근 눈썹, 아래로 뜬 눈, 다문 입, 깊이 파인 보조개, 살찐 뺨 등을 통하여 온화하고 자비로운 불성(佛性)을 표현하고 있다. 목이 표현되지 않은 원통형의 체구에 손을 큼직하게 조각하였는데, 왼손은 내리고 오른손은 올리고 있다.","a":"경주 배동 석조여래삼존입상","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620135.jpg"},{"q":"○○○○○은 고려 중기에 만들어진 ○○○○으로 높이 34.2㎝, 아가리 지름 1.3㎝, 밑지름 9.3㎝이다. 몸통의 한 면에는 물가의 갈대와 그 밑에서 노닐고 있는 기러기 한 쌍을 새겼고, 다른 한 면에는 수양버들 아래서 쉬고 있는 원앙 한 쌍을 새겼다. 병 목의 중간에 있는 넓은 삿갓모양 마디의 윗면은 안쪽과 바깥쪽으로 나누어 안쪽에는 구름무늬를, 바깥쪽에는 덩굴무늬를 둘렀다. 병 목 중간 마디에 수직으로 물을 따르는 주구가 세워져 있는데, 6각으로 모서리를 깎아냈다. 굽다리는 밖으로 약간 퍼져서 안정된 자세를 보인다.","a":"청자 양각갈대기러기문 정병","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613264.jpg"},{"q":"○○○은 신라의 제 29대 왕으로 진덕여왕의 뒤를 이어 왕위에 오른 최초의 진골출신의 왕이며 본명은 김춘추이다. 즉위 전부터 고구려와 당나라 사이를 직접 오가며 탁월한 외교역량을 보여주었고 이후 당과 연합하여 백제를 정복하고 삼국통일의 기초를 마련한 인물로, '삼국사기'에 의하면 왕위에 오른지 8년만인 661년 6월에 죽어, 죽은 왕에게 '태종무열'이라는 시호를 내렸다고 전한다.. 서악동 구릉의 동사면에 종렬한 5기의 대형 원분 가운데 가장 아래쪽에 위치한다.","a":"경주 무열왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627550.jpg"},{"q":"조선 중기의 명장인 이순신의 덕을 기리기 위하여 세운 비이다. ‘타루(墮淚)’란 눈물을 흘린다는 뜻으로, 중국의 양양 사람들이 양호(羊祜)를 생각하면서 비석을 바라보면, 반드시 눈물을 흘리게 된다는 고사성어에서 인용하였다. 비의 형태는 네모난 받침돌 위에, 비몸을 세우고, 머릿돌을 얹은 모습이다.받침돌에는 꽃무늬가 새겨져 있고, 머릿돌에는 구름무늬로 가득 채워져 있으며, 꼭대기에는 머리장식으로 보주(寶珠:연꽃봉오리모양의 장식)가 큼직하게 솟아있다.","a":"여수 타루비","c":"보물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619597.jpg"},{"q":"「○○○○○」는 16세기 문신·시조작가·○○명필로 유명한 봉래(蓬萊) ○○○의 필적으로 당나라 저광의(儲光羲)의 오언시 「낙양도(洛陽道)」 5수 가운데 제1수를 쓴 것이다. 원래 첩이었던 것을 근대에 축으로 개장하였다. ○○○은 고산(孤山) 황기로(黃耆老, 1521~1576?)와 더불어 조선을 대표하는 ○○ 명필로 후대에 큰 영향을 미쳤다. 그는 금강산과 같은 선경(仙境)을 좋아하고 세속에 얽매이기를 싫어했듯이 글씨에서도 당나라 장욱(張旭)과 회소(懷素)의 방일(放逸)한 ○○를 매우 애호하였다.","a":"양사언 초서","c":"보물","nc":"","r":"서울특별시","s":"마포구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614946.jpg"},{"q":"절에 행사가 있을 때 절 입구에 당(幢)이라는 깃발을 달아두는데, 당간(幢竿)이란 이 깃발을 달아두는 대(臺)를 말한다. ○○읍 ○○○은 ○○읍에서 순창행 도로를 따라 1㎞쯤 가다보면 논 한가운데에 높게 서 있다. 연꽃잎이 새겨진 돌 위에 당간을 세우고 양 옆에 기둥을 세워 지탱하고 있다. 당간은 가늘고 긴 8각 돌기둥 3개를 연결하고 연결부위에 철띠를 둘렀다. 꼭대기에는 쇠로 만든 둥근 보륜(寶輪:바퀴모양의 장식)이 있는데 풍경같은 장식물이 달려있고 위에는 철침이 솟아있다.","a":"담양 객사리 석당간","c":"보물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619216.jpg"},{"q":"272.2×137.9cm에 달하는 1축의 대형 조선전도로, 표현된 범위는 조선과 만주의 일부를 아우르고 있다. 지도의 재질은 세견(細絹)으로 세 폭을 이어 만들었는데, 정교하게 그려진 솜씨로 볼 때 도화서의 화원이 그린 것으로 추정된다. 조선의 전체적인 모습, 수록된 정보의 종류와 양이 정상기(鄭尙驥, 1678-1752)의 <동국지도> 원본 계통과 동일하다. 1767년에 산청(山淸)과 안의(安義)로 바뀌는 산음(山陰)과 안음(安陰)이 변경 이전의 지명으로 기록되어 있는 점 등에서 1755년에서 1757년 사이에 제작된 것으로 추정된다.","a":"동국대지도","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614910.jpg"},{"q":"머리에 두건을 쓴 ○○○○상으로 바위형태의 대좌에 앉아 있는 모습이다. 전체 높이가 33.4㎝ 정도의 작은 불상으로 몸체는 두껍게 도금이 되어 있고 대좌는 붉은 빛이 도는 칠을 하였다. 결가부좌한 모습의 ○○○○상은 약간 앞으로 고개를 숙이고 있으며 목은 짧게 표현되었다. 양 어깨를 모두 감싼 옷을 입고 왼손에 보주를 들고 있다. 머리와 몸에 비해 다리와 양손이 작게 표현되어 있고, 조선시대 불교조각품으로는 드문 소형 석조상이다. 특이한 바위형태의 대좌 뒷면에는 이 불상 조성 배경 및 시주자와 제작자, 제작연대를 밝혀주는 글이 새겨져 있다.","a":"석조지장보살좌상","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614766.jpg"},{"q":"○○○은 하늘에 제사를 드리는 곳이다. 우리나라의 제천행사는 농경문화의 형성과 함께 시작된 것으로 보이며, 삼국시대부터는 국가적인 제천의례로 시행된 것으로 믿어진다. 고려 성종 2년(983) 정월에 처음 시행되어 설치와 폐지를 계속 되풀이하다가 조선초에 제천의례가 억제되자 폐지되었다. 세조 2년(1456)에는 일시적으로 제도화하여 1457년에 ○○○을 설치하고 제사를 드리게 되었다. 그러나 세조 10년(1464)에 실시된 제사를 마지막으로 ○○○에서의 제사는 중단되었다.","a":"환구단","c":"사적","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624581.jpg"},{"q":"구급의방을 집대성하여 민간에서 사용할 수 있게끔 만든 한글로 쓴 한의학 서적으로, 조선 성종 20년(1489)에 윤호, 임원준 등이 임금의 명을 받들어 편찬하여 목판본으로 간행한 것이다. 이것은 활자로 다시 간행한 총 8권 가운데 ○○의 1책이다. 질병을 중풍, 두통 등 127종으로 나누어 그 치료방문을 모아 엮었으며 누구나 알기 쉽게 한글로 번역하여 쉽게 편찬하였다. 이 책은 초간본은 전하지 않고, 을해자본으로 그대로 뒤집어 새긴 중간본만 전한다. 그러나 현존하는 중간본도 전질이 아니라 권1, 2, 3, 6, 7의 5권 5책만 전하고 있다.","a":"구급간이방 권6(1996)","c":"보물","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617234.jpg"},{"q":"1912년 무렵 건립 이 건물은 일제 강점기 당시 진해에 자리 잡은 일본 해군기지인 ○○○○○이다. 좌우 대칭형 평면으로 중앙부와 양쪽 끝 부분이 앞뒤로 돌출되어 그 위쪽을 박공지붕으로 구성하여 정면성을 강조하였으며, 지붕 용마루에는 3개의 환기탑을 설치하여 지붕 뼈대가 썩는 것을 방지하고 있다. 본관의 장엄하고 화려한 구성과 비교하면 ○○은 간소한 의장을 취하고 있지만, 1910년대 서양식 건물로서 건물의 의장 요소가 뛰어나다.","a":"구 진해방비대 사령부 별관","c":"국가등록문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669406.jpg"},{"q":"○○○에 소장되어 있는 ○○○○○로, ○○○ 16국사 중 제6세인 원감국사가 당시 충렬왕의 명을 받고 원나라를 방문하고 돌아오는 길에 원나라 세조인 쿠빌라이로부터 받아온 것이라 전해진다. 이 ○○○○○는 현재 크고 작은 6장의 조각으로 나뉘어 있는데, 색깔은 고르지 못하지만 전체적으로 황토색계의 밝은 황갈색이며 종이의 두께·색깔·필체 등으로 보아 본래는 1매의 문서였을 것으로 추정된다.","a":"순천 송광사 티베트문 법지","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619883.jpg"},{"q":"○○○는 고려 명종 25년(1195)에 보조국사 지눌이 세웠다고 전한다. 임진왜란 때 이 절의 승려들이 이순신 장군을 도와 왜적을 무찌르는데 공을 세웠으나 절이 모두 타 버려 지금 있는 건물들은 인조 2년(1624)에 다시 세운 것들이다. ○○○은 인조 2년(1624) 계특대사가 절을 고쳐 세울 때 다시 지은 건물로 석가삼존불을 모시고 있는 절의 중심 법당이다. 규모는 앞면 3칸·옆면 3칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위뿐만 아니라 기둥 사이에도 있는 다포 양식이다.","a":"여수 흥국사 대웅전","c":"보물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619115.jpg"},{"q":"통일신라말 ·고려초에 활약한 승려인 대경대사의 사리탑이다. 대경대사(862∼930)는 통일신라 경문왕 2년(862)에 태어나 9세 때 출가하였으며, 19세에 승려가 지켜야 할 계율을 받았다. 그후 교리보다는 참선에 뜻을 두어 성주사의 무염대사에게서 수행하기도 하였다. 중국으로 건너가 수 년동안 정진하다가 효공왕 13년(909)에 귀국 후 소백산에서 은거하던 중 고려 태조의 부름으로 보리사의 주지가 되었다. 태조 68세로 입적하니, 태조는 그의 시호를 ‘대경대사’라 하고 탑이름을 ‘현기’라고 내렸다.","a":"전 양평 보리사지 대경대사탑","c":"보물","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613272.jpg"},{"q":"19세기 초에 지은 것으로 보이는 초가로, 집의 뒷산이 좌우로 뻗어나와 감싸고 앞으로는 넓은 들판이 펼쳐지는 명당에 동남향으로 자리잡고 있다. 오른쪽 산자락에 울창한 소나무 숲과 연못을 조성하였고, 들판에 나무를 일렬로 심어 진입로를 조성하여 아늑함을 느끼게 한다. 안마당을 중심으로 안채와 사랑채가 나란히 배치되고 광채가 왼쪽·부엌이 오른쪽을 감싸고 있어 전체적으로 튼 'ㅁ'자 모양을 이루고 있다. 앞면 5칸·옆면 1칸반 규모의 안채는, 왼쪽부터 방 3개를 차례로 배치하였고 오른쪽이 부엌이다. 부엌과 'ㄱ'자로 연결되어 부엌광·헛간·외양간이 있다.","a":"예산 오추리 고택","c":"국가민속문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634303.jpg"},{"q":"○○○○○은 줄여서 ‘○○○○○’또는 ‘○○○’이라고도 하며, 부처님의 말씀을 머리속으로 이해하는데 그치지 않고 자신이 직접 경험하여 얻을 것을 주요 사상으로 하고 있다. 이 책은 송나라 계환(戒環)이 중요부분을 요약하여 풀이한『○○○』중 권 제1∼4인데, 4권이 하나의 책으로 묶여 있다. 나무에 새겨서 종이에 찍은 것으로, 조선 성종 19년(1488)에 충청도 홍산 무량사(無量寺)에서 홍산현감 등의 시주로 박경(朴耕)이 글을 써서 간행한 것이다.","a":"대불정여래밀인수증요의제보살만행수능엄경 권1~4","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614734.jpg"},{"q":"<○○○○○>은 오리 ○○○이 1604년 호성공신(扈聖功臣) 2등에 녹훈(錄勳)된 것을 기념해 제작된 것으로 같은 해 조성된 청난공신(淸難功臣)과 선무공신(宣武功臣)의 도상에 비해 사모(紗帽)의 모양이 다소 변한 것으로 보아 책록된 시기보다 몇 년 뒤에 그려진 것으로 추정된다. ○○의 주인공인 오리 ○○○의 자(字)는 공려(公勵), 호(號)는 오리, 본관은 전주이며 태종의 아들 익녕군(益寧君) 치의 현손(玄孫)이며 이억재의 아들로 태어났다. 1569년(선조 2년)별시 문과에 급제하여 대사헌, 호조판서, 이조판서 등을 지냈으며 조선시대 대표적인 청백리로 유명하다.","a":"이원익 초상","c":"보물","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2016062713022600.jpg"},{"q":"지권인(智拳印)의 비로자나불을 본존으로 하고 좌우에 약사불(向右)과 아미타불(向左)을 배치한 삼불형식으로, 흙으로 제작한 소조상이다. 임진왜란 이후 17세기에는 대형의 소조불상이 많이 만들어졌는데 이 삼불좌상은 보물 보은 법주사 ○○○○○, 보물 완주 송광사 소조석가여래삼불좌상 등과 더불어 이러한 양상을 입증하여 주는 좋은 예이다. 이 삼불좌상은 규모가 매우 커서 보는 이를 압도하게 하는데, 인자하고 부드러운 얼굴표현과 허리가 긴 장신형(長身形)의 불신(佛身)은 매우 우아하고 품위 있는 불격을 보여준다.","a":"김제 귀신사 소조비로자나삼불좌상","c":"보물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618709.jpg"},{"q":"절에 행사가 있을 때 절 입구에 당(幢)이라는 깃발을 달아두는데 이 깃발을 달아두는 장대를 당간(幢竿)이라 하며, 장대를 양쪽에서 지탱해 주는 두 기둥을 ○○○○라 한다. 이 ○○○○는 양 지주가 원래 모습대로 85㎝ 간격을 두고 동서로 서 있다. 이곳을 중초사터라고 하는 것은 서쪽지주의 바깥쪽에 새겨진 기록에 따른 것이다. 현재 지주의 기단은 남아있지 않고, 다만 지주 사이와 양쪽 지주의 바깥에 하나씩 총 3장을 깔아서 바닥돌로 삼고 있는데, 이 역시도 원래의 모습이라고 보기는 어렵다.","a":"안양 중초사지 당간지주","c":"보물","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615580.jpg"},{"q":"건물은 일제강점기에 ○○에서 포목점과 소규모 농장을 운영하며 ○○부협의회 의원을 지낸 일본인이 건립한 ○○○ 2층 목조 ○○이다. ‘ㄱ’자 모양으로 붙은 건물이 두 채 있고 두 건물 사이에 꾸며놓은 ○○○ 정원에는 큼직한 석등이 있다. 1층에는 온돌방, 부엌, 식당, 화장실 등이 있고 2층에는 일식 다다미방과 도코노마 등이 있어 일제강점기 일본인 지주의 생활양식을 엿볼 수 있으며 아울러 이들의 농촌 수탈 역사를 알 수 있다. 영화 ‘장군의 아들’과 ‘타짜’를 촬영하기도 하였다.","a":"군산 신흥동 일본식 가옥","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668734.jpg"},{"q":"이 교회는 구한말 탁지부 관리를 지낸 김종숙(1872~1956)이 건립하였다. 예배당은 원래 정면 3간, 측면 3간의 정방형 건물이었으나, 1990년에 앞쪽에 현관을 만들면서 붉은 벽돌로 증축되었다. 내부의 강단과 아치형 나무 장식은 원형 그대로 잘 보존되어 있다. 예배당과 함께 지어진 명동서숙은 종교 교육과 함께 국어, 수학, 한문 등 신자들을 교육하던 건물이다. 이 교회는 선교사나 단체가 아니라 교인의 선구적인 의지로 설립했다는 점에서 가치가 있다.","a":"봉화 척곡교회","c":"국가등록문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669107.jpg"},{"q":"○○○○○의 안채와 사랑채는 1922년 건립되었고, 행랑채는 1930년에 건립되어 역사가 그리 오래되지 않았으나 개화기 전통가옥 형식에 근대의 건축기법이 가미되는 당시의 시대상과 건축적 특징, 건축양식의 시대 변화를 잘 보여주고 있음","a":"익산 김병순 고택","c":"국가민속문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2019031514424500.JPG"},{"q":"○○○은 1동, 1층 규모로 건축면적 90.6㎡, 철로길이 좌·우 각각 150m이다. ○○○은 경전선로로 1930년 12월 25일 간이역으로 영업을 개시하였으며, 1948년 5월 3일 보통역으로 승격하였으며, 1950년 2월 7일 여순반란사건으로 역은 소실되어 1956년 7월 17일 신축되었다. 6.25동란과 1.4후퇴 때에 인민군의 장악과 전투가 있었던 아픈 역사를 가지고 있다. 현재도 간이역으로 사용되고 있다.","a":"나주 구 남평역","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669001.jpg"},{"q":"○○○○○ 본관은 원통형 매스를 중심으로 주변에 단순 입방체가 결합되어 전체적으로 기하학적, 추상적 형태와 공간을 강조하였고, 원통형 옥탑 구조물, 곡면의 현관과 캐노피, 상층부 돌림띠의 요철장식 등 근대 모더니즘 건축 기법을 나타내고 있다. “노장(露場)”이라 불리는 우량계측실과 계절적인 변화를 관측하기 위해 식재된 단풍나무, 벚나무 등 ○○○○을 위한 부속시설도 잘 남아 있다. 경기도립경성측우소 청사로 건립된 후 현재까지 ○○○○용도로 사용되고 있는 등 우리나라 ○○○○의 역사를 증명하는 장소로 가치가 있다.","a":"서울 기상관측소","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667676.jpg"},{"q":"신라 경문왕 7년(862) 도의선사가 창건한 ○○○에 모셔져 있는 이 삼불좌상은 본존불인 석가불을 중앙에 안치하고, 오른쪽에는 아미타불, 왼쪽에 약사불을 배치하고 있다. 무량사 소조아미타불상(5.4m)과 함께 가장 거대한 소조불상(5m)으로, 신체 각 부분이 비교적 조화를 잘 이루고 있는 작품이다. 장중하고 원만한 얼굴과 두껍게 처리한 옷은 당당한 불상양식에 걸맞는 표현기법을 보여준다. 작은 소라 모양의 머리칼 표현은 강한 인상을 나타내고 있는데 이는 조선 후기 양식이 나타나기 시작한 시대적 특징을 보여주는 것이다.","a":"완주 송광사 소조석가여래삼불좌상 및 복장유물","c":"보물","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618685.jpg"},{"q":"○○○○○는 높이 12.9㎝로 솥 모양의 몸체(훈구부)를 받침부(기대부)가 받치고 있는 모습이며, 몸체에 도깨비 얼굴을 형상화시켜 놓았다. 몸체의 윗부분인 구연부에는 3개의 굴곡진 산형(山形)으로 처리되었고 삼각형 모양이 솟아 있고, 몸체 양 측면에는 각각 2개의 고리가 달려 있다. 그 고리에 손잡이 장식을 달았던 것으로 보이는데, 지금은 남아 있지 않다. 몸체의 아랫부분은 밑으로 가면서 잘록해지면서 받침부와 연결되었는데, 잘록한 부분에는 도깨비 얼굴을 크게 새기고, 입을 뚫어서 내부로 관통되도록 만들었다.","a":"귀면 청동로","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611595.jpg"},{"q":"○○시내 평지 서남쪽에 위치한 4기의 봉토무덤과 1기의 원형무덤이다. 『삼국사기』에는 신라 시조 박혁거세와 제2대 남해왕, 제3대 유리왕, 제5대 파사왕 등 신라 초기 4명의 박씨 임금과 혁거세의 왕후인 알영왕비 등 5명의 무덤이라 되어 있다. 『삼국유사』에는 혁거세왕이 임금자리에 있은지 62년 만에 하늘로 올라갔다가 7일 후에 몸이 흩어져 땅에 떨어지자 왕비도 따라 죽으니, 사람들이 같이 묻으려고 했으나 큰 뱀이 방해해서 몸의 다섯부분을 각각 묻었는데, 그것을 ○○ 또는 사릉(蛇陵)이라 했다고 한다.","a":"경주 오릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627762.jpg"},{"q":"○○○란 죽은 사람의 생전의 행적을 기록하여 묘 앞에 세우는 비이다. 조선시대에는 정2품이상의 관직에 있는 사람 중 위업을 세웠거나 학문이 뛰어나 후세에 모범이 될 때에 ○○○를 세워 기리도록 하였다 한다. 이 비는 조선시대의 문신 윤효손의 ○○○이다. 윤효손(1431∼1503)은 단종 원년(1453)에 과거에 급제하여 황해도관찰사, 형조판서, 우참찬 등을 두루 거쳐 좌참찬에 이르렀다. 성종때에는『경국대전』과『오례의주』를 편찬하기도 하였다. 연산군 9년(1503)에 세상을 떠났으며, 시호는 ‘문효(文孝)’이다.","a":"구례 윤문효공 신도비","c":"보물","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619293.jpg"},{"q":"섬진강이 반달꼴로 끼고 돌며 멀리 광주 무등산까지 거침없이 바라보이는, 풍수지리상 우리나라에서 가장 아름다운 집자리 가운데 하나일 것이다. 조선 후기의 건물로 '군지촌정사'는 사랑채의 이름이며, 안채, 대문간채와 더불어 전체를 이루고 있다. 전해오는 바에 의하면 18세기 중엽에 건축되었다고 하나 안채는 19세기 초 정도에 지어진 것으로 추정된다. 안채는 '一'자형으로 서쪽부터 2칸의 부엌이 위·아래에 있으며, 그 옆에 큰방이 있는데 앞·뒤에 툇마루를 깔았다. 전면에 2칸의 대청이 있고, 뒷쪽에는 도장과 작은방이 있다.","a":"곡성 제호정 고택","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634628.jpg"},{"q":"신라시대 종의 형태를 하고 있는 고려 범종으로, 종의 꼭대기 부분에 종을 매다는 용뉴와 뒷편에는소리의 울림을 도와주는 용통이 솟아있다. 종의 몸체의 위와 아래에는 횡선의 띠를 두르고, 연당초문을 동일하게 새겨 넣었다. 3분의 1되는 곳 위쪽으로는 사각형의 연곽을 만들고, 그 안에 나즈막하게 돌출된 9개씩의 연뢰(蓮蕾)를 장식하였다. 또한 종의 몸체 아래쪽으로 중국이나 일본에서는 볼 수 없는, 종을 치는 곳인 당좌를 앞·뒷면 두 곳에 배치하였다.","a":"포항 오어사 동종","c":"보물","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622164.jpg"},{"q":"1945년 무렵 건립 이 시설물은 ○○도민들보다는 다른 지방 주민들, 특히 전남 지방 광산 노동자들이 대거 동원되어 구축되었다. 1기는 ‘王’자형, 나머지는 ‘一’자형으로 모두 18곳으로 구성되어 있다. 이 가운데 일자형 ○○○○는 일본군이 연합군 함대를 향해 자실 폭파 공격을 하기 위한 소형선박을 보관하기 위한 격납고로 구축되었다. 시설 부대와 주둔 부대 등에 대한 기록이 분명하게 남아 있어 일본군 주둔 실상과 침략 야욕을 생생히 보여주고 있다.","a":"제주 일출봉 해안 일제 동굴진지","c":"국가등록문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669587.jpg"},{"q":"1925년 건립된 이 건물은 일제 강점기 ○○ 청년들의 항일 운동 근거지였으며, ‘조선청년’이란 잡지를 발행한 역사적인 장소이다. 회관 건립을 위한 모금 운동으로 각계각층의 기금을 모아 건립된 것이기에 특별한 디자인 요소 없이 각 부분이 기능적으로 처리되었다. 일제 강점기 ○○ 청년들이 펼쳤던 민족 운동의 산실이며, 우리 민족 스스로의 자주성으로 건립·운영된 건물로 ○○ 청년 운동의 중심 역할을 했던 곳이다.","a":"목포 구 청년회관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668843.jpg"},{"q":"송나라 진실(陳實)이 불교 경전인 『대장경』에서 중요한 내용을 뽑아서 엮은 것인데, 고려 초 13세기 중엽에 간행한 것이다. 이 책은 제1권 상·중·하 1책으로 구성된 영본(零本)인데, 내용을 보면 선왕품으로부터 번뇌품에 이르기까지 총 17품에 대하여 설명하고 있다. 판심 하단부에는 존식·정안 등의 각수 이름이 새겨져 있다. 판식에 있어서 송본의 형태를 유지하고 있으며, 12세기의 『능엄경』이나 『선문염송』 등과 같이 좁은 판심에 흑어미가 가늘게 이중으로 처리되어 있다. 서체도 송본과 13세기 중반에 유행한 고려본과 같은 형식이다.","a":"대장일람집","c":"보물","nc":"","r":"대구광역시","s":"달서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615286.jpg"},{"q":"제복이란 왕이 종묘사직에 제사 지낼때 입었던 옷으로 나라에 경사가 있을 때 입는 조복과 모양이 비슷하지만 머리에 쓰는 금관인 양관에 금칠이 훨씬 적고 붉은옷의 ○○○가 아닌 푸른색의 청초의를 입었다. 이 옷은 붉은 갑사로 지어졌으며 깃과 옷둘레에는 검은 선을 두루고 선사이에 0.3㎝정도의 흰색선을 두었다. 『경국대전』에 의하면 이 옷은 대한제국말의 조복과 같은 모습을 하고 있으며 왕의 조복에 해당하는 강사포나 제복인 구장복과는 차이가 난다. 따라서 이 옷은 왕이 아닌 문무의 신하들의 입던 조복이었을 가능성이 크다.","a":"적초의","c":"국가민속문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633221.jpg"},{"q":"『○○○○○』은 조선 태조에서부터 조선 철종 때까지 25대 472년간(1392∼1863)의 역사를 편년체(編年體:역사적 사실을 일어난 순서대로 기술하는 역사서술의 한 방식)로 기록한 책이다. 이것은 조선시대 사회, 경제, 문화, 정치 등 다방면에 걸쳐 기록되어 있으며, 역사적 진실성과 신빙성이 매우 높다. 또한 사료의 편찬에 있어서 사관이라는 관직의 독립성과 기술에 대한 비밀성도 보장되었다. 실록을 편찬하는 작업은 다음 왕이 즉위한 후 실록청을 열고 관계된 관리를 배치하여 펴냈으며, 사초는 임금이라 해도 함부로 열어볼 수 없도록 비밀을 보장하였다.","a":"조선왕조실록 태백산사고본","c":"국보","nc":"","r":"부산광역시","s":"연제구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2593975.jpg"},{"q":"조선 중기의 대표적인 유학자인 우암 ○○○ 선생의 ○○화이다. ○○○ 선생은 조선의 대표적 성리학자로 평생 주자학연구에 몰두하여 율곡 이이의 학통을 잇는 기호학파의 주류였다. 그는 논리적이고 힘있는 문장과 서예로도 평판이 높았다. 이 ○○화는 세로 89.7cm, 가로 67.6cm로 비단바탕에 채색하여 그린 반신상이다. 머리에는 검은색 건을 쓰고 유학자들이 평상시에 입는 옷인 창의를 걸치고 오른쪽을 바라보고 있다. 과장되게 표현된 거구의 몸체와 개성적인 눈썹 그리고 깊게 패인 광대뼈의 주름에서는 학식의 깊이를 느끼게 한다.","a":"송시열 초상","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611818.jpg"},{"q":"○○○○란 칼의 손잡이 끝부분에 둥근 고리가 있는 고리자루칼로서, 삼국시대 무덤에서 주로 출토된다. 고리 안에는 여러가지 장식이 들어가는데, 이것은 이 칼을 사용한 사람의 신분을 나타내 준다. 그 가운데 용이 조각된 것은 가장 높은 신분에서 사용하였다. ○○○○는 금으로 된 칼의 손잡이 부분과 철로 된 칼날 부분으로 구성되어 있다. 현재 떨어져 있으나 원래 같이 붙어 있었다. 손잡이 부분은 표면 전체에 서로 엉킨 두 마리의 용이 조각되어 있다. 고리 안에도 두 마리 용이 조각되어 있으며, 용의 눈은 옥으로 장식되어 있다.","a":"환두대도","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613899.jpg"},{"q":"백제 무왕이 수도를 왕궁평으로 옮기려고 지은 궁궐 근처에 불교의 수호신인 제석천을 중심 불상으로 모신 절이 있던 자리이다. 기록에 의하면 무왕 40년(639)에 벼락으로 절이 모조리 불에 탔을 때 탑 아래 넣어 두었던 동판에 새긴 금강반야경과 불사리만은 보존되어 다시 절을 지은 후 보관하였다고 한다. 탑터로 생각되는 지역에서 ○○○라고 적힌 기와조각이 발견됨으로써 절의 이름이 밝혀졌다. 주목되는 점은 1965년 백제 무왕의 궁터라고 전하는 왕궁평 성안의 석탑에서 발견한 유물과 이곳에서 발견된 유물이 비슷하다는 점이다.","a":"익산 제석사지","c":"사적","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626956.jpg"},{"q":"○○○○○는 영남사림파의 종장인 ○○○이나 그의 후손들과 관련된 것으로 중요성이 크다. 그 중에서도 특히 ○○○에게 내려진 교지나 교첩, 그의 후손들이 소과나 무과에 합격하여 받은 홍패와 백패, 그리고 각종 사령장 등은 조선 전기와 중기의 과거제도 와 관료제도를 연구하는데 매우 중요한 자료이다. 또 ○○○과 그의 후손들이 부모나 친척들로부터 재산을 분배받으며 작성한 분재기나 토지나 노비를 매득하고서 작성한 매매문서와 입안 등이 다수 전하고 있는데 이들 문서는 조선 전기와 중기 재산의 분배 양상과 매매 관행을 연구하는데 매우 유용할 것으로 판단된다.","a":"김종직 종가 고문서","c":"보물","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622307.jpg"},{"q":"○○○○○은 광주사범대학 본관으로 건립된 건물로 광주, 전남과 제주를 중심으로 활동했던 건축가 김한섭이 설계하였음. 외관은 각 교실의 기본 모듈을 바탕으로 창과 벽돌 기둥을 번갈아 가면서 리듬감 있게 구성하였고, 시멘트와 철근이 귀하던 시절에 조적조와 목조 지붕틀을 주 구조체로 하면서 횡력을 보강하기 위해서 벽돌거푸집 콘크리트 기둥 방식을 사용한 것이 특징적임.","a":"광주교육대학교 교육박물관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2126592.jpg"},{"q":"조선시대 성리학 중심지 중 한 곳인 우암 ○○○○○이다. ○○○은 조선 후기의 성리학자이자 문신으로 조선 효종(재위1649∼1659)을 도와 북벌정책을 추진하는 등 자주적인 정치를 펼쳤으며, 주자학의 대가로서 많은 인재를 양성하였다. 화양서원은 우암 ○○○이 잠시 머물렀던 장소에 세워진 서원으로 조선시대 학자들이 많이 모였던 장소이다. 만동묘의 자리는 중국 명나라 황제인 신종과 의종의 위패를 모신 사당이 있던 곳이다.","a":"괴산 송시열 유적","c":"사적","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626350.jpg"},{"q":"○○읍 무기산을 중심으로 뻗어나간 구릉 주변에 있는 7기의 가야 무덤들이다. 가장 높은 곳에 1호 무덤이 있고 점차 밑으로 내려가면서 나머지 6기의 무덤들이 자리잡고 있다. 이 지역에서 북쪽으로 300m 거리에 기원리 무덤들이 있고, 동쪽으로 300∼400m 거리에 ○○○ 조개더미가 있어, 삼국시대 소가야국의 자리를 나타내주고 있다. 1호 무덤은 겉모습에서 앞이 네모나고 뒤가 둥근 무덤인 전방후원형 무덤으로 보여지기도 하나, 발굴조사 결과 흙을 쌓아 구릉처럼 만든뒤 돌무덤방을 만든 가야 고유의 형식을 취하고 있다.","a":"고성 송학동 고분군","c":"사적","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628239.jpg"},{"q":"마한의 왕궁이 있던 자리로 알려진 터에 있는 ○○○○○을 보수하기 위해, 1965년 해체하면서 탑을 받치고 있던 기단부와 1층 지붕돌 윗면에서 발견된 유물들이다. 발견된 유물들은 백제에서 통일신라에 이르는 시기의 것들로 판단된다. 기단부 윗면에 品자형으로 뚫린 3개의 구멍 중 동쪽에서는 광배와 대좌를 갖추고 있는 금동여래입상 1구와 불교 의식 때 흔들어 소리를 내던 청동방울 1개가 나왔고, 북쪽구멍에서는 향류(香類)가, 또 다른 구멍은 이미 도굴된 상태였다.","a":"익산 왕궁리 오층석탑 사리장엄구","c":"국보","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612358.jpg"},{"q":"<○○○○○>은 화면의 좌측 상단에 “初封延仍君古號養性軒”이라 적혀있어 이 본이 영조가 임금이 되기 이전에 제작된 延礽君 시절 圖寫本임을 알 수 있다. 紗帽, 白澤 胸背를 부착한 綠袍團領, 犀帶, 검은색 녹피화 등으로 구성되어 있는 정장관복차림에 공수자세로 앉아 있는 좌안8분면의 전신교의좌상이다. 이 상은 영조 21세(1714년) 때 진재해(?-1735 이전)가 그린 것으로 영조 21년(1745)에 慶熙宮 泰寧殿에 봉안되었다가 정조가 즉위하자 잠시 景賢堂에 두었다가 정조 2년(1778년) 3월에 선원전으로 이봉되었다.","a":"연잉군 초상","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614877.jpg"},{"q":"조선시대 전기의 ○○○으로 높이 36.2㎝, 아가리 지름 7.4㎝, 밑지름 13.5㎝이다. 벌어진 아가리에서 긴 목을 지나 몸통까지 유연한 곡선을 이루고 벌어져 풍만한 몸체를 이루었으며, 넓고 높은 굽다리를 갖춘 안정감을 주는 병이다. 묵직한 기벽에 푸른빛이 도는 백색 유약을 고르게 발랐으며, 광택이 은은하다. 이러한 ○○는 경기도 광주에서 15세기 후반에서 16세기 전반에 걸친 시기에 만들어진 것으로 추정된다. 풍만하고 단정하며 격식있는 병의 형태와 부드러운 색이 어울리는, 조선초기의 대표적인 병의 하나이다.","a":"백자 병","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614418.jpg"},{"q":"○○○○○은 부처님의 열반을 다루고 있는 경전으로, 중생들에게 열반을 종교적·철학적으로 깊이 이해시키기 위해 만든 것이다. 이 책은 담무참(曇無嘴)이 번역한 ○○○○○에 당나라 법보(法寶)가 주석을 붙인 것으로, 권9와 10이 한 책으로 되어있다. 닥종이에 찍은 목판본이며 크기는 세로 35.5㎝, 가로 32.7㎝이다.","a":"대반열반경소 권9~10","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618746.jpg"},{"q":"○○○○○은 대학교 교사로서 강의를 위한 실용적인 목적이 강조된 건축물로 모더니즘 건축의 조형적 특징이 잘 표현된 건축물이다. 특히, 중앙 출입구 포치와 파사드의 수직·수평적 요소, 과감한 블록처리는 당시 단순화 된 고딕양식에 근대성과 조형성을 가미한 것으로 희소성 측면에서 보존 가치가 있다.","a":"전북대학교 구 문리과대학","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019120914292400.jpg"},{"q":"○○○○○의 전신인 경북도립 사범학교는 일제강점기 식민지 교육정책 실행에 필요한 교원 양성을 목적으로 설립하였다. 본관은 정면 중앙에 사각 기둥을 4개 세우고 그 위에 평지붕을 올린 돌출 현관을 두었고, 현관의 돌기둥 앞에는 공 모양으로 만든 대형 장식 석물을 2개 올렸다. ○○은 우진각 지붕 앞뒤에 반원형 지붕창을 6개 설치하였으며, 외벽 양옆 모서리에는 버팀기둥을 세워 벽이 구조적으로 안정되게 하였다.","a":"구 대구사범학교 본관과 강당","c":"국가등록문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667783.jpg"},{"q":"<○○○○>은 오른쪽 1/3이 소실되었지만 남아 있는 왼쪽 상단에 “予三十一歲 哲宗熙倫正極粹德純聖文顯武成獻仁英孝大王”이라고 적혀 있어 이 어진이 철종 12년(1861)에 도사된 것임을 알 수 있다. 규장각에서 펴낸 『御眞圖寫事實』에 의하면, 李漢喆과 趙重黙이 주관화사를 맡았고, 金夏鍾, 朴基駿, 李亨祿, 白英培, 白殷培, 劉淑 등이 도왔다고 한다. 당시 1개월여에 걸쳐 絳紗袍本과 軍服本을 모사했으나 현재 군복본만 현전한다. 이 <○○○○>은 임금이 具軍服으로 입고 있는 초상화로는 유일한 자료이다.","a":"철종어진","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614878.jpg"},{"q":"ㅇ조각에 불화를 접목한 중요한 사례에 해당. 근대기의 출발점에 있는 불교 조각이며 인근에 조성된 근대기 회화성 짙은 마애불상의 제작에도 많은 영향을 주고 있음. ㅇ19세기 유행한 불화의 초본을 바위에 옮긴 것처럼 불화의 시대적 특징이 잘 드러나 있으며 희소성의 가치가 있음.","a":"양산 통도사 자장암 마애아미타여래삼존상","c":"국가등록문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2401329.jpg"},{"q":"충청남도 ○○의 ○○○○에 남아 있는 석조불상으로 ○○○○○ 오층석탑(국보)와 남북으로 마주보고 있다. 정림사는 6세기 중엽에 처음 창건되어 백제 멸망 때까지 번창하였던 사찰로 고려시대에 다시 번창했던 것으로 추정되는데, 이 석불상은 고려 때의 번성을 보여주는 것이다. 지금의 머리와 보관은 제작 당시의 것이 아니라, 후대에 다시 만들어 얹은 것으로 보인다. 신체는 극심한 파괴와 마멸로 형체만 겨우 남아 있어 세부적인 양식과 수법을 알아보기 어렵지만, 어깨가 밋밋하게 내려와 왜소한 몸집을 보여준다.","a":"부여 정림사지 석조여래좌상","c":"보물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617517.jpg"},{"q":"왕실이 후원한 미술교육기관인 서화미술원에서 교육받은 대표적 신진 화가인 노수현에 의해 1920년경 제작되어 ○○○에 부착된 벽화로, 장승업 이후 안중식이 이룬 반복적 형태의 산수화의 전통을 잘 보여주고 있으며, 형상의 표현과 기술묘사에 충실하여 화려한 구성을 담고 있다. 궁중 벽화로는 다른 5점과 더불어 유일하게 현존하고 있으며, 단순한 장식이 아닌 전각의 기능과 연계되어 추락한 왕실의 안녕 및 권위의 회복, 왕실의 역량을 재확인하는 길상적, 상징적 의미를 갖고 있어 역사적, 예술적 가치가 있다.","a":"창덕궁 경훈각 조일선관도","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667056.jpg"},{"q":"신라 제35대 ○○○의 무덤이라 전해지는 곳으로 ○○ 시가지에서 서남쪽으로 멀리 떨어진 구릉에 자리하고 있다. ○○○은 성덕왕의 아들이며 이름은 헌영이다. 신라 왕실의 전제왕권이 쇠퇴되기 시작하는 시기에 왕위에 올라 행정구역 개편·직제개편 등을 단행하였다. 봉분은 둥근 모양이며, 무덤 주위에 봉분을 보호하기 위한 둘레돌을 둘렀다. 둘레돌은 목조건축물의 돌기단 같은 형태로 되어 있는데, 바닥돌을 깔고 그 위에 면석을 둘렀다. 면석 사이에는 기둥 역할을 하는 탱석을 배치하였다. 탱석에는 두 칸 건너 하나씩 무인 복장을 하고 무기를 든 12지신상이 조각되어 있다.","a":"경주 경덕왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627565.jpg"},{"q":"절에서는 행사나 의식이 있을 때 사찰 입구에 당(幢)이라는 깃발을 달아두는데, 이 깃발을 매달아두는 길쭉한 장대를 당간(幢竿)이라 하며, 당간의 좌우에 세워 단단히 지탱해 주는 두 돌기둥을 ○○○○라고 한다. 드물게 당간이 남아 있으나 대개는 두 지주만 남아 있다. 이 ○○○○는 남간사의 옛터에서 약 500m 떨어진 논 가운데에 세워져 있다. 논을 경작하면서 지주의 아래부분이 약 50㎝정도 드러나 있으며, 바닥돌은 없어진 상태이다. 기단부가 없어서 기단 위에 당간을 세우던 받침돌도 찾아볼 수 없다.","a":"경주 남간사지 당간지주","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621787.jpg"},{"q":"○○○○○은 수태산에서 채취한 2~3cm 두께의 납작돌과 황토로 쌓아 다른 마을의 ○○과는 차별되는 모습을 보여주고 있다. 토석담은 0.4~1m 높이까지 큰 납작돌을 쌓고, 그 위에 작은 납작돌과 진흙을 쌓아 올린 뒤 맨 위에 큰 판석을 올려 만들었다. 건물의 기단, 후원의 돈대 등에도 이와 같은 방식이 사용되어 ○○과 조화를 이루고 있으며, 마을 주변 대숲과도 잘 어우러져 남도의 정취가 물씬 풍기는 아름다운 경치를 자아내고 있다.","a":"고성 학동마을 옛 담장","c":"국가등록문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669458.jpg"},{"q":"○○○○○- ○○○○○(驪州李氏 玉山門中 典籍 - 驪州李氏 玉山門中 典籍)은 아래와 같다 ㅇ 이륜행실도(二倫行實圖, 1539년) : 이 책은 현재 알려진 국내 소장본 중 가장 빠른 본에 속하며 조선시대 유학사상 및 윤리관을 살펴볼 수 있는 귀중한 자료이다. 또한 도판 및 언해, 권말의 판각기록은 조선시대 판화(版畵)의 변천, 국어사·서지학 연구에 중요한 자료이다.","a":"여주이씨 옥산문중 전적","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621166.jpg"},{"q":"충청남도 ○○ 칠갑산에 자리잡은 ○○○의 상대웅전 안에 모셔져 있는 불상으로 진리의 세계를 두루 통솔한다는 의미를 지닌 비로자나불을 형상화한 것이다. 삼각형에 가까운 작은 얼굴에는 긴 눈썹과 가는 눈, 작은 코와 입 등이 표현되어 다소 세속화된 모습이다. 어깨는 넓지만 볼륨은 약화되었다. 옷은 오른쪽 어깨를 드러내고 왼쪽 어깨만을 감싸고 있는데, 드러나 있는 오른쪽 어깨가 너무 소홀하게 처리된 느낌이다. 두 손은 가슴 앞에서 왼손 검지를 오른손으로 감싸고 있는데 이는 비로자나불만이 취하는 독특한 손모양으로 부처와 중생이 하나라는 의미를 지닌다.","a":"청양 장곡사 철조비로자나불좌상 및 석조대좌","c":"보물","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617570.jpg"},{"q":"이 수원지는 ○○시 중심부 점방산, 설림산 기슭을 흐르는 물이 모이는 곳으로, ○○ 지역에 식수를 공급하기 위하여 1912년 공사를 시작한 뒤 연인원 10만 명을 동원해 3년 만에 완공하였다. 이 지역 대다수 시민이 우물물을 길어 마실 때 건립한 수원지로, ○○과 수문, 수위측정 탑은 근대 초기 산업 시설물 건립의 수준을 잘 보여 준다.","a":"군산 구 제1수원지 제방","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668757.jpg"},{"q":"최초의 근대소설 《무정》을 발표한 ○○○ 선생이 살던 ○○○이다. 남아 있는 한옥은 1970년경 새로 지은 건물이나, 우물과 향나무는 당시 모습이 남아 있다. ○○○는 근대문학사에서 선구적인 작가로 평가받고 있으나,「일제강점하 반민족행위 진상규명에 관한 특별법」에 따른 친일반민족행위진상규명 보고서에 포함된 인물이다.","a":"서울 홍지동 이광수 별장 터","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666949.jpg"},{"q":"경문왕의 둘째 아들인 신라 제50대 ○○○의 무덤이다. ○○○은 형인 헌강왕에 이어 886년 7월에 왕위에 올랐으나 887년 7월에 병으로 죽어 왕위에 있던 기간이 만 1년밖에 되지 않았다. 무덤의 외형은 흙으로 덮은 둥근 형태로, 무덤을 보호하기 위해 밑둘레에 3단으로 돌을 쌓았다. 그 중 제일 밑단만이 밖으로 약간 나왔으며, 무덤 앞에는 돌단이 있는데, 그 위에 돌로 만든 작은 제삿상이 있다. 무덤의 구조는 헌○○○과 같다.","a":"경주 정강왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627812.jpg"},{"q":"탑이 부처의 사리를 모시는 곳이라면, ○○은 유명했던 스님들의 사리를 두는 곳이다. ○○의 구성은 석탑과 같아서, 기단(基壇) 위에 사리를 모시는 탑신(塔身)을 두고 그 위에 머리장식을 얹는다. 이 ○○은 ○○○의 동쪽에 네모난 바닥돌위로 세워져 있으며, 전체적으로 8각형을 기본으로 하고 있다. ○○○는 고려 전기까지 스님들이 선(禪)을 닦는 절로 이름이 높았는데, 이 때문인지 이곳에는 이 ○○ 외에도 ○○○○○ 소요대사탑(보물), ○○○○○ 북 ○○ 등 2기가 더 있다. ○○○은 그 중 형태가 가장 아름답고 우아한 작품이다.","a":"구례 연곡사 동 승탑","c":"국보","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612474.jpg"},{"q":"○○국사(827-898)는 신라말기에 활동한 선승으로, 남쪽지역의 비보사찰(裨補寺刹)로 ‘巖’자가 들어가는 세 절인 삼암사(三巖寺)의 하나로 ○○○를 중창하였다. ○○국사○○은 두 발을 받침대 위에 올려놓은 의좌상(椅坐像)으로, 오른손에는 주장자를 세워 들고 있다. 옷주름의 표현이 특이한데 녹색장삼은 색의 농·담(濃·淡)으로, 붉은 가사의 옷주름은 먹선과 흰선을 중첩하여 표현하고 있다. 화기에 따르면 1805년에 도일비구(道日比丘)가 ○○○ 대각국사(보물) ○○과 함께 중수한 것으로, 이 두 ○○은 유사한 화풍을 보여주고 있다.","a":"순천 선암사 선각국사 도선 진영","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619962.jpg"},{"q":"○○○은 국가에서 ○○○신에게 제사 지내기 위해 마련한 조선시대의 건축물이다. ○○○은 예로부터 신령스러운 산으로 여겨져 왔으며, 신라 때 5악의 하나로 제사를 지냈다. 조선시대에는 북쪽의 묘향산을 상악으로, 남쪽의 지리산을 하악으로, 중앙의 ○○○을 중악으로 하여 단을 모시고 산신에게 제사를 지냈다. 무학대사의 꿈에 산신이 나타났다는 말을 듣고 태조 3년(1394)에 처음 제사를 지냈다고 전하며, 효종 2년(1651)에 제단이 폐지되었다. 그 후 고종 16년(1879)에 명성황후의 명으로 다시 짓고 ○○○이라 하였다.","a":"공주 계룡산 중악단","c":"보물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618053.jpg"},{"q":"토수란 지붕의 추녀나 사래 끝이 비바람에 부식되는 것을 막기 위해 끼우는 용머리형의 기와이다. 높이 30.5㎝, 길이 35.2㎝의 이 토수는 목 부분을 방형으로 절단하고, 그 속을 비워 나무를 끼울 수 있게 하였고, 나무를 고정시키기 위해 못 구멍 좌우에 각각 2개씩 뚫었다. 전체를 도금하였으나 현재는 대부분 탈락되었다. 용은 눈을 크게 부릅뜨고 있으며, 뭉툭한 윗이빨이 아래입술 위로 돌출되어 있다. 코는 짧게 처리했고 약간 불거져 나온 눈동자를 2단으로 만들어 생동감 있게 처리하였다.","a":"금동용두토수","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613909.jpg"},{"q":"'ㅁ'자형의 전형적인 교육시설의 특징을 갖고 있는 한국 근대공업교육의 최고학부(경성제국대학)건물로서 경성제국대학 이공학부 ○○를 현 위치에 옮기면서 본관으로 이용하였다. 광복후 ○○○○○ 본관으로 사용하다가 관악캠퍼스 이전후 서울과학기술대학교 다산관으로 사용되고 있다.","a":"서울대학교 구 공과대학 본관과 교사","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666883.jpg"},{"q":"경상남도 ○○군 하산리 사근장터 뒤 연화산에 있는 돌로 쌓아진 산성이다. 이곳은 조선시대 경상도 지방 14개의 역길을 총괄하던 중심역인 사근역이 있던 곳이다. 성을 쌓은 시기는 확실히 알 수 없으나 산성의 규모와 이곳이 신라와 백제 사이의 분쟁지역이었다는 점을 생각해 보면 삼국시대에 세워졌다는 것이 추측된다. 성은 부분적으로 무너졌으나 비교적 잘 남아 있는 편이다. 둘레는 약 1,218ｍ이고, 연화산의 지형에 따라 쌓은 ‘ㅏ ’자형의 산성이다. 성벽은 네모난 가공석과 자연석을 약 5ｍ 높이로 정연하게 어긋쌓기를 하였는데 밑바닥의 넓이가 5ｍ나 된다.","a":"함양 사근산성","c":"사적","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628255.jpg"},{"q":"경상북도 ○○시 건천읍 ○○○ 중턱에 이르면 거대한 암벽이 ㄷ자 모양으로 높이 솟아 하나의 석실(石室)을 이루고 있음을 볼 수 있다. 여기에 인공적으로 지붕을 덮어서 석굴 법당을 만들었을 것으로 생각되는데, 바위면에는 10구의 불상과 보살상이 새겨져 있어 장관을 이루고 있다. 동북쪽의 독립된 바위면에는 도드라지게 새긴 높이 8.2m의 여래입상이 1구 서 있다. 둥근 얼굴에 미소가 가득하며, 머리 위로 2단으로 된 상투 모양의 머리묶음이 작게 솟아있다. 양 어깨를 감싸고 있는 옷에는 U자형 주름이 선명하고, 트인 가슴 사이로는 띠매듭이 보인다.","a":"경주 단석산 신선사 마애불상군","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612876.jpg"},{"q":"통일신라시대 모전탑 계열에 속하는 탑으로써, 모전탑은 전탑(전탑:흙으로 구운 벽돌로 쌓은 탑)을 모방한 것으로, 돌을 벽돌 모양으로 다듬어 쌓아 올린 것을 이른다. 기단(基壇)은 주사위 모양의 커다란 돌덩이 8개를 2단으로 쌓은 독특한 형태로 이루어져 있다. 기단 윗면에 1층 몸돌을 받치기 위한 1장의 평평한 돌이 끼워져 있는데, 남산리 석탑에 3단의 층급이 있는 것에 비하면 간략화된 것이다. 탑신부(塔身部)는 몸돌과 지붕돌이 각각 1장의 돌로 되어 있고, 1층 몸돌에는 큼직한 네모꼴 감실(龕室:불상을 모시는 방)을 얇게 파서 문을 표시하였다.","a":"경주 서악동 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620160.jpg"},{"q":"○○○○○ 가운데 특히 규격이 크고 전면에 선이 굵고 검은 철화문양이 파격적인 필치로 그려져 있는 작품이다. 성형과정에서 굽형태로 깎은 한쪽 마구리와 사용할 때 굽의 기능을 하는 넓고 높은 굽의 안쪽면을 제외한 전면에 귀얄 붓으로 백토를 약간 두텁게 씌웠으며, 조금 얇은 부분은 붓 자국이 그대로 나타나 있다. 문양은 넓은 몸통을 중심으로 그렸는데, 중심에 작은 모란꽃송이와 양편으로 거의 대칭에 가까운 형태의 무성한 모란 잎을 전면이 꽉 찰만큼 듬직하게 그려 넣었다.","a":"분청사기 철화모란문 장군","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614789.jpg"},{"q":"우리나라에서 처음으로 쌓아 만든 최고의 고대 저수지이다. 『삼국사기』에는 신라 흘해왕 21년(330)에 “처음으로 ○○○를 만들었는데, 둘레가 1천 8백보”라는 기록이 있다. 그러나, 이 시기는 이 지역이 신라 땅이 아닌 백제의 땅이었으므로 나중에 연도를 고쳐서 신라가 만든 것처럼 보이도록 해놓았을 가능성이 크다. 그러므로 실제로 만들어진 때는 백제 11대 비류왕 27년(330)으로 보아야 할 것이다. 그 이후 신라 원성왕 6년(790)과 고려 현종 및 인종 21년(1143)에 고쳐 쌓은 후, 조선 태종 15년(1415)에 다시 쌓았다.","a":"김제 벽골제","c":"사적","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626816.jpg"},{"q":"부처가 태어나 도를 닦고 열반에 이르기까지의 일생을 8부분으로 나누어 그린 ○○○이다. 가로 151㎝, 세로 233.5㎝의 비단에 채색하여 그린 이 ○○○는 모두 8폭으로 액자에 끼워 벽에 붙여 놓아 보관하고 있다.","a":"통도사 영산전 팔상도","c":"보물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622863.jpg"},{"q":"산비탈 두 곳의 커다란 암벽에 시기를 약간 달리하여 부조(浮彫)로 조각되어 있는 9구의 불·보살상(佛·菩薩像)이다. 상부에는 높이 3.5m, 폭 8m의 바위면에 불좌상 1구가 양각되어 있고, 하부에는 불좌상 1구와 공양상(供養像)·반가상(半跏像)을 중심으로 5구의 보살상 등 모두 8구가 새겨져 있다.","a":"충주 봉황리 마애불상군","c":"보물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617312.jpg"},{"q":"○○○○○는 신라의 전형적인 평지 이탑식 가람배치(중문‧양탑‧금당‧강당‧회랑)를 기본구조로 하면서 ‘아(亞)’ 자형 건물지 등 독특한 유구가 확인되었으며, 통일신라 시대 전형적인 석탑 양식인 쌍탑에 모두 팔부중이 조각되어 있고 자기류, 전돌류, 토기, 목간, 금속유물, 지진구 등의 많은 유물이 출토되어 신라 사찰건축 등의 연구자료로서 역사적‧학술적 가치가 뛰어남.","a":"경주 인왕동 사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2016101309061400.jpg"},{"q":"이 ○○○은 형산강 물을 농업용수로 사용하기 위하여 설치한 것이다. 외부는 목재 널판으로 마감하였으며, 내부는 펌프와 전동기를 설치하기 위해 기존의 진입 바닥 높이보다 약 4.0m 낮게 콘크리트로 구축하였다. 일제강점기 지방의 ○○○ 시설을 알 수 있는 시설로 가치가 있다.","a":"경주 우안양수장","c":"국가등록문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669139.jpg"},{"q":"벌교와 ○○간의 국도변인 ○○○ 마을 앞 논 한가운데에 세워져 있는 탑이다. 이 곳은 절터로 추정되나 문헌에 남아 있는 기록이 없고, 전해지는 이야기로는 징광사에 딸린 부속 절이 있던 곳이라 하기도 한다. 탑은 기단(基壇)의 일부분이 땅 속에 묻혀 있고, 바닥은 시멘트로 발라져 밑부분의 정확한 모습을 알 수 없다. 드러난 기단부에는 기둥을 본뜬 조각이 새겨져 있다. 탑신(塔身)은 3층을 이루고 있으며 몸돌과 지붕돌이 각각 하나의 돌로 이루어져 있고, 몸돌에는 모서리마다 아주 얇게 기둥모양을 본떠 새겨놓은 것이 보인다.","a":"보성 우천리 삼층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619424.jpg"},{"q":"조선시대 만들어진 ○○○○ 병으로 야외에서 술, 물을 담을 때 사용하던 용기이다. 자라와 비슷한 모양을 하고 있어 ○○○이라 불리며, 크기는 높이 9.4㎝, 지름 24.1㎝이다. 병 전체를 백토로 두껍게 바르고, 윗면에는 모란꽃과 잎을 간략하게 나타냈다. 무늬가 새겨진 곳 이외의 백토면을 깎아낸 후, 검은 색 안료를 칠하여 흑백의 대조가 대비되는 효과를 가져오게 하였다. 이와 같은 무늬 장식기법을 박지기법이라 하는데, ○○○○ 무늬 중 조형적으로 가장 뛰어나다.","a":"분청사기 박지철채모란문 자라병","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611863.jpg"},{"q":"배재학당을 설립한 아펜젤러를 기념하기 위한 건물로 미국·매사추세츠주 피츠필드시의 기부금을 가지고 지어졌다. 화학과 교수 밀러의 감독하에 1921년 짓기 시작해 1924년 완성했다. 고딕풍의 단아한 건물이며, 돌로 지은 3층 건물로 언더우드관과 함께 ○○○○○에 두 번째 세워진 건물이다. 평면은 장방형이며 중앙에 현관과 계단실이 있고 나머지는 교실로 사용되었으나 현재는 행정관으로 활용하고 있다.","a":"서울 연세대학교 아펜젤러관","c":"사적","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624888.jpg"},{"q":"옛 석은사지에 세워진 통일신라시대의 석불입상으로 현재 기와지붕만을 씌운 누각 안에 서 있다. 직사각형의 네모나고 평평한 돌에 새겨진 이 불상은 중앙의 본존불을 중심으로 좌우에 보살입상이 배치된 삼존불(三尊佛) 형식을 이루고 있다. 본존불은 민머리 위에 작은 상투 모양의 머리(육계)가 있고, 둥근 얼굴에는 미소를 띠고 있다. 양 어깨를 감싸고 입은 두꺼운 옷은 가슴에서 U자형을 이루고 있으며, 그 사이에는 ▽형 모양의 띠매듭이 있다. 옷주름선은 오른손 아래에서 3가닥의 음각선을 이루며 흘러내리고 있다. 양쪽의 보살상은 각각 손으로 물건을 감싸 잡거나 합장한 자세이다.","a":"영동 신항리 석조여래삼존입상","c":"보물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617152.jpg"},{"q":"○○○○○은 검간(黔澗) 조정(趙靖)이 1626년 지은 것으로 ○○○ 중수기를 통해 알 수 있다. 또한, 종도리에서 기록이 나온 것으로 보아 1807년(순조 7)에 중수한 사실을 확인할 수 있다. ○○○○○은 전체적으로 정면 9칸, 측면 7칸의 규모의 ‘ㅁ’자형 평면을 한 고상식 건물로서 퇴칸 전면에 세운 6개 기둥은 통재를 사용하였는데, 특이하게 하층부분에는 방형으로 치목하고 상부는 원형으로 다듬었다.","a":"상주 양진당","c":"보물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622247.jpg"},{"q":"｢○○○○○｣는 고려 말 전리판서를 지낸 남휘주(南暉珠, 1326~1372)와 공조참판 남민생(南敏生, 1348~1407)의 묘를 지키고 제사를 받들기 위해 마련된 건물임. 창건 시기는 정확히 알 수 없으나 법당인 남흥사를 개조하여 지어졌다고 전해지고 있으며, 청벽 이수연(靑壁 李守淵, 1693~1748)이 1744년 기록한「○○○○중수기(南興齋舍重修記)」로 미뤄보아 18세기 이전부터 존재하고 있었던 것으로 추정됨.","a":"안동 영양남씨 남흥재사","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2020122316003800.JPG"},{"q":"1937년 건립 ○○○은 한센병 환자들의 유해를 나무 상자에 담아 보관하던 납골당이다. 일본의 보탑을 모방하여 콘크리트로 원통형 몸통을 구성하였고, 지붕은 갓을 씌운 형태이며, 지붕 위쪽은 탑의 상륜부처럼 구성하였다. 정면에 감실을 두어 참배객들이 망자에 대해 배향을 할 수 있게 하였고, 뒤쪽 문으로 들어가면 유골함이 안치되어 있고 작은 분향대가 마련되어 있다. 한센병 환자라는 이유로 일제에 의해 소록도에 강제 수용을 당하여 한 많은 삶을 살다 생을 마감한 환자의 납골당이라는 역사적 의미가 있는 건물이다.","a":"고흥 구 소록도갱생원 만령당","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668878.jpg"},{"q":"○○○○○’은 고려 광종(光宗, 재위 949～975)의 명으로 968년경 승려 조각장 혜명(慧明)이 제작한 우리나라 최대 규모의 석불로서, 1963년 1월 21일 보물로 지정, 관리되어 오다가, 고려시대 신앙과 불교조각사에 있어서의 위상을 재평가 받아 국보로 승격하게 되었다.","a":"논산 관촉사 석조미륵보살입상","c":"국보","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2018042017045500.JPG"},{"q":"○○○○은 주로 구봉(龜峯) 송익필(宋翼弼, 1534∼1599), 우계(牛溪) 성혼(成渾, 1535∼1598), 율곡(栗谷) 이이(李珥, 1536∼1584) 사이에 왕래한 편지를 후대에 4첩(帖)으로 제작한 것이다. 구봉, 우계, 율곡은 서로 절친한 친구들로서 16세기의 성리학(性理學)의 대가(大家)들인데 이들이 주로 이기(理氣)·심성(心性)·사단(四端)·예론(禮論) 등 성리학을 둘러싸고 토론·논의한 편지를 모아 엮어 놓은 이 책은 사상사적(思想史的), 학술사적(學術史的)으로도 귀중한 자료가 된다.","a":"삼현수간","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614801.jpg"},{"q":"토함산 동남쪽 계곡의 비교적 높은 곳에 자리하고 있는 통일신라시대의 절터이다. 절터가 있는 계곡은 대종천의 상류로 감은사터 앞을 지나 동해로 흘러간다. 절을 지은 연대나 절의 이름은 전해지지 않는데, ○○○라는 마을 이름을 따서 ○○○○○라 불러오고 있다. 절터에는 서탑인 5층석탑과 파괴된 동탑의 석재, 그리고 석조불대좌가 남아 있다. 금당으로 보이는 건물터에 있는 석조불대좌는 2단으로 되어 있는데, 아랫단은 팔각형으로 조각이 새겨져 있고 윗단은 연꽃을 조각한 원형대좌이다.","a":"경주 장항리 사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627658.jpg"},{"q":"이 집은 임진왜란 때 의병장으로 활약하다가 순국한 이홍인 부자의 충과 효가 얽혀있는 유서 깊은 집이다. 이홍인 공의 후손들이 사는 집으로서 명종 6년(1551)에 지은 것으로 보아 조선 중기 건축으로 추정되며 ‘○○○’이라 부른다. 안채와 사랑채가 맞붙어 있고 ○○지방에서 흔히 볼 수 있는 ㅁ자형 평면을 이루고 있다. 내부의 중앙은 뜰로 꾸민 소박한 집으로 남쪽과 서쪽에 바깥으로 통하는 대문이 있다. 남문이 본래의 대문이지만 지금은 서문을 대문으로 사용하고 있는데, 서문 바깥에 평행하게 있던 바깥채를 철거한 뒤에 드나드는 문도 옮긴 것으로 보인다.","a":"안동 예안이씨 충효당","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621186.jpg"},{"q":"○○○은 흥선대원군이 살았던 집으로, 고종이 태어나서 왕위에 오를 때까지 자란 곳이기도 하다. 흥선대원군의 집과 1910년대 새로 지어 덕성여자대학 본관으로 사용하던 서양식 건물을 합쳐 사적으로 지정하였다. 한옥은 제일 앞 남쪽에 대원군의 사랑채인 노안당이 자리잡고, 뒤쪽인 북쪽으로 행랑채가 동서로 길게 뻗어있으며 북쪽에 안채인 노락당이 자리잡고 있다. 고종이 즉위하자 이곳에서 흥선대원군이 정치를 하였고, 궁궐과 직통으로 연결되었다.","a":"서울 운현궁","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624805.jpg"},{"q":"선현께 제사지내고 학문을 이어받고자 설립한 조선시대 사립교육기관으로 인조 12년(1634)에 세웠다. 김장생(1548∼1631)을 중심으로 김집, 송준길, 송시열의 위패를 모시고 있으며, 흥선대원군의 서원철폐령이 내려졌을 때에도 없어지지 않은 전국 47개 서원 중 하나이다. ○○○은 학문을 갈고 닦던 강당으로 서원 옛 터에 남아있던 것을 1971년 지금 있는 곳으로 옮겼다. 건물을 옮길 때 기와에 적힌 기록을 발견하면서 오래된 건물임을 알게되었다. 규모는 앞면 5칸·옆면 3칸이며 지붕은 옆면에서 볼 때 지붕선이 사람 인(人)자 모양과 비슷한 맞배지붕이다.","a":"논산 돈암서원 응도당","c":"보물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618080.jpg"},{"q":"보물 '○○○○○'는 ○○○○의 권제3~권제5까지 3권을 1책으로 묶은 것으로, 권3의 첫부분 10장, 권5의 18장 후면부터 31장(발문)까지 모두 23장이 결락되었다. 표지는 개장한 것으로 홍사를 이용한 오침안장이며, 고 육당 최남선의 소장이었다가 후에 고려대학교에 기증된 것이다. 이 책은 현재 학계에서 가장 널리 이용하고 있는 조선 중종7년(1512)에 경주에서 간행한 책판에서 인출한 것인데 국내에 현존하는 정덕본 ○○○○ 가운데서 규장각본과 함께 비교적 초기에 인출한 선본에 속하며, 중종임신본의 서지적인 특징 및 가치를 지니고 있다.","a":"삼국유사 권3~5","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613376.jpg"},{"q":"조선 선조 때 성리학자 지산 조호익 선생의 7세손인 조학신(1732∼1800) 선생의 집으로 ○○○은 사랑채의 이름이다. 새사랑채인 광명헌과 별묘 및 보본재는 후대에 지어진 것으로 전한다. 야산의 소나무 숲에 둘러싼 평지마을의 가운데에 있는 집이다. 길쪽 새사랑채와 행랑채 솟을대문 지붕사이로 사랑채와 안채 지붕이 조금씩 보이는 평면적인 경관을 이루고 있다. 행랑채와 떨어져 있는 사랑채는 안채와 더불어 'ㅁ'자형을 이루고 있으며, 오른쪽에 사당이 있다. 그 뒤쪽에는 별묘와 보본재 등이 자리하고 있어서 사대부 집의 면모를 갖추었다고 하겠다.","a":"영천 만취당 고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635324.jpg"},{"q":"예전 정의(성읍) 고을 면사무소 관원들이 숙식하였던 곳이다. 조선 후기에 지었다고 하며 넓은 터에 안채(안거리), 바깥채(밖거리), 안채와 바깥채 사이에 있는 모커리가 배치되어 있다. 현재 있는 모커리 맞은편에 모커리가 하나 더 있었는데 1970년대 중반에 헐었다고 한다. 지금 있는 건물들은 1979년에 수리한(안채, 바깥채)것으로 모커리 역시 일부 수리한 것이다. 건물들은 모두 바람에 지붕이 날리지 않도록 새끼줄로 그물처럼 덮어 놓았다. 문을 들어서 오른쪽 위편에 자리 잡은 안채는 3칸 규모로 가운데칸에 대청마루(상방)가 있다.","a":"제주 성읍마을 고평오 고택","c":"국가민속문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1636003.jpg"},{"q":"이 비로자나불상은 불상의 중대석에서 발견된 납석사리호의 명문을 통해 766년(혜공왕 2)에 법승(法勝)과 법연(法緣) 두 승려가 받들어 돌아가신 두온애랑(豆溫哀郞)의 원을 위해 석조비로자나불상을 조성하여 무구정광대다라니와 함께 석남암수(石南巖藪, 여기서 \"수藪\"는 오래된 절을 의미) 관음암에 봉안하였다는 기록을 가진 중요한 불상이다. 이 불상은 우리나라 가장 오래된 연대를 가진 지권인(智拳印) 비로자나불상으로서 중요하며, 편년자료가 부족한 고대조각사 연구에도 절대적인 자료로 평가된다.","a":"산청 석남암사지 석조비로자나불좌상","c":"국보","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2016010709232300.jpg"},{"q":"제석천과 대범천은 원래 브라만 또는 힌두교의 신상(神像)이었으나, 대승불교 이후 불법을 지키는 신상이라 여겨 사천왕상 등과 더불어 불교미술에 있어 중요한 위치를 차지해 왔다. 『삼국유사』에 의하면 우리나라에서는 조각상이 아닌 그림으로 그려졌다고 전하며, 조선시대 탱화에서 주로 예를 찾아볼 수 있으나 조각상으로는 ○○○의 것이 유일하다. 사천왕상이 위엄을 나타내는 무서운 인상임에 비해 제석·대범천상은 보살상같은 자비로운 인상이다.","a":"진주 청곡사 목조제석천·대범천의상","c":"보물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622916.jpg"},{"q":"이 건물은 ○○○ 서장 ○○로 1934년 건립하였으며, 중복도를 통해 각 실로 연결되는 일식 가옥의 평면 형식을 취하고 있다. 현관을 비롯한 전면부 외벽은 시멘트 모르타르로 마감하였고, 측면 일부와 후면은 목재 비늘판 마감으로 두 기법이 혼합된 독특한 양식이다. 지붕은 일식기와를 주재료로 모임지붕이 중첩되고 부섭지붕이 외곽부에 첨가된 복잡한 형태이다. 내부 평면의 실 구성과 배치는 변화하는 생활 방식에 따라 많이 바뀌었지만, 외관은 예전 모습을 잘 간직하고 있다.","a":"장수경찰서 관사","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668779.jpg"},{"q":"임진왜란 때 ○○○이 난을 겪으면서 쓴 일기로, 선조 24년(1591)∼선조 34년(1601) 2월까지 약 9년 3개월간의 사실을 기록한 것이다. ○○○은 학문에 뛰어났으나, 과거급제를 못해 정식으로 관직에 오르지는 못했다. 그의 아들 오윤겸은 인조 때에 영의정을 지냈으며, 손자인 오달제는 병자호란 때 끝까지 싸울 것을 주장하다 청나라까지 끌려가 죽음을 당한 삼학사(三學士) 가운데 한 사람이다.","a":"오희문 쇄미록","c":"보물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615967.jpg"},{"q":"「○○○○」은 회재(晦齋) 이언적(李彦迪)이 27세 때 지은 「외천잠(畏天箴)」, 「양심잠(養心箴)」, 「경신잠(敬身箴)」, 「개과잠(改過箴)」, 「독지잠(篤志箴)」을 퇴계(退溪) 이황(李滉)이 읽고 크게 감명을 받아 평소 잊지 못하여 오던 중 이언적의 아들 이전인(李全仁, 호(號)는 잠계(潛溪), 1516~1568)의 요청에 의하여 쓴 것으로 전하고 있다. 이러한 내용은 10폭에 적혀 있는 이황의 발문에 보이는데 여기에는 잠계 이전인의 요청에 의해서 썼다는 기록은 없고 끝에 ‘후학 이황 근서(後學 李滉 謹書)’라고 쓴 묵적이 선명히 남아 있다.","a":"여주이씨 옥산문중 유묵 - 원조오잠, 사산오대","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621172.jpg"},{"q":"○○○는 조선 중종 15년(1520)에 벽송(碧松)이 창건한 사찰이다. 석탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 세운 통일신라시대 양식을 보이고 있다. ○○○의 창건연대가 1520년인 것으로 보아 조선시대에 만들어진 신라양식 탑이라는 점에서 매우 주목되는 작품이다. 2단으로 구성된 기단은 아래층 기단에 가운데돌의 네 모서리와 면의 가운데에 기둥 모양을 얕게 조각하였는데, 특이한 점은 바닥돌과 아래층 기단의 사이에 높직하게 딴 돌을 끼워놓은 것이다. 위층 기단의 맨윗돌은 한 장의 널돌로 이루어졌으며 밑에는 수평으로 얇은 단을 새겼다.","a":"함양 벽송사 삼층석탑","c":"보물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622691.jpg"},{"q":"1951년 건립된 이 건물은 ○○○○○으로 건립되었으며, 지금은 신한은행 대전역 금융센터로 사용되고 있다. 지상 2층 철근콘크리트조로 장식이 없는 화강석 평판 붙임으로 마감하였으며, 종래 은행건축의 고전적인 외형을 탈피하여 최대한 장식을 배제한 단순하면서도 전체적으로 조화로운 구성의 모더니즘 건물이다. 20세기 중반 서양의 기능주의 건축에 영향을 받은 한국 근대 건축의 경향을 잘 보여 주고 있다.","a":"구 조흥은행 대전지점","c":"국가등록문화유산","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667944.jpg"},{"q":"이 건물은 1907년에 착공되어 1909년 정초 후, 1912년에 조선은행 본점으로 준공된 은행건물로, 광복 후 1950년에 ○○○○○이 되었다. 일제 강점기에 우리나라 경제 수탈을 위해 일본이 세운 중앙은행으로, 정초석에 이토 히로부미 글씨로 확인되는 “定礎 隆熙三年七月十一日” 기록이 남아 일본이 자행했던 금융 침탈의 역사를 증언하고 있다. 지하1층 지상3층의 철골 콘크리트 구조로 외벽에는 화강석을 다듬어 붙였다. 일본인이 설계하였으며, 한국전쟁 때 내부가 불에 타서 1956년에 보수하였다.","a":"서울 한국은행 본관","c":"사적","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624905.jpg"},{"q":"이 건물은 도청 소재지를 진주에서 ○○으로 옮기면서 건립한 경남도청으로, 한국전쟁 당시 임시 ○○○○로 사용하였다. 처음 준공할 때는 ‘一’자 모양의 평면으로 구성하였으나, 1960년대 증·개축으로 ‘ㅁ’자 모양, ‘日’자 모양으로 바뀌었다. 정면 가운데에 현관 포치(porch)가 돌출되어 있고, 가운데와 양쪽 끝 부분을 돌출시키고 그 위쪽을 박공지붕으로 구성하는 등 전체적으로 위엄 있는 입면을 갖고 있다. 우리나라 근대사의 정치·사회적 변화를 간직한 역사적인 건물로 구 경상남도지사 관사(지금의 ○○○○기념관)와 더불어 ○○ 지역의 대표적인 근대 공공 건축물이다.","a":"부산 임시수도 정부청사","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667682.jpg"},{"q":"○○○ 앞 골짜기의 길가에 있던 것을 1900년 경 암자를 다시 세우면서 이곳에 옮겨 보관하고 있다. 머리는 상투 모양으로 묶어 올렸으며, 최근에 만든 불꽃무늬 장식의 관(冠)을 쓰고 있다. 몇 가닥의 머리카락은 어깨 앞뒤로 늘어져 있다. 얼굴은 양감이 적당하여 눈·코·입이 잘 조화를 이루고, 얼굴 바로 밑에서 어깨가 시작되며, 목에 새겨진 삼도(三道)는 가슴 윗부분까지 내려와 표현되었다. 옷에는 주름이 부드럽게 흘러내리고 있으며 불상의 뒷면에까지 섬세하게 표현되어 있다. 가슴에는 화려한 장식이 있고, 배 위에는 속에 입은 옷을 묶은 띠매듭이 있다.","a":"청양 운장암 금동관음보살좌상","c":"보물","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2017021514295700.jpg"},{"q":"○○은 조선중기의 문신으로 본관은 풍천(豊川), 자는 자룡(子龍)이다. <○○○○>은 17세기 전반의 전형적인 공신도상의 모습을 보여주는데, 단령을 입고 공수한 뒤 의자에 앉아 좌안7분면을 취하고 있으며 바닥에는 화려한 채전(彩氈)을 깔고 두 발은 돗자리를 깐 목제 의답(椅踏) 위에 팔자형으로 벌리고 있다. 이 ○○화는 왼쪽 눈꼬리를 위로 치켜 올려 두 눈의 형상을 차이 나게 묘사한 점, 숱은 적지만 때로는 짧게 때로는 약간 길게 올의 방향을 달리하여 수염의 성질을 잘 살린 표현법 등에서 화가가 인물을 앞에 두고 실사한 느낌이 강하다.","a":"임장 초상","c":"보물","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614888.jpg"},{"q":"고려시대 만들어진 뚜껑있는 ○○대접으로 높이 19.3㎝, 아가리 지름 18.5㎝, 밑 지름 6.8㎝이다. 뚜껑과 받침, 수저까지 완전하게 갖추어진 유물로서, 뚜껑에 다람쥐 모양의 꼭지를 만들었다. 다람쥐를 중심으로 그 아래에 흑백상감의 겹 연꽃무늬 띠와 물결무늬 띠를 두었고 그 밑으로 봉황과 용을 새겼다. 그릇 안에 수저를 꽂았을 때 뚜껑과 사발의 사이가 뜨지않도록 뚜껑의 한쪽 귀퉁이에 홈을 파 놓았으며, 대접 아가리의 가장자리에는 번개무늬 띠를 두르고 그 아래로 학과 구름무늬를 규칙적으로 새겼다.","a":"청자 상감용봉모란문 합 및 탁","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611696.jpg"},{"q":"구 곡성역은 2동, 1층 규모로 역사 건축면적 216.19㎡, 창고 건축면적 189.50㎡이다. 구 곡성역은 전라선로의 역사로 1933년에 건립되었으며 등록된 간이역중 규모가 큰편에 속하며., 1933년 10월 15일 보통역으로 영업 개시하였다. 1999년 전라선 복선화로 곡성역이 신축이전하면서 폐역되었다. 지붕형태는 박공이 양쪽에 설치되었으며, 전면은 입구에 배면는 사무실쪽에 배치되어 있다. 구조는 목조에 맞배지붕으로 2001년 등록전 보수시 지붕재료와 벽체 일부가 변형되었다. 내부에는 난방시설이 대합실과 사무실 사이에 위치하며 굴뚝이 지붕위에 조적되어 있다.","a":"구 곡성역사","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668917.jpg"},{"q":"서혈사터에서 출토된 3구의 불상 중 하나이다. ○○○○는 백제시대에 창건되어 작은 규모로 운영되다가 통일신라시대에 본격적인 사찰로 운영되었다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 얼굴은 약간 길고 눈·코·입 등은 아주 작게 표현되었다. 옷은 양 어깨에 걸쳐 입고 있는데 두께가 얇아보인다. 옷주름은 배부분에서 곡선을 그리고 있으나 전체적으로 규칙적인 가는 평행선이 약한 느낌을 준다. 앉은 자세는 양 발을 무릎 위로 올리고 발바닥이 위로 향하도록 하고 있다. 손모양은 오른손을 무릎 위에 올리고 손가락을 아래로 편 항마촉지인(降魔觸地印)이다.","a":"공주 서혈사지 석조여래좌상","c":"보물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617995.jpg"},{"q":"이 ○○○○○는 한국전쟁 당시 연합군 군수물자 수송을 위해 개성역에서 황해도 한포역까지 올라갔다 전세가 악화되어 남쪽으로 내려오던 중 1950.12.31 밤늦게 ○○○○○에서 피폭되어 탈선하여 그 자리에 멈춰선 ○○○○○임. 검붉게 녹슬고 부식된 채로 반세기 넘게 비무장지대 안에 방치되어 있었으며, 국가유산청은 이를 남북분단의 뼈아픈 역사적 상징물로 보호·관리하기 위해 국가등록문화유산으로 등록하였음.","a":"경의선 장단역 증기기관차","c":"국가등록문화유산","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668066.jpg"},{"q":"한계사터는 한계령 중턱의 장수대에 자리잡고 있다. 앞으로는 한계천이 흐르고, 뒤로는 산줄기가 병풍처럼 펼쳐져 있는데, 한용운이 지은 책에 의하면, 신라 진덕여왕 원년(647)에 자장율사가 창건했다고 한다. 그 후 몇 차례의 보수를 거쳐 약 17세기 말까지는 절의 명맥을 유지했던 것으로 짐작된다. 현재 이 절터에는 건물의 주춧돌이 그대로 남아 있고, ○○○○ 2기와 불상, 석등 등 많은 석조물이 있다.","a":"인제 한계사지 남 삼층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"인제군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616815.jpg"},{"q":"광복 직후에 전남 고흥의 소록도에서 사용된 ○○○으로 1984년 체신부 우표과에서 우정박물관으로 이관하여 1985년 박물관 개관 시부터 전시되었다. 원기둥형의 철제 ○○○에 당시의 우편마크가 양각되어 있고, 붉은색 칠은 퇴락되고 일부 녹이 슬었으나 원형을 잘 유지하고 있어 사료적 가치가 크다.","a":"소록우체국 우체통","c":"국가등록문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668630.jpg"},{"q":"○○○은 『삼국사기』를 비롯한 여러 기록에서 신산(神山)으로 섬겨져 제천의식의 장소가 되었음을 엿볼 수 있는데, ○○○은 이러한 제를 올리기 위해 만든 제단이다. ○○○은 ○○○ 정상에 있는 천왕단을 중심으로 북쪽 약 300m 떨어진 곳에 장군단과 남쪽 아래에 있는 이름 없는 제단(하단, 下壇)으로 구성되어 있다. 이들은 북에서 남으로 일직선상에 배열되어 있다. 천왕단은 2m 남짓한 높이로 자연석을 쌓아 남쪽으로 단을 조성한 원형제단이다.","a":"태백산 천제단","c":"국가민속문화유산","nc":"","r":"강원특별자치도","s":"태백시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633838.jpg"},{"q":"조선시대에 중국의 사신을 맞아들이던 모화관 앞에 세웠던 주춧돌이다. 개화기에 우리민족의 자유와 독립을 다짐하는 의미로 ○○○을 헐고 그 자리에 독립문을 세우면서 그 기둥을 받치던 밑돌인 ○○만 남게 되었다. 모화관은 조선 태종 7년(1407)에 처음 세우고 모화루라 하였는데 그 뒤 세종 12년(1430)에 모화관이라 이름을 바꾸고 그 앞에 상징적인 의미의 홍살문을 세웠다. 중종 32년(1537)에 홍살문보다 격식을 갖춘 형식의 문을 만들고 ‘영조문’이라 하였다가 중종 34년(1539)에는 중국 사신의 건의로 ○○○이라 이름을 고쳤으며, 연주문·연은문이라고도 하였다.","a":"서울 영은문 주초","c":"사적","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624458.jpg"},{"q":"○○○○○에 최초로 세워진 건물로서, 1919년 착공하여 1920년 완성된 돌로 지은 2층 건물이다. ○○○○○의 전신인 연희전문학교의 설립자 언더우드(한국이름 원두우)목사가 고향인 미국으로 돌아가서 항구적인 학교건축을 위해 미국 로스엔젤레스에 거주하던 찰스 스팀슨의 기부금을 얻어놓고 세상을 떠난 뒤, 후임교장인 에비슨이 그 기부금으로 건립한 것이다. 미망인인 언더우드 부인이 초석을 놓았고 당시 화학과 교수인 밀러가 공사를 감독하였다. 설계자는 알 수 없으나 당시 미국인 건축가들이 우리나라에 와서 설계와 기본계획을 작성하였다고 한다.","a":"서울 연세대학교 스팀슨관","c":"사적","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624847.jpg"},{"q":"동촌역은 1동, 1층 규모로 건축면적 176.65㎡이다. 동촌역은 ○○선 역사로 1938년 7월 1일 ○○-영천간 광궤선 개량사업시 건립되었다. 본래 조선중앙철도(주)에 의하여 1916년 2월 착공되어 같은 해 11월 1일 ○○-하향간이 개통되었으며, 1917년 11월 1일 보통역으로 영업개시하고, 1918년 10월 31일 하양-포항구간이 개통되었다. 1928년 7월 1일 국철도 편입되어 1938년 ○○-영천간 광궤선으로 개량되었으며, ○○선 이설로 역사가 폐역되었다.","a":"대구 구 동촌역사","c":"국가등록문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667805.jpg"},{"q":"「○○○○○」은 임진왜란 때 소실되었다가 17세기 중엽에 재건 된 이후로 현재까지 여러 차례 수리가 이루어 졌으나 건축의 형태와 구조, 의장 등 전반에 걸쳐 건립 당시의 고식기법을 잘 유지하고 있음. ○○○은 정면에 개방된 퇴칸을 구성하고 맞배지붕을 얹은 조선시대 사묘건축의 전형적인 형태를 하고 있으며, 정면 5칸의 간살 구성은 조선시대 군․현 단위 향교의 ○○○으로서는 규모가 큰 편에 속하는 것으로 볼 수 있음.","a":"안성향교 대성전","c":"보물","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122909220300.JPG"},{"q":"「○○○○○」은 향촌사회가 재편되어가던 15세기 중반 혹은 후반에 이곳에 정착한 전주최씨와 거창신씨 일족에 의하여 창건되고, 임진, 정유의 왜란 이후 1635년(인조 13) 경 중건되었으며, 이후 보수를 거쳐 현재에 이르고 있는 ○○ 지역의 대표적인 누정임. 이웃한 장암정과 함께 동계(洞契)의 회합장소로 사용되었던 곳으로 향약 정자로서 보기드문 희소성을 가지고 있음. 민간이 운영한 향촌의 누정으로서는 보기 드물게 큰 규모를 가지고 있고 누정으로서 역시 유례를 찾기 어려운 높은 마루를 가지고 있으며, 후면열의 중앙에 구분된 방을 두는 독특한 평면형식을 가지고 있음.","a":"영암 영보정","c":"보물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019122715280200.JPG"},{"q":"『○○○○○』서첩에는 1476년(성종 7) 1월말에 우리나라에 온 명나라 사신 호부낭중(戶部郞中) 기순(祁順：東莞人, 1460년 진사, 자 致和, 호 巽川)과 사신일행을 맞이했던 원접사(遠接使) ○○○의 글씨가 함께 실려 있으며 표지에는 ‘천사사한진적(天使詞翰眞蹟)’이라 쓰여 있다.","a":"서거정 필적","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616148.jpg"},{"q":"표지에 ‘청송서(聽松書)’라고 쓰여진 이 『○○○○○』은 16세기 학자 청송(聽松) ○○○이 당나라 가도(賈島), 두목(杜牧), 이상은(李商隱)과 송나라 구양수(歐陽脩)의 칠언시를 쓴 것이다. 종이 바탕을 줄[行]에 따라 잘라 첩장하였다. 송명흠(宋明欽, 1705~1768)후손의 기증품으로 송명흠의 아버지 송요좌(宋堯佐, 1678~1723)의 [청은당(淸隱堂)]이란 인영(印影)이 있다. ○○○은 이황과 함께 16세기를 대표하는 도학자 명필로 ○○은 드문 편이다. 현재 그의 소자(小字)는 몇몇 전하고 있는 상황이고 대자(大字)는 목판밖에 전하지 않는다.","a":"성수침 필적","c":"보물","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615530.jpg"},{"q":"조선시대에는 70세가 넘는 신하에게 공경의 뜻으로 나라에서 지팡이 <장 (杖)>와 의자 <궤 (几)>와 가마 등을 주는 풍습이 있었는데, 그에 따라 왕이 내린 물품이다. 현종 9년(1668) 11월 왕이 당시 원로대신이었던 ○○○에게 공경의 뜻으로 내린 궤 1점과 장 4점 그리고 이를 받는 장면을 그린 그림 1점 등 총 6점의 유물이다. ① 궤:높이 93㎝, 폭 77.4㎝로 앉을 때만 펴고 평상시 에는 접어둘 수 있게 만든 의자이다. 앉는 곳에는 단단한 노끈을 X자로 엮어 접어두기 편하게 만들었다.","a":"이경석 궤장 및 사궤장 연회도 화첩","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615883.jpg"},{"q":"○○○○○는 우리나라에서 가장 널리 유통된 ○○○ 중 하나로 ○○○여래가 마음속에서 불교의 진리를 깨닫는 것을 의미한다. ○○○를 모은 것을 진언집(眞言集)이라 하며 조선시대에는 ‘○○○○○’등 5종의 ○○○를 모아 편집한『오대진언집』이 널리 유통되었다. 닥종이에 찍은 목판본으로 병풍처럼 펼쳐서 볼 수 있는 첩장의 형태이며, 접었을 때의 크기는 세로 25.6㎝, 가로 8.8㎝이다. 간행기록이 없어서 정확한 시기는 알 수 없으나 판각한 글자가 많이 닳고 인쇄가 깨끗하지 못한 것으로 보아 고려말에 새기고 조선초에 찍어낸 것으로 보인다.","a":"대불정다라니","c":"보물","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615982.jpg"},{"q":"○○○○○은 현재 석종사에 모셔져 있다. 머리에는 상투 모양의 머리(육계)가 큼직하게 자리잡고 있으며, 머리 가운데에는 고려시대 불상에서 자주 보이는 반달 모양을 표현하였다. 긴 타원형의 얼굴에는 눈·코·입이 단아하게 묘사되었으며 두 귀는 길게 표현되고 목에는 3개의 주름이 분명하게 표현되었다. 양 어깨에 걸쳐 입은 옷은 다소 두꺼운 편이고 옷주름은 간략한 몇 개의 선으로 표현하고 있다. 특히 가슴에 묘사된 띠매듭은 고려말 조선초부터 나타나는 수평적인 처리에 근접하고 있다. 좁고 둥근 어깨와 평평한 가슴의 상체는 4각형의 각진 모습이다.","a":"충주 단호사 철조여래좌상","c":"보물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617051.jpg"},{"q":"○○○는 신라말 도선국사가 지었다고 전하지만 건물의 위치와 앞 마당에 있는 석탑들로 미루어 고려시대의 절로 짐작된다. ○○○은 석가모니 불상을 모신 절의 중심 법당을 가리키는데 이 건물은 ‘대광보전(大光寶殿)’이라 쓴 현판이 걸려있다. 규모는 앞면 3칸·옆면 3칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 지붕 위부분에 장식하여 짜은 구조가 기둥 위에만 있는 주심포 양식인데 밖으로 뻗쳐 나온 부재가 주심포 양식의 초기 수법을 띠고 있다.","a":"홍성 고산사 대웅전","c":"보물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617731.jpg"},{"q":"1928년 철근콘크리트조 적벽돌 마감으로 재건된 지상 2층 규모의 병원 건축물로, 일제강점기 철도기지로서 신시가지로 개발되었던 용산을 상징적으로 보여주는 건축물이다. 건립 당시의 구조, 재료, 공간구성을 간직하였으며, 절제된 장식과 함께 서양의 고전적 양식에서 근대건축으로 옮겨가는 과도기적 특성을 보여주고 있다.","a":"서울 구 용산철도병원 본관","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667225.jpg"},{"q":"경상북도 ○○군 성산일대에 있는 성산가야지배층의 무덤들이다. 성산의 정상에는 성산산성이 있고 주변에 70여기의 가야 무덤들이 분포하고 있다. 1호 무덤은 높이 3.6m, 지름 13.6m로 내부구조는 앞트기식돌방무덤(횡구식석실묘)으로 보인다. 돌방(석실)에서는 은제관장식과 고리자루큰칼(환두대도), 각종 토기류가 발견되었다. 2호 무덤은 구덩식돌방무덤(수혈식석실묘)으로 창·도끼·손칼을 비롯하여 많은 수의 토기가 발견되었다. 58호 무덤 굴방에서는 금제굵은고리귀고리(금제태환이식), 은제팔찌, 금동제말장식(행엽)이 발견되었다.","a":"성주 성산동 고분군","c":"사적","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627699.jpg"},{"q":"이 다리는 장성광업소 안에 있는 시설물로, 위쪽 다리는 석탄 수송용 전차가 다니고, 아래쪽 다리는 보행자와 차량이 다니도록 설계되었다. 교각은 무지개 형상이며, ○○ 지역에서 가장 오래된 교량으로 한국의 근대화 과정에서 중요한 기능을 한 석탄 산업 관련 시설물이다.","a":"태백 장성이중교","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"태백시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668324.jpg"},{"q":"정영방이 광해군 5년(1613)에 벼슬을 버리고 낙향하여 은둔하였을 때 조성한 것으로 전해지는 조선시대 민가의 정원시설로 연못과 정자로 구성되어 있다. 자양산 남쪽의 완만한 기슭에 위치한 연못을 중심으로 경정과 주일재를 배치하고, 이들을 담장으로 둘러싼 후 담장 밖 북쪽에 수직사를 두었다. 경정은 넓은 대청과 방 2개로 되어있는 큰 정자이며, 주일재는 ‘운서헌’이라고 쓴 현판이 걸려있는 서재이다. 주일재 앞은 연못 쪽으로 내밀어 돌로 쌓은 단을 만들고 그곳에 소나무·대나무·매화·국화를 심어 ‘사우단’이라 이름 지었다.","a":"영양 서석지","c":"국가민속문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635186.jpg"},{"q":"1945년 금융조합 ○○으로 건축된 우진각지붕의 일식(和風)주택이다. 현관문이 후면에 위치하고, 안방의 도코노마 공간 등 일본식 주택양식을 보여주고 있다. 내외부가 전반적으로 잘 보존되어 있어, 일제강점기 후반 ○○ 연구의 귀중한 자료로 가치가 있다.","a":"구 문경금융조합 사택","c":"국가등록문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669130.jpg"},{"q":"전북특별자치도 ○○시 야산 중턱에 나란히 서 있는 2구의 석불입상이다. 백제시대의 불상으로 백제 최남단에 조성된 화강암 석불이라는 점과 오른쪽 어깨를 드러낸 편단우견(偏袒右肩)의 착의법(着衣法)을 보여주는 점에서 의의가 크다. 두 불상은 같은 조각양식의 특징을 보여주고 있지만, 오른쪽 불상이 왼쪽 불상보다 약간 커서 이불병존상(二佛竝存像)을 염두에 두고 조성된 것은 아닌 듯 하다. 오른쪽의 큰 불상은 뒤편의 광배(光背)가 깨지고 대좌(臺座)의 아랫부분을 잃어버린 것 외에는 대체로 완전한 모습이다.","a":"정읍 보화리 석조이불입상","c":"보물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618593.jpg"},{"q":"빛벌가야(지금의 ○○군)를 ○○ 영토로 편입한 ○○○이 이곳을 순시하면서 민심을 살핀 후 그 기념으로 세운 비이다. 당시 ○○군은 ○○가 서쪽으로 진출하는데 있어 마치 부채살의 꼭지와 같은 중요한 길목이었는데, ○○○ 16년(555) ○○에 병합되었고, 565년에는 대야주(지금의 합천군)와 합쳐져 비사벌군(比斯伐郡) 또는 비자화군(比自化郡)으로 불리워지게 되었다. 비는 목마산성 기슭에 있던 것을 1924년 지금의 자리로 옮겨 비각안에 모셔 둔 것으로, 자연석의 앞면을 평평하게 다듬어 비문을 새기고, 그 둘레에 선으로 윤곽을 돌려놓은 모습이다.","a":"창녕 신라 진흥왕 척경비","c":"국보","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1613008.jpg"},{"q":"○○○○○은 고려시대 문인이었던 최해(崔瀣,1287∼1340)가 편집한 책이다. 그의 문집인 『졸고천백(拙藁千百)』에는 「동인문서(序)」와 「동인사륙서(序)」가 있다. 「동인문서」에 의하면 그는 우리나라 시문을 선집하여 시를「오칠」, 문을「천백」, 병려를「사륙」이라고 이름을 붙였다. 「동인사륙서」에는 「사륙」에 대해 따로 체례(體例) 문제를 서술하였다. 그러나 현재 전하는 『○○○○』에는 「오칠」, 「천백」은 거의 보이지 않고, 「사륙」만이 남아있다. 이 책은 신라와 고려시대의 문장을 모은 것으로, 권 1∼6의 총 6권 2책이다.","a":"동인지문사육 권1~6","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613715.jpg"},{"q":"○○○은 ○○○ 내전의 으뜸전각으로 왕비의 침전으로 사용되었지만, 『조선왕조실록』의 기록을 보면 주로 왕대비의 생활공간으로 사용되었다. 1484년(성종 15)에 처음 지었다가 임진왜란으로 불에 탄 것을 광해군 대에 다시 지었고, 1790년(정조 14)에 다시 불에 탔으나 1833년(순조 33) ○○○ 오른쪽에 있는 양화당(養和堂)과 함께 다시 지었다. 규모는 앞면 7칸, 옆면 4칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이고, 지붕 위는 용마루가 없는데 현재 ○○○에 남아 있는 건물 중 유일하다.","a":"창경궁 통명전","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614024.jpg"},{"q":"○○○는 고려 충목왕 1년(1345)에 세워졌다. 절 이름은 중국의 달마대사가 숭산 소림사에서 9년간 앉아 도를 닦았다는 옛 이야기를 기리는 뜻에서 지었다고 한다. ○○○○○은 17세기 이전에 지은 건물로 추정하고 있다. 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위와 기둥 사이에도 있는 다포 양식인데, 건물 옆면에는 공포를 배치하지 않았다.","a":"익산 숭림사 보광전","c":"보물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618532.jpg"},{"q":"「○○○○○」은 만공스님(1871~1946)의 업적을 기리기 위하여 1947년에 세운 석탑으로 전통적 승탑 형식을 탈피한 근대적 기념탑이다. 육각의 지대석 위에 원형의 괴임돌을 놓고, 그 위에 세 개의 기둥을 평면 Y字형태로 세운 후, 그 위에 구체(球體)를 올려놓았다. 기둥 세면의 빈 공간에 오석(烏石)으로 면석을 조성한 후, 정면에는 ‘○○○’, 좌우측면에는 ‘世界一花’(세계일화), ‘百艸是佛母’(백초시불모)를 비롯한 만공스님의 친필과 행장(行狀), 법훈(法訓) 등을 새겼다. 탑 주위에 두른 육각의 돌난간은 후대에 ○○○을 보호하기 위해 설치한 것이다.","a":"예산 수덕사 만공탑","c":"국가등록문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668651.jpg"},{"q":"당나라 승려 현각이 지은 선종(禪宗)의 지침서로 각 구절에 송나라 남명선사 법천이 그 뜻을 구체적으로 밝힌 책이다. ○○○○○는 고려 고종 26년(1239)에 최이(崔怡)가 이미 간행한 금속활자본을 견본으로 삼아 다시 새긴 것 중 하나가 전해진 것이다. 닥종이에 찍은 목판본으로 크기는 세로 27.5㎝, 가로 16.6㎝이다. 책 머리부분에는 1077년에 오용천용(吳庸天用)이 지은 글이, 끝부분에는 1076년에 축황(祝況)이 판을 새길 때 지은 글이 실려 있다.","a":"남명천화상송증도가(1984)","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613823.jpg"},{"q":"이 ○○은 고려시대에 굴산사를 세운 범일국사(梵日國師)의 사리를 모신 탑으로 추정된다. 굴산사터의 위쪽에 자리잡고 있으며, 모든 부재가 8각을 기본으로 하여 조성되고 있지만 부분적으로는 변화된 수법을 보인다. 사리를 모시는 몸돌을 중심으로 아래로는 받침부분이 놓이고, 위로는 지붕돌과 꼭대기장식이 놓였다. 꼭대기장식으로는 상륜받침과 보개(寶蓋), 연꽃봉오리 모양의 구슬장식이 놓여 있다. 한 돌로 된 바닥돌은 8각의 평면이며, 위에는 접시 모양의 받침돌이 있다. 2단으로 된 8각의 괴임돌이 있는 아래받침돌은, 평면이 원형이며 구름무늬가 새겨져 있다.","a":"강릉 굴산사지 승탑","c":"보물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616319.jpg"},{"q":"○○에서 대전으로 가는 금강가에 있는 구석기시대의 유적이다. 구석기시대란 인류가 돌을 깨뜨려 도구로 사용하고 사냥이나 물고기잡이, 식물채집을 통해 생활한 문화단계를 말하는데, 인류가 태어나 1만년 전까지의 시기로 보고 있다. 찍개·긁개·주먹도끼·새기개 등의 석기류가 다양하게 출토되었다. 후기 구석기층의 집자리에서는 숯이 발견되었는데, 이것으로 연대측정을 한 결과 약 2만 5천년에서 3만 년전의 집터임이 확인되어, 당시에 사람들이 이곳에서 생활하였음을 알게 되었고 전후 시기에도 살았을 것으로 보고 있다.","a":"공주 석장리 유적","c":"사적","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626617.jpg"},{"q":"통일신라 후기의 승려인 진경대사의 사리탑으로, 탑비와 함께 봉림사터에 있던 것을 1919년 경복궁으로 옮긴 것이다. 현재 국립중앙박물관에 옮겨져 있다. 전형적인 8각 부도이지만 표면의 조각은 적은 편이어서 재료의 빛깔과 아울러 청초한 느낌을 준다. 8각의 바닥돌 위에 있는 기단(基壇)의 아래받침돌 또한 8각으로, 옆면에는 안상(眼象)이 새겨져 있는데, 특히 무늬의 바닥선이 불꽃모양으로 솟아올라 시대적인 특징을 보이고 있다. 가운데받침돌은 북모양으로 중앙의 곳곳에 꽃송이를 새긴 후 이를 도드라진 띠장식으로 연결시켰다. 윗받침돌에는 연꽃 8송이를 조각하였다.","a":"창원 봉림사지 진경대사탑","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613305.jpg"},{"q":"○○○○○ 마을에 세워져 있는 3층 석탑으로, 우리나라에서는 일찍이 볼 수 없었던 독특한 모습을 하고 있다. 기단(基壇)은 낮은 1단으로, 부여 정림사지 오층석탑(국보)과 같은 양식이다. 탑신(塔身)은 몸돌과 지붕돌이 여러 장의 돌로 이루어졌다. 1층의 몸돌은 대단히 높아 기형적인 인상을 주고, 각 면 모서리에는 희미하게 기둥모양을 본떠 새겨놓았다. 2층 몸돌은 높이와 너비가 급격히 줄었으며, 남쪽면에 2매의 문짝이 달려 있는데, 이는 감실(龕室:불상을 모시는 방)을 설치한 것으로 짐작된다.","a":"정읍 은선리 삼층석탑","c":"보물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618234.jpg"},{"q":"조선 후기의 문신 ○○○이 입던 ○○○○이다. 조복이란 문신과 무신들이 동지와 설날, 나라에 경사가 있을때나 종묘와 사직에 제사지낼 때 입었던 옷으로 ○○○○이라고도 한다. ○○○○○으로 지정된 유물은 금관, 적초의, 적상, 청초의(청초중단), 운학금환수, 패옥, 서대, 홀 등이다. 금관은 5개의 금색선이 붙여진 오량관으로 나무비녀로 고정시키게 되어있다. 조복인 적초의는 날씨가 더울 때 쓰는 항라로 만든 붉은색의 홑옷로, 깃은 직선이고 넓은 동정이 달렸으며 소매가 넓고 양 옆이 트였다.","a":"심동신 금관조복","c":"국가민속문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633012.jpg"},{"q":"○○○○는 태조 3년(1394년) 관덕정에서 동쪽으로 1리 정도 떨어진 가락천의 서안에 위치한 교동에서 창건된 것으로 추정되며, 이후 5차례 이건과정을 거치면서 순조 27년(1827) 현재의 위치에 자리 잡았다. ○○○○는 애초 경사지형에 맞추어 ‘홍살문-외삼문-명륜당-○○○-계성사’로 이어지는 ‘전학후묘’의 배치였으나, 제주중학교가 들어서면서 영역이 축소되고 명륜당이 ○○○ 남쪽에 건립되어 현재의 ‘좌묘우학’ 배치가 되었다. 그러나 ○○○ 및 계성사는 이건 이후 현재까지 제자리를 유지하고 있다.","a":"제주향교 대성전","c":"보물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2016061316550500.JPG"},{"q":"○○○ 대홍원전(大弘願殿) 앞에 세워진 3층석탑이다. 탑 앞에는 같은 시대에 만들어진 것으로 보이는 석등이 있으나 이 곳은 탑과 석등이 놓였던 원래의 위치가 아닌 듯하다. ○○○의 원래 이름은 죽림사(竹林寺)인데 신라 흥덕왕 4년(829)에 두번째로 크게 확장시켜 이름을 영정사(靈井寺)로 고쳤다고 전한다. 조선 헌종 5년(1839)에는 그때까지 ○○군 무안면에 있었던 ○○○를 영정사로 옮기면서 절 이름도 ○○○로 개칭하였고, 가람배치도 큰 이동이 있었던 것이니 이 탑도 그 때에 옮긴 것이 아닌가 추측된다.","a":"밀양 표충사 삼층석탑","c":"보물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622666.jpg"},{"q":"○○○는 통일신라 후기에 창건된 것으로 추정되며 고려 명종 때인 12세기에 원각국사에 의해 중창이 있었던 것으로 추정된다. 고려 고종 때 안종필이 왕의 명을 받아 탑과 부도와 금당을 새로 짓고 절 이름을 국청사(國淸寺)라 하였다. 뒤에 다시 공민왕에 의해 ○○○로 불리게 되었다. 이 탑은 ○○○ 대웅전 앞에 서 있으며, 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올리고 머리장식을 갖춘 완전한 형태이다. 위·아래층 기단의 네 면에는 무늬가 새겨져 있는데, 특히 위층 기단의 무늬는 모서리까지 침범할 만큼 크고 넓다.","a":"영동 영국사 삼층석탑","c":"보물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617067.jpg"},{"q":"○○○는 672년(신라 문무왕 12) 능인대사(能仁大師)에 의하여 창건되었다는 전설이 전하는데,<○○○ 중수상량문>등 발견된 구체적인 자료를 통해 보면 7세기 후반 능인대사에 의해 창건된 것으로 추정된다. ○○○은 원래 대장전이라고 불렀으나 뒤에 이름을 바꾸었다고 한다.","a":"안동 봉정사 극락전","c":"국보","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612623.jpg"},{"q":"1933년 승려이자 독립운동가인 ○○○○○ 선생이 건립하여 거주한 곳으로, 독립운동 관련 활동과 애국지사들과의 교류 등에 대한 흔적이 남아 있다는 측면에서 사적으로서의 가치가 충분하다.","a":"만해 한용운 심우장","c":"사적","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2019041013463600.jpg"},{"q":"탑이 세워진 이 터는 신라 법흥왕이 죽기 전까지 승려로서 불도를 닦았다는 애공사(哀公寺)가 있었던 곳이라 전해오기도 하지만 주변이 논밭으로 변하여 사찰의 흔적은 찾을 수 없다. 탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 세운 모습이다. 기단은 사방 네 면에 기둥 모양의 조각을 두었는데, 탑신에 비해 과중한 비율을 보이고 있어 무거운 느낌을 준다. 탑신(塔身)은 각 층의 몸돌 모서리마다 기둥을 본 뜬 조각을 두었고, 지붕돌은 하늘을 향해 네 귀퉁이가 살짝 들려있어 경쾌한 곡선을 이룬다.","a":"경주 효현동 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620179.jpg"},{"q":"1948년에 착공되어 한국전쟁 기간인 1951년에 완공된 후 광주○○○○○과 ○○○○○ 본부로 사용되었으며 현재는 ○○○○○ 의학박물관으로 활용되고 있다. 동 시대에 건립된 대학 건축물과 비교할 때 한국전쟁 중에도 꾸준히 건축공정이 진행된 점, 모더니즘의 세련된 디자인, 조적조와 철근콘크리트 슬라브 연결의 적합성 등 역사적, 건축사적 측면에서 중요한 의미를 간직하고 있어 국가등록문화유산으로서의 가치가 있다고 할 수 있다.","a":"전남대학교 의과대학 구 본관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018081418161900.JPG"},{"q":"조선 19대 숙종의 후궁이자 21대 영조의 생모(사친)인 숙빈 최씨(1670~1718)의 원이다. 숙빈은 최효원의 딸로 7세에 궁녀로 입궁하여, 1693년(숙종 19) 숙종의 후궁이 되고 이듬해에 연잉군(영조)을 낳았다. 1699년(숙종 25) 숙빈에 봉해진 후, 1718년(숙종 44) 49세로 세상을 떠났다. 숙빈 최씨가 세상을 떠난 후 영조는 묘소 근처에 시묘막을 지어 어머니의 죽음을 애도하였다. 이후 영조는 왕위에 오른 후 묘소 입구에 신도비를 세웠으며, 1744년(영조 20) 사당의 이름을 육상묘, 묘의 이름을 소령묘라 하였다.","a":"파주 소령원","c":"사적","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020081316591500.jpg"},{"q":"한강의 지류인 성내천 남쪽에 있으며, 둘레가 약 2.7㎞ 되는 백제 전기의 토성이다. 자연 지형을 이용해 진흙으로 성벽을 쌓고, 나무 울타리로 목책을 세웠던 흔적도 확인되었다. 자연 암반층을 급경사로 깎아 만들기도 하였으며, 성을 둘러싼 물길인 해자도 확인되었다. 조사 결과 문터와 집자리, 저장용 구덩이가 확인되었고, 출토유물로는 동전무늬가 찍힌 자기조각과 여러 종류의 토기류, 철제 무기류 등이 나왔다. 특히 동전무늬가 찍힌 자기조각은 중국 서진(265∼316)대의 유물이어서 시대 확인에 있어 중요한 역할을 한다.","a":"서울 몽촌토성","c":"사적","nc":"","r":"서울특별시","s":"송파구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624948.jpg"},{"q":"○○○ 뒷편에 모셔져 있는 나옹의 사리탑으로, 널찍하게 마련된 단층 기단(基壇) 위에 2단의 받침을 둔 후 종 모양의 탑신(塔身)을 올린 모습이다. 기단은 돌을 쌓아 넓게 만들고 앞쪽과 양 옆으로 계단을 두었다. 탑신은 아무런 꾸밈이 없고, 꼭대기에는 머리장식으로 불꽃무늬를 새긴 큼직한 보주(寶珠:연꽃봉오리모양의 장식)가 솟아 있다. 고려 우왕 5년(1379)에 세운 것으로, 나옹이 양주 회암사 주지로 있다가 왕의 명으로 밀양에 가던 도중 이곳 ○○○에서 입적하니, 그 제자들이 절 뒤에 터를 마련하여 이 탑을 세워 두었다.","a":"여주 신륵사 보제존자석종","c":"보물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615708.jpg"},{"q":"1927년 건립된 이 건물은 ○○○○○ 여사가 받은 생일 헌금으로, 건축을 전공한 남장로회 서로득(Swinehart) 선교사가 건축하였다. 좌우 대칭의 중복도형으로 정면 출입구에 설치한 아담한 돌출 현관인 포치가 인상적이다. 이 돌출 현관 위 삼각형의 박공지붕과 이를 받치는 투스칸 오더(Tuscan Order)의 원형 기둥은 다른 학교 건물에서는 볼 수 없는 독특한 것이다.","a":"광주 구 수피아여학교 윈스브로우 홀","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667915.jpg"},{"q":"원경왕사를 기리기 위해 세운 비(碑)로, 반야사의 옛터에 있었던 것을 1961년에 해인사 경내인 지금의 자리로 옮겼다. 거북받침돌과 비몸, 지붕돌을 갖추었는데, 각 부분이 얇은 것이 특색이다. 비문에 의하면, 원경왕사는 대각국사를 따라 송나라에 갔다가 귀국하여 숙종 9년(1104)에 승통(僧統)이 되었다. 예종의 스승이 되기도 하였고 그 후 귀법사에 머물다 입적하자 왕은 ‘원경’이라는 시호를 내렸다. 비문은 김부일이 짓고 글씨는 이원부가 썼다. 고려 인종 3년(1125)에 만들어진 이 비는 조각기법이나 간단한 형태의 지붕돌 등에서 고려 중기 특징을 잘 나타내고 있다.","a":"합천 반야사지 원경왕사비","c":"보물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622352.jpg"},{"q":"○○○○은 ○○의 치악산(해발 1,288m)에 위치한 돌로 쌓은 산성이다. 이 산성은 축조연대를 정확히 알 수 없으나 신라말 가장 큰 지방세력이었던 북원(北原)의 양길(梁吉)·궁예(弓裔)와 관련되어 있는 사적으로 인식되어 왔다. 또한 고려 충렬왕 17년(1291) 원충갑(元冲甲)이 지역의 방위군과 합단(哈丹)의 침략군을 통쾌히 무찌른 곳일 뿐만 아니라, 조선시대에는 임진왜란 때 목사 김제갑의 지휘 아래 ○○ 일대의 주민들이 끝까지 항전하다가 함락되어 수많은 장졸들이 목숨을 잃은 비극의 현장이기도 하다.","a":"원주 영원산성","c":"사적","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626153.jpg"},{"q":"○○○은 겸암 류운룡(1539∼1601)의 집으로 매우 오래된 풍산 류씨 종가이다. 입암 류중영(1515∼1573)의 호를 빌어 ‘입암고택(立巖古宅)’이라는 현판이 걸려 있는데 류중영은 류운룡의 아버지이다. ○○○은 류운룡의 6대손 류영(1687∼1761)의 어릴 때 이름에서 따 온 것이다. 규모는 앞면 4칸·옆면 3칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 오른쪽 3칸은 대청, 왼쪽 1칸은 온돌방으로 바깥 주위에 툇마루와 난간을 둘러 마치 누(樓)집과 같은 인상을 주며 대청에는 문을 달아 3칸 모두 열 수 있게 하였다.","a":"안동 하회 양진당","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620714.jpg"},{"q":"○○○○○은 해안으로부터 육지 쪽으로 300여미터 떨어진 ‘쌍호(雙湖)’라 불리는 호수를 매립하여 농토로 사용하기 위한 토사 채취 작업 중 흙에서 다량의 토기와 석기가 발견되면서 유적이 있음을 알게 되었다. 발굴조사를 통해 지금으로부터 약 8천년전 신석기 사람들이 살았던 유적으로 밝혀졌으며, 집터를 비롯하여 불을 피웠던 자리(野外 爐址)와 도구를 제작했을 것으로 보이는 흔적이 확인되었고, 덧무늬 토기(隆起文 土器) 등 다양한 형태의 토기와 어로생활을 짐작케 하는 결합식 낚시(이음낚시), 그물추(漁網錘)와 돌톱, 화살촉 등 당시의 생활을 엿볼 수 있는 특징적인 간석기도…","a":"양양 오산리 유적","c":"사적","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626100.jpg"},{"q":"○○○○○은 이 지역의 부자인 김기중(金褀中)이 1895년(조선 고종 32년)에 안채, 사랑채, 헛간채를 짓고 1903년(광무 7년)에 안사랑채와 곳간채를 지었다. 그 후 1984년 대문채를 복원하여 현재와 같이 \"ㅁ\"자형 공간구성을 하고 있다. 지붕은 초창자의 부에 맞지 않게 안채, 사랑채, 대문채 등이 모두 초가로 되어 있는데 당시 혼란한 사회에서 소박하게 보이기 위해서 초가로 한 것으로 보이며, 이 지역에서 나는 천연재료인 샛대로 지붕을 이었다는 설도 있다.","a":"부안 김상만 고택","c":"국가민속문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634547.jpg"},{"q":"조선 전기의 조선과 중국을 중심으로 동아시아 지역을 그린 세계지도이다. 바다의 물결무늬[수파묘(水波描)], 중국의 연호와 지명 등을 볼 때 16세기 중엽에 제작된 것으로 추정된다. 지도의 전체적인 윤곽은 1402년에 만들어진『혼일강리역대국도지도(混一疆理歷代國都之圖)』와 유사하지만, 조선 부분은 보다 자세하고 정확하게 그려졌다. 반면, 일본은 지도가 생략된 채 조선 남쪽에 위치만 표시되었다. 이처럼 중국과 조선만 자세히 그리고 그 외의 지역은 위치만 간략히 표시한 방식은 중국 중심의 세계관이 반영된 결과로 생각된다.","a":"화동고지도","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614926.jpg"},{"q":"김유신이 압량주 군주로 있을 당시 군사 훈련장이었다고 전해오는 유적이다. 압량리, 내리, 선화리, 두룩산 유적으로 구성되어 있으며 야트막한 언덕에 자리잡고 있다. 유적은 서북쪽의 구릉지대에 높은 대를 쌓은 고대식 광장과 동남쪽에는 무덤처럼 흙을 쌓아올려 높은 대를 만든 토축 고대가 연결되어 있다. 고대식 광장은 거의 원형이며 평탄한 넓은 장소를 광장으로 하고있다. 광장은 병사들이 무술을 익히고 심신을 연마하던 장소로 보이며 토축 고대는 장군의 지휘장소로 보인다.","a":"경산 병영유적","c":"사적","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627826.jpg"},{"q":"○○○○는 ○○시 구정면 학산2리 윗골마을의 마을회관 일대에 있는 절터이다. ○○○는 신라 문성왕 13년(851)에 범일국사(梵日國師, 810∼889)가 창건한 사찰로, 우리나라 9산선문(九山禪門) 중의 하나인 사굴산문의 중심 사찰이었다. ○○○는 고려시대에 지방호족들의 지원하에 번성한 후 조선초 이후의 문헌에는 등장하지 않는 것으로 보아 조선초 이후에는 폐사된 것으로 추정된다.","a":"강릉 굴산사지","c":"사적","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626162.jpg"},{"q":"경상북도 선산군 ○○○에 있는 종 모양의 ○○○○○ 안에서 발견된 육각의 ○○○이다. ○○○는 높이 17㎝로 기단, 몸체, 지붕으로 구성되어 있고, 표면에 도금이 잘 남아 있다. 평면 육각형으로 각 면의 기단에 안상을 뚫었다. 몸체의 두면에는 불자(拂子)와 금강저를 든 불교의 수호신인 천부상을 선과 점으로 새겼다. 남은 4면에는 사천왕상을 선으로 새겼다. 이들의 배치는 사천왕상 중에서 탑을 들고 있는 다문천을 중심으로 좌우에 천부상을 배치하여, 다문천이 정면에 올 수 있게 한 듯 보인다.","a":"도리사 세존사리탑 금동 사리기","c":"국보","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612901.jpg"},{"q":"청계 ○○의 ○○화로 크기는 가로 109㎝, 세로 142㎝이다. ○○은 조선의 학자로 중종 20년(1525)에 과거에 합격하여 이조판서까지 오른 인물이다. 모시바탕에 채색하여 그린 이 ○○화는 오른쪽을 바라보며 앉아 있는 모습으로 두 손은 소매 안에서 마주잡고 있다. 머리에는 높고 테가 넓은 전립을 썼으며 녹색의 옷을 입고 있다. 얼굴은 몇 개의 선으로만 처리했고 눈매는 매우 가늘다. 명상에 잠긴 듯한 얼굴과 전체적인 분위기가 학자로서의 면모를 암시하고 있다. 깔고 앉은 호랑이 가죽의 방석은 부피감이 없고 매우 평면적이지만 그림이 어색하지 않다.","a":"김진 초상","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622137.jpg"},{"q":"1934년 동해남부선에서 최초로 완공된 역사로 일제강점기 병력수송의 주요 거점이었으며, 오랫동안 역사 광장에서는 새벽장터로서 지역생활의 중심지가 된 곳으로 지역민들의 수많은 애환을 간직하고 있다. 또한, 건립 당시 및 변천과정의 모습을 소상하게 알 수 있는 건축도면이 현존하고 있는 등 역사성과 장소성 측면에서 보존가치가 충분하다","a":"부산 구 동래역사","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019060414341600.jpg"},{"q":"○○○이란 초기철기시대에 나타난 청동으로 된 거울로 잔무늬거울이라고 한다. 잔무늬거울의 뒷면에는 거울을 멜 때 사용하는 고리인 뉴가 우리나라의 경우 한쪽으로 치우친 곳에 2개가 돌출되었다. 또한 청동기 시대에 주로 보이는 거칠게 무늬를 새긴 거울(거친무늬거울)에 비해, 작은 삼각형을 기본으로 하여 기하학적 무늬를 세밀하게 새긴 것이 특징이다. 이 ○○○은 지름 21.2㎝로 뉴가 2개이며 내구(內區), 중구(中區), 외구(外區)로 3등분 되어있다. 각 구마다 작은 삼각형 무늬를 교차하는 방식으로 세밀하게 장식하였다.","a":"정문경","c":"국보","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611593.jpg"},{"q":"고려 후기의 승려인 보제존자의 사리탑으로, 모두 2기이다. 1915년, 일본인에 의해 국립중앙박물관으로 옮겨 세워졌는데, 보통 승려의 사리탑과는 달리 석탑 형식을 취하고 있다. 보제존자(1320∼1376)는 여주 신륵사에서 입적한 나옹화상으로, 신륵사에 그의 사리탑이 남아 있으나 제자들에 의해 영전사에도 따로 사리탑을 세운 것이다. 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단은 위·아래층 모두 모서리에 기둥조각을 새겼고, 위층 기단 윗면에는 탑신을 받치기 위한 돌을 따로 끼웠다.","a":"원주 영전사지 보제존자탑","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613281.jpg"},{"q":"○○○○○」은 낙포 이종문(1566~1638)이 1604년 경에 건립한 정면 3칸, 측면 2칸의 대청과 정면 1칸, 측면 4칸의 방들이 서로 붙어서 전체적으로 “丁”자형의 독특한 평면으로 구성되어 있는 정자형 별당 건물임. ○○○은 “丁”자형 평면을 가진 것도 독특하지만 건물의 용도를 주인과 하인이 같은 건물에 거주하는 것도 매우 이례임. 이 건물은 조선 중기에 건립된 평면형태가 독특한 정자형 별당 건축으로 공간구성과 세부기법 및 의장 등에는 많은 특색이 나타나고 있어 역사적, 건축적, 학술적 가치가 뛰어남.","a":"달성 하목정","c":"보물","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019122715264100.JPG"},{"q":"원래 경상북도 ○○군 정도사터에 있었던 5층 석탑으로, 1924년에 경복궁으로 이전하였다가 1994년에 국립대구박물관으로 다시 옮겨 세워 놓았다. 기단(基壇)은 2단으로, 아래층 기단에는 각 면에 안상(眼象)을 3구씩 조각하였는데 무늬의 바닥선이 꽃모양처럼 솟아오르고 있다. 위층 기단에는 각 면 중앙에 기둥 모양을 새겼고 각 기단의 맨윗돌은 약간의 경사를 이루었으며, 윗돌 윗면에 1단의 괴임을 두었는데 특별한 예에 속한다. 탑신(塔身)은 몸돌과 지붕들이 각각 한 돌로 되어 있다.","a":"칠곡 정도사지 오층석탑","c":"보물","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613278.jpg"},{"q":"가파른 산비탈을 평지로 만들기 위해서 동쪽과 북쪽으로 높이 4m 가량되는 돌축대를 쌓아 불단을 만들고 이 위에 사방불(四方佛)을 모셨으며, 1.74m의 간격을 두고 뒤쪽의 병풍바위에는 삼존불(三尊佛)을 새겼다. 삼존불은 중앙에 여래좌상을 두고 좌우에는 협시보살입상을 배치하였다. 화려한 연꽃위에 앉아 있는 본존불은 미소가 가득 담긴 양감있는 얼굴과 풍만하고 당당한 자세를 통해 자비로운 부처님의 힘을 드러내고 있다. 왼쪽 어깨에만 걸치고 있는 옷은 몸에 그대로 밀착되어 굴곡을 실감나게 표현하고 있다.","a":"경주 남산 칠불암 마애불상군","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612945.jpg"},{"q":"○○○○○은 줄여서 ‘대반야경’이라고도 부르기도 하며, 존재물 자체에는 실체가 없으므로 집착하는 마음을 갖지 말라는 공(空)사상을 주요사상으로 하고 있다. 당나라 현장(玄奘)이 번역한 것으로 전권은 600권이다. 이 경은 대반야경 600권 가운데 권 제305로, 불모품(佛母品)의 처음부분에 해당된다. 갈색의 종이에 은색으로 글씨를 썼으며, 병풍처럼 펼쳐서 볼 수 있는 형태로 되어 있고, 크기는 세로 30.9㎝, 가로 11.6㎝이다. 은색의 화려한 꽃무늬가 장식된 표지에는 제목이 금색으로 쓰여져 있으며, 그 뒤로 본문이 은색으로 쓰여져 있다.","a":"상지은니 대반야바라밀다경 권305","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614561.jpg"},{"q":"○○은 대가야의 옛 지역으로서 현재 무덤이 수백 기에 이르고 있다. 그 중 ○○○ 무덤들은 겉모습이 확실하고 봉분이 비교적 큰 무덤에 한하여 번호를 매겨 지금은 72호 무덤까지 정해져 있다. 이들 무덤의 겉모양들은 모두 원형의 봉토를 하고 있고, 봉토의 규모에 따라서 대형·중형·소형무덤으로 구분한다. 주로 대형무덤은 산등성이의 위쪽에 많이 있으며 중형무덤은 산등성이의 중간 정도에 모여 있고, 작은무덤들은 대형무덤과 중형무덤 주위나 그 밑에서 발견이 된다.","a":"고령 지산동 고분군","c":"사적","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627681.jpg"},{"q":"이 ○○은 조선 중종 36년(1541)에 최초로 건립된 것으로 추정된다. 1974년 ○○댐 건설로 인해 기존 위치에서 2㎞ 떨어진 외곽 산 중턱인 지금의 위치로 옮겨 세워졌다. ○○의 좌향(坐向)은 달라졌지만 기존 배치를 따라 건물의 형식은 원형과 동일한 형태로 이축됐다. 건물의 보존상태가 양호하고 사랑채와 안채, 그리고 좌·우익사가 연결된 ○○지역에서 많이 보이는 ‘ㅁ’자형 평면의 전형적 배치를 보여주며, 조선 중기 ○○지방 사대부들의 생활상과 건축에 대한 의식이 잘 반영되어 있는 유서 깊은 종가이다.","a":"안동 광산김씨 탁청정공파 종택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635741.jpg"},{"q":"우리나라 최초의 근대식 병원인 ○○○의 첫 해(1885.4.10-1886.4.10) 활동 ○○○이다. ○○○ 의사 알렌(H. N. Allen, 1858-1932)과 헤론(J. H. Heron, 1856-1890)이 ○○○ 개원 1주년을 맞아 작성한 것으로, 19세기 후반 우리나라 사람들이 앓던 질병의 양상을 연구하는 데 중요한 자료가 되며 표지 상단의 ‘Compliments H. N. Allen’이라 적은 알렌의 서명이 있어 의학사적·사료적 가치가 크다.","a":"제중원 1차년도 보고서","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667297.jpg"},{"q":"조선 시대 관아 건물인 ｢○○○○○｣는 선조 때 문신 백호(白湖) 임제가 호남의 삼한(三寒)인 ○○○○○, 남원 광한루(廣寒樓), 전주 한벽당(寒碧堂) 중에서도 으뜸으로 꼽으며 찬사를 아끼지 않았던 문화유산이다. 현판은 한석봉이 썼다고 전해지며, 수많은 묵객들이 글과 그림으로 풍류를 즐기던 곳으로 당시 시대상과 문화상을 알 수 있는 건물이다.","a":"무주 한풍루","c":"보물","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2021062409381200.jpg"},{"q":"보(補)는 조선시대 왕과 왕세자의 곤룡포(袞龍袍)나 ○○·세자빈의 적의(翟衣)·원삼(圓衫)·당의(唐衣)의 가슴과 등, 양 어깨에 부착하여 장식한 둥근 천으로 주로 용을 수놓았다. 문양에 따라 ‘용보(龍補)’라고도 하며 형태에 따라 ‘원보(圓補)’라고도 한다. 용은 상상의 동물로 예로부터 천자(天子)나 국왕을 상징하는 동물로 여겨왔기 때문에 조선시대 왕의 직계가족들은 용보를 부착하였으며 용의 발톱수로 신분의 구분을 두었다. 즉 왕과 ○○는 ○○○, 왕세자와 세자빈은 사조룡(四爪龍), 왕세손과 세손빈은 삼조룡(三爪龍)의 보를 사용하였다.","a":"오조룡 왕비 보","c":"국가민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2022011717170200.jpg"},{"q":"거돈사 옛 절터의 금당터 앞에 세워져 있는 탑으로, 2단의 기단(基壇)위로 3층의 탑신(塔身)을 올린 모습이다. 아래층 기단은 네 면의 모서리와 가운데에 기둥 모양을 새긴 형태로, 기단을 이루는 밑돌·가운데돌·맨윗돌이 각각 4매로 이루어진 특징이 보인다. 위층 기단은 남·북쪽에 무늬없는 긴 돌만 세우고 동·서면에는 가운데에 기둥 모양을 새긴 돌을 끼워 맞춘 방식이다. 즉, 남·북쪽에서 보았을 때 동·서면에 세운 석재의 두께가 자연스럽게 기둥 모양으로 보이도록 한 것이다. 탑신은 각 층의 몸돌과 지붕돌을 각각 하나의 돌로 구성하였다.","a":"원주 거돈사지 삼층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616737.jpg"},{"q":"조선시대 선조가 직접 써서 이조판서 등을 역임한 ○○○에게 남모르게 보낸 서찰 7건이다. ○○○은 선조 10년(1577) 문과에 급제하고 여러 벼슬을 두루 거쳐 호조를 제외한 5조의 판서를 지냈다. 명종 때에는 불교를 배척하여 중 보우를 처형할 것을 건의하기도 했다. 서첩은 원래 길게 이어있던 종이를 옆으로 적당하게 잘라, 그 앞뒤에 따로 표지를 붙인 것이다. 정조가 이 서첩을 보고 나서 7건에 대한 내용해설을 곁들여 직접 발문을 지어내리고, 호조판서에게 명하여 원첩을 궤에 담아 ○○○의 후손에게 되돌려주고 따로 한 부를 똑같이 써서 내각에 보관하도록 하였다.","a":"선조어서사 송언신 밀찰첩 및 송언신 초상 - 선조어서사 송언신 밀찰첩","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615892.jpg"},{"q":"조선 후기 전국의 군현 지도를 수록한 지도책이다. 제1~2책은 지도책, 제3책은 각 고을의 지리지로 구성되어 있으며, 제작 시기는 1800~1804년으로 추정되고 있다. 각 고을의 지도는 20리 방안에 그려져 있으며, 안동, 충주 등 일부 고을의 경우 1면에 최대 8개 고을까지 함께 수록되어 있다. 각 도별의 앞부분에 「팔도분표」를 수록하여 각 도에서 군현의 위치를 알 수 있게 하였다. 이 지도책은 앞서 제작된 20리 방안의 지도책을 실제 사용하기 쉽도록 재편집했다는 점에서 지도 제작의 발달 과정을 보여주고 있어 학술적 가치가 크다.","a":"해동여지도","c":"보물","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614929.jpg"},{"q":"1946년 ○○시 대안동에서 처음 발견되었다가 7, 8년 동안이나 행방을 알 수 가 없었는데, 그 후 다시 경북대학교 근처에서 발견되었다. 비(碑)는 길쭉한 모양의 자연석으로, 아래는 직선으로 잘려 있고 윗부분은 원형으로 처리되어 있다. 아래부분의 모습으로 보아 본래 받침돌 위에 세웠거나 암반 위를 파고 세웠던 것으로 여겨진다. 비의 내용은 건립날짜와 저수지 축조내용 및 관계된 사람들에 대한 것이다. 글자가 상당수 깎여나가 해석을 하는 데에 많은 어려움이 있으나, 신라시대 수리시설이나 사회사연구에 중요한 자료이다.","a":"대구 무술명 오작비","c":"보물","nc":"","r":"대구광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615217.jpg"},{"q":"굴포만이 있는 바닷가 앞의 넓은 들판에 자리하고 있는 가마터로, 토성으로 둘러싸인 안쪽 언덕에 주로 널려 있다. 모두 40여 곳으로 대부분 ○○○를 동서로 가로지르는 도로의 남쪽에 모여 있고 북쪽 야산 기슭에도 10여 곳이 있다. 대체로 12세기 중엽에서 13세기 전반에 걸치는 시기의 것들이며, 11세기 말 이나 12세기 전반의 것도 약간 있다. 그 중 가장 우수한 도자기 조각이 나오는 곳은 12호 가마터 일대이다.","a":"부안 유천리 요지","c":"사적","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626782.jpg"},{"q":"1954년 건립된 이 건물은 ○○○○○으로 건립되어, 지금은 목포대학교 경영행정대학원 건물로 사용되고 있다. 전면 중앙에는 박공지붕과 함께 육중한 캐노피를 설치하여 진입 현관으로서의 정면성을 강조하였고, 뒤쪽 출입구에 설치된 캐노피를 지지하는 기둥은 아래쪽을 위쪽보다 크게 하여 역동적으로 처리하는 등 디자인이 돋보인다. 목포 지역에서 생산되는 화강석을 이용하여 고전적인 의장 효과를 연출하였다.","a":"구 목포사범학교 본관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668970.jpg"},{"q":"가야산 중턱에 자리잡은 ○○○는 통일신라 애장왕 3년(802)에 지은 사찰로, 왕후의 병을 부처의 힘으로 치료해 준 것에 대한 감사의 뜻으로 지었다고 한다. 우리나라 3대 사찰 중 하나이며, 8만대장경을 보관하고 있기 때문에 법보사찰이라고도 부른다. ○○○○은 고려시대에 만들어진 8만여장의 대장경판을 보관하고 있는 건물로, ○○○에 남아있는 건물 중 가장 오래 되었다. 처음 지은 연대는 정확히 알지 못하지만, 조선 세조 3년(1457)에 크게 다시 지었고 성종 19년(1488)에 학조대사가 왕실의 후원으로 다시 지어 ‘보안당’이라고 했다는 기록이 있다.","a":"합천 해인사 장경판전","c":"국보","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1613038.jpg"},{"q":"○○○○○은 줄여서 ‘대불정수능엄경’또는 ‘능엄경’이라 부른다. 부처님의 말씀을 머리속으로 이해하는데 그치지 않고 자신이 직접 체득하여 힘을 갖는 것을 주요사상으로 하고 있으며, 스님들이 수련과정에서 필수적으로 배우는 경전이다. ○○○○대불정여래밀인수증료의제보살만행수능엄경 ○○(紺紙金泥大佛頂如來密因修證了義諸菩薩萬行首楞嚴經 卷七)은 당나라의 반자밀제(般刺密帝)가 번역한 능엄경 10권을 검푸른 빛이 도는 종이에 금색 글씨로 옮겨 쓴 것으로 현재 남아있는 것은 ○○에 해당한다. 병풍처럼 펼쳐서 볼 수 있는 형태이며, 접었을 때 크기는 세로 81.4㎝, 가로 11.1㎝이다.","a":"감지금니 대불정여래밀인수증요의제보살만행수능엄경 권7","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613819.jpg"},{"q":"『○○○○○』은 고려 공민왕 20년(1371)에 원나라로부터 수입하여 목판본으로 찍어낸 책으로, 송나라 주희가『사서(四書)』가운데 하나인『중용』에 대해 여러 문제점을 묻고 답하는 형식으로 서술한 책이다. 비교적 원본(元本)의 특징이 잘 나타나 있으며, 글자새김이 정교하고 인쇄가 깨끗한 편이다. 현재 두 권이 전해지는데 한 권은 고려대학교도서관에서, 다른 한 권은 개인이 소장하고 있다. 또한 책 끝에 홍호(洪虎) 4년(1371) 7월에 진주목에서 개판(開板)하였다는 기록이 있어 이는 고려시대 지방관판본으로 문헌학 연구에 귀중한 자료가 된다.","a":"중용주자혹문(1981-1)","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613701.jpg"},{"q":"통일신라시대에 창건된 ○○○에는 승려의 사리를 모셔놓은 승탑이 3개 있는데, 이 비(碑)는 동승탑 앞쪽에 서 있는 비로, 비몸돌이 없어진 채 받침돌과 머릿돌만이 남아 있다. 받침돌은 네 다리를 사방으로 쭉 뻗고 엎드린 용의 모습을 하고 있으나 사실성이 떨어지며, 잘려진 것을 복구해 놓아 부자연스럽다. 용의 등에는 새 날개 모양의 무늬를 조각해 놓아 새로운 느낌이다. 등 중앙에 비를 끼우도록 마련된 비좌(碑座)에는 구름무늬와 연꽃무늬가 장식되어 있다.","a":"구례 연곡사 동 승탑비","c":"보물","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618829.jpg"},{"q":"진각국사의 행적을 알리는 탑비로 창성사터에 있었다. 직사각형의 비받침 위에 비몸돌을 세운 다음 지붕돌을 올려놓았다. 비문을 새긴 비몸돌은 마멸이 심하고 오른쪽 모서리가 떨어져 나갔으며, 지붕돌은 경사면이 완만하다. 비문에는 진각국사가 13세에 입문한 뒤 여러 절을 다니며 수행하고 부석사(浮石寺)를 중수하는 등 소백산에서 76세에 입적하기까지의 행적이 실려있다. 입적한 다음 해인 우왕 12년(1386) 광교산 창성사 경내에 이 비가 세워졌다.","a":"수원 창성사지 진각국사탑비","c":"보물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615654.jpg"},{"q":"○○○○○는 1736년 의겸(義謙)이 으뜸화원을 맡아 그린 작품으로 화기에 “서부도전하단도(西浮圖殿下壇圖)”라는 기록이 있는 것으로 미루어 보아 서부도전에 봉안하기 위하여 조성하였음을 알 수 있다. 상단에는 칠여래와 관음, 지장보살, 인로왕보살, 중단에는 한 쌍의 아귀와 제단, 하단에는 육도 제상을 그린 형식을 취하고 있다. 이 ○○○○에서 주목되는 점은 상단에 그려진 칠여래가 중단과 하단에 비해 비중 있게 그려진 점인데, 이는 수륙재(水陸齋)를 통하여 중생들을 영가천도(靈駕遷度)하는 감로도의 기능을 강조하기 위해 의도된 것으로 여겨진다.","a":"순천 선암사 서부도암 감로왕도","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619982.jpg"},{"q":"선릉(宣陵)은 조선 9대 성종(1457~1494, 재위 1469~1494)과 세 번째 왕비 정현왕후 윤씨(1462~1530)의 능이다. 성종은 재위기간 동안 『경국대전』과 『대전속록』, 『국조오례의』를 완성하여 반포하였고, 선비들을 등용하여 기존의 훈구세력과 국정의 균형을 이루게 하였다. 정현왕후는 1473년(성종 4) 성종의 후궁이 되었고, 1480년(성종 11)에 왕비가 되었다. 선릉은 같은 능역에 하나의 정자각을 두고 서로 다른 언덕에 능을 조성한 동원이강릉(同原異岡陵)의 형태로 앞에서 봤을 때 서쪽 언덕이 성종, 동쪽 언덕이 정현왕후의 능이다.","a":"서울 선릉과 정릉","c":"사적","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624667.jpg"},{"q":"화동 구 경기고교는 스팀난방방식을 도입한 당시 최고급 철근콘크리트 구조의 학교 건물로 1938년 건립되었다. 6.25동란시 미군 통신부대에서 사용하였으며, 그후 1956년 다시 고등학교로 반환되었고, 1976년 고등학교 이전으로 1977년 이후 현재까지 정독도서관으로 사용되고 있다.","a":"서울 구 경기고등학교","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666869.jpg"},{"q":"○○○은 한국 현대건축사에서 매우 중요한 의미를 갖고 있는 김중업의 작품으로 그의 초기 건축적 특성을 잘 보여주는 대표적 작품 중 하나로 가치가 있음. 급한 경사지에 필로티를 이용하여 다른 건물로의 동선을 원활하게 하여 ○○을 중심으로 각 공간을 연결시키고 있으며, 규칙적인 모듈에 의한 평면 구성과 높은 층고, 전면 계단실의 넓은 유리를 통한 파노라마 경관, 후면부의 모자이크 창 구성 등이 특징적임.","a":"부산대학교 구 본관","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2126209.jpg"},{"q":"신라후기의 학자였던 최치원(857∼?)과 조선 중종(재위 1506∼1544)때 관리였던 신잠(申潛)을 모시고 제사지내는 서원으로, 교육기능과 제사기능을 모두 가지고 있다. 원래는 태산서원이라 하던 것을 숙종 22년(1696)에 임금으로 부터 이름을 받아 ○○○○이라 하게 되었다. 앞에는 공부하는 공간을 두고, 뒤에는 제사 지내는 사당을 배치한 전학후묘의 형식이다. 현재 남아있는 건물은 사당, 현가루, 동·서재, 비각, 명륜당 등이 있다.","a":"정읍 무성서원","c":"사적","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626843.jpg"},{"q":"○○○○○의 경우에는 선조 및 가문 관련 자료도 많지만 사실상 가문소장 자료라고 보기 어려운 경주 ○○ 등 유향소 관련자료, 구강서원 문서가 많이 소장되어 있다는 점이 특이하다. ○○○ 중 지정대상은 ○○○○ 소장 조사첩 2점, 교지·교첩·차첩류 23점, 소지 1점 이다. 조사첩(朝謝帖)은 이조(吏曹)에서 사헌부의 서경(署經)을 거친 사실이 기록된 것으로 고신식(告身式)이 확정되기 이전의 고려적인 양식이 남아있어 귀중하다. 조사첩은 사헌부의 서경을 받는 최종 종결로 보여지며 이 조사첩을 발급받는 것은 관료가 해당관직에 정식으로 임명되는 것을 의미한다.","a":"경주이씨 양월문중 고문서 및 향안","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622241.jpg"},{"q":"1930년 건립 이 ○○○는 일제 강점기 당시 ○○에 거주하던 일본인과 일제 부역자들에게 물을 공급하기 위해 건립되었다. 석재를 직사각형으로 반듯하게 가공하여 돌과 돌 사이에 모르타르를 채워 댐을 쌓았으며, 석재를 경사지게 쌓아 올라가다가 상부 2/3 정도 지점에서 수직으로 쌓아 구조적으로 안정된 느낌을 준다. 이 지역 대다수의 시민들이 우물물을 길어 먹던 상황에서 건립된 ○○○이며, 당시의 댐 축조 기술을 잘 보여주고 있다.","a":"마산 봉암수원지","c":"국가등록문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669427.jpg"},{"q":"○○○○○은 흙으로 조성한 것으로 ○○○ 천왕문의 좌우에 2구씩 모두 4구가 안치되어 있다. 사천왕상의 배열은 천왕문의 향 우측으로 비파를 든 북방 다문천왕과 검(劍)을 든 동방 지국천왕이, 향 좌측으로는 당(幢)을 든 서방 광목천왕과 용·여의주를 든 남방 증장천왕이 각각 시계방향으로 북→동→남→서방의 순서로 안치되어 있다.","a":"순천 송광사 소조사천왕상","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619945.jpg"},{"q":"강원특별자치도 지역 선교를 담당할 수녀 양성을 위한 시설로 1959년 신축 이후 1962년 증축되는 과정에서 시기를 달리하는 2동의 건물을 유기적으로 연결시켜 하나의 공간으로 만들어 낸 건축수법 등이 특징적이라 할 수 있으며, 또한 강원특별자치도 지역 선교활동 중심지라는 장소성 측면에서도 의미하는 바가 크다고 할 수 있다.","a":"구 영원한 도움의 성모수녀회 춘천수련소","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019021819440200.jpg"},{"q":"○○○에 자리하고 있는 낭원대사의 사리탑으로, 8각의 평면을 기본으로 하고 있다. 무너져있던 것을 사찰입구에 복원해 두었다가, 1991년 다시 원래의 자리인 산꼭대기 주변으로 옮겼다. 탑신(塔身)을 받치는 기단(基壇)은 세 개의 받침돌로 이루어져 있었으나, 지금은 가운데받침돌이 없어져 아래받침돌 위에 바로 윗받침돌이 얹혀있다. 탑신의 몸돌 한쪽 면에는 문 모양과 자물쇠 모양을 새겨 두었다. 지붕돌은 두터운 편이며, 경사가 급하고, 여덟 곳의 귀퉁이마다 꽃장식을 얹었던 흔적이 남아있다. 지붕돌 꼭대기에는 머리장식이 놓여 있다.","a":"강릉 보현사 낭원대사탑","c":"보물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616419.jpg"},{"q":"1935년 건립된 이 건물은 일제 강점기 당시 건립된 ○○으로, 학교 ○○의 기능을 했을 뿐만 아니라 ○○ 지역 사회의 대형 집회 공간으로 이용해 온 역사적인 장소이다. 15미터나 되는 너비를 중간 기둥 없이 처리한 것이 특징적이며 전체적으로 아주 간결하면서도 기능적이다. 이 건물은 당시 ○○○○○ 학생들이 많은 애국지사 등의 강의를 들으며 청운의 꿈을 키웠던 곳이기도 하다.","a":"인천 제물포고등학교 강당","c":"국가등록문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667840.jpg"},{"q":"○○○는 신라시대 의상대사가 세웠다고 한다. 지형에 따라 건물을 자연스럽게 배치한 ○○○○○은 부처님의 제자인 나한을 모신 곳이다. 임진왜란(1592) 이후 새롭게 지은 것으로 생각하는데 1984년 수리를 할 때 발견한 기록에 따르면, 조선 명종 8년(1553)에 처음 지었고 인조 12년(1634)에 다시 지었음을 알 수 있다. 건물 규모는 앞면 3칸·옆면 1칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위뿐만 아니라 기둥 사이에도 있는 다포 양식으로 꾸몄다.","a":"영주 성혈사 나한전","c":"보물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621532.jpg"},{"q":"이 ○○○○○은 조선초기 분청의 전형적인 병 형태로써 전면에 굵고 대담한 상감문양을 새겨 넣었다. 목부분에는 연주문(連珠文)이 상감되고 그 아래의 어깨부분에는 두 개의 문양대로 나누어 인화기법을 사용하여 국화문(菊花文)을 꽉 차게 배치하였다. 몸통에는 파도위로 헤엄치는 물고기를 크게 두 군데 상감하고 그 밑에는 당초문대(唐草文帶)를 둘렀는데 모두 백상감으로 하였다. 파어문의 해학성이 뛰어나고 활달한 문양과 다리에까지 문양을 넣어 제작한 점 등이 돋보인다.","a":"분청사기 상감파도어문 병","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614855.jpg"},{"q":"1940년대 미국에서 생산되어 제2차 세계대전 중 미 육군이 사용하던 2인승 연락용 경○○○이다. 1948.9.13. ○○○○ 공군의 전신인 육군항공대가 미군으로부터 인수한 10대 중 1대로 우리나라 공군으로서 보유한 ○○의 ○○○이다.","a":"대한민국 최초 항공기(L-4 연락기)","c":"국가등록문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668542.jpg"},{"q":"이 건물은 ○○○○○의 본당으로 미국 선교부의 지원을 받아 건립하였다. 동서로 긴 장방형의 평면에 출입구 위에는 박공지붕의 포치(porch)를 돌출시켜 정면성을 강조하였으며, 출입구 지붕 아래에 목구조를 응용하여 십자가 형태를 표현해 종교 시설임을 나타냈다.","a":"영덕 송천예배당","c":"국가등록문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669127.jpg"},{"q":"공주시 ○○○릉에서 발견된 백제 때 금으로 만든 ○○○ 일종의 머리 장신구이다. ○○○릉 나무널(목관) 안 왕의 머리에서 발견되었으며, 길이는 18.4㎝, 상단의 폭은 6.8㎝이다. 위가 넓고 아래가 좁은 역삼각형 모양이며, 밑은 세가닥의 핀 모양을 이루고 있어 머리에 꽂았던 것으로 보인다. 역삼각형의 윗부분은 새가 날개를 펼치고 있는 모습이고, 3가닥으로 갈라진 꽂이 부분은 긴 꼬리처럼 되어 있어 마치 날고 있는 새의 모습을 하고 있다. 양 날개쪽 좌우에는 꽃무늬를 도드라지게 찍었고, 그 아래는 서로 대칭으로 덩굴무늬를 빈틈없이 메꿔 놓았다.","a":"무령왕 금제 뒤꽂이","c":"국보","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612282.jpg"},{"q":"이 화차(貨車)는 지붕이 있는 협궤선용 화물열차로 미국에서 제작하였다. 레일 사이의 간격이 표준보다 좁은 협궤 노선인 수인선(수원~인천 송도), 수여선(수원~여주)에서 농산물 등 지방의 특산물을 수송하였으나, 1995년 수인선이 폐지됨에 따라 운행이 중단되어 지금은 사용하지 않는다.","a":"협궤유개화차","c":"국가등록문화유산","nc":"","r":"경기도","s":"의왕시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668165.jpg"},{"q":"○○○에 세워져 있는 탑으로, 1단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이나, 기단과 탑신의 여러 군데가 갈라지거나 떨어져 나간 상태이다. 기단은 네 모서리에 두터운 기둥을 세우고, 그 사이마다 판돌을 끼워 두었는데 그 중 한 면에는 판돌이 없이 작은 돌들로 채워져 있다. 이렇게 모서리기둥을 본떠 새기지 않고, 직접 세운 것은 부여 정림사지 오층석탑(국보)에서도 볼 수 있다. 탑신의 1층 몸돌은 각 면마다 감실(龕室)을 팠는데, 목탑에서의 감실은 불상을 모셔두는 곳으로 들어갈 수 있는 공간이었으나, 석탑에서는 이처럼 형식적인 조각만 하게 된다.","a":"강진 금곡사 삼층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619386.jpg"},{"q":"1936년 건립된 이 건물은 ○○○의 법회를 위한 본부건물로서, 사무 공간과 불교 의식을 주관하는 법당으로 이루어져 있다. 사무 공간은 가운데에 복도가 있으며, 그 우측의 법당은 내부 3칸에 불단이 있다. 지붕틀은 트러스 위쪽에 서까래를 얹은 구조로, 한옥 건축 형식과 서양식 목조 트러스 지붕이 혼합된 모습을 보여주고 있다.","a":"대전 수운교 본부법회당","c":"국가등록문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667979.jpg"},{"q":"ㅇ 연혁 - 1925년 4월 16일 당시 토목업에 종사했던 다나카(田中筆吉)는 1876년 오카야마현 출신으로 경부선 신설공사를 수행하기 위하여 한반도로 건너온 것으로 알려져 있다. 1914년에는 다나카구미(田中組)를 만들어 ○○진 매축, 동해 남부선 공사 등에 참여하였다. (조선공로자명감 참조)에 의해 현재 중앙부에 위치한 1층 규모의 속복도형 목조 일식주택이 건립. - 1931년 6월 2층 규모의 목조 일식주택이 1차 증축.","a":"부산 초량동 일본식 가옥","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667733.jpg"},{"q":"○○은 『삼국사기』에 나오는 진한의 12개 나라 중 하나인 불사국으로, 비사벌이라고 불리던 곳이다. ○○읍 교리 및 송현리 일대에 넓게 분포하고 있는 대형 ○○○으로, 1911년 일본인 학자 세키노 타타시에 의해 처음 알려졌다. 150여기 정도가 확인되는데, 출토유물과 구조양상을 볼 때 5~6세기가 중심연대가 되는 ○○○으로 파악되고 있다. ○○교동○○○과 ○○○○○이 ○○○○○으로 2011년 7월 28일에 다시 지정되었다. ○○○○○은 가야○○○으로 2023년 9월 24일 세계유산으로 등재되었다.","a":"창녕 교동과 송현동 고분군","c":"사적","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628509.jpg"},{"q":"○○○는 신라 선덕여왕 9년(640) 자장율사가 세웠다는 설과 신라의 승려 무선이 당나라에서 돌아와 세웠다는 두 가지 설이 전한다. 신라말부터 고려 전기까지 폐사되었던 절로 고려 명종 2년(1172) 보조국사가 절을 다시 세웠으나 임진왜란 뒤 60년 동안 다시 폐사되었다. 훗날 조선 효종 2년(1651)에 각순대사가 대웅전·영산전·대적광전 등을 고쳐 지었다고 한다. ○○○○은 석가모니불을 모신 법당을 가리키는데 이 법당은 석가모니불을 중심으로 약사여래불·아미타불을 모시고 있다. 조선시대 각순대사가 절을 다시 일으킬 때(1651) 고쳐 지은 것이라고 한다.","a":"공주 마곡사 대웅보전","c":"보물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617959.jpg"},{"q":"○○ 보원사터에 위치한 ○○이다. 보원사는 고란사라고도 하며 사찰에 대한 역사는 전혀 알려지지 않고 있으나 1959년 국보인 ○○ 용현리 마애여래삼존상이 발견되면서 큰 관심을 끌었던 곳이다. ○○는 승려들이 물을 담아 쓰던 돌그릇으로, 원형·팔각형·장방형 등이 있다. 이 ○○는 화강석의 통돌을 파서 만든 직사각형 모양으로 통일신라시대의 일반적 형식을 보인다. 규모가 거대하며 표면에 아무 장식이 없어 장중해 보인다. 내부 각 면에도 조각한 흔적이 없으며, 밑바닥면은 평평하고 한쪽에 약 8㎝정도의 원형 배수구가 있을 뿐이다.","a":"서산 보원사지 석조","c":"보물","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617472.jpg"},{"q":"○○○에 모셔진 보제존자 나옹의 탑비이다. 보제존자 나옹은 선종과 교종을 통합하여 불교를 다시 일으켜 세우려 하였던 승려로, 양주 회암사의 주지로 있다가 왕의 명을 받아 밀양으로 가던 도중 이곳 ○○○에서 입적하였다. 이후 그를 따르던 문도들이 절안에 터를 마련하여 사리를 안치한 석종과 석비를 세워두었다. 비는 3단의 받침 위에 비몸을 세우고, 지붕돌을 얹은 모습이다. 받침부분의 윗면에는 연꽃무늬를 새겨 두었다. 대리석으로 다듬은 비몸은 양옆에 화강암 기둥을 세웠으며, 지붕돌은 목조건물의 기와지붕처럼 막새기와와 기왓골이 표현되어 있다.","a":"여주 신륵사 보제존자석종비","c":"보물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615714.jpg"},{"q":"'○○○○○'은 줄여서 “대불정수능엄경” 또는 “능엄경”으로 부르기도 하는데, 부처님의 말씀을 머리 속으로만 이해하는데 그치지 않고 자신이 직접 경험하여 얻을 것을 주요사상으로 하고 있다. 능엄경은 전○○권으로 되어 있으며, 지금도 우리나라의 일부 선종사찰에서는 이 경의 제7권에 수록된 수능엄다라니를 외우는 것을 매일의 일과로 삼고 있다. '능엄경'은 고려 소자본 능엄경을 비롯하여 조선시대 초기의 대자본, 활자본, 간경도감에서 간행한 언해본을 비롯하여 다양한 판본이 전래되고 있다.","a":"대불정여래밀인수증요의제보살만행수능엄경 권2, 10","c":"보물","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616112.jpg"},{"q":"○○○ 예비대 ○○으로 상·하의 한 벌로 구성되어 있다. 대한민국임시정부 군무부(軍務部)는 1945.2.19. ‘군인제복 양식 제정안’을 제정, 국무회의 의결을 거쳐 공포·시행하였다. 그 전까지는 일정한 제복이 없이 중국식의 ○○과 표지를 사용하였으나, 복식제식이 정해진 후 독자적으로 ○○○의 표지와 ○○을 사용하거나 착용하였다. 이 ○○은 1972년에 서울시청 금고에서 발견된 후 육군사관학교에 기증되어 육군박물관에 전시되고 있는 것으로, 우리나라 ○○○ 복장의 대표적인 유물로서 현재까지 발견된 국내 유일의 ○○○○○이다.","a":"한국광복군 군복","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667337.jpg"},{"q":"1935년 건립 이 건물은 한센병 환자들을 위해 설립된 보통학교 ○○이다. 장방형의 본관 건물과 화장실 및 샤워실이 회랑으로 연결되어 있으며 남쪽에는 교실을 배치하고 북쪽에 복도를 두는 등 오늘날 학교 건축과 유사하게 설계되었다. 한센병 환자를 대상으로 자체적으로 설립한 초등학교라는 점에서 의미가 있다.","a":"고흥 소록도 구 녹산초등학교 교사","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668887.jpg"},{"q":"\"『○○○○○』은 조선 태조(太祖)에서부터 조선 철종(哲宗) 때까지 25대 472년간(1392～1863)의 역사를 연대순으로 정리한 책이다. 완성된 실록은 재난에 대비하고자 춘추관사고(春秋館史庫; 서울), 정족○○○, 태백○○○, 오대○○○, ○○○○○의 전국 5대 사고(史庫)에 보관하였다. 기 지정 범위에 포함되지 않았던 ○○○○○은 6.25전쟁 당시 북한으로 유출되어 보존되고 있다고 전할 뿐 현품은 물론 실상 또한 알려져 있지 않았다. 이번에 확인된 ○○○○○은 국립중앙박물관 소장의 1책과 한국학중앙연구원 장서각 소장의 3책 등 모두 4책이다.","a":"조선왕조실록 적상산사고본","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2017052309403900.jpg"},{"q":"○○○는 조선 숙종 15년(1689) 성해대사가 건물을 세우고 불상을 모시면서부터 비로소 절의 모습을 갖추게 되었다고 한다. 조선 중기 이후에 다시 지은 것으로 보이는 ○○○은 불교도의 이상향인 극락정토를 표현하고 있는 법당이다. 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조를 기둥 위와 기둥 사이에 배치한 다포 양식으로 꾸몄다. 기단 앞부분에는 연꽃무늬와 거북 무늬를 조각하고 주변에 Ｈ자 모양의 선 조각을 하였다.","a":"청도 대적사 극락전","c":"보물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621580.jpg"},{"q":"<○○○○○>은 고려시대 장군인 ○○○을 그린 ○○화로, 크기는 가로 61.3㎝, 세로 80㎝이다. ○○○은 고려시대 명장으로 목종(재위 997∼1009) 때 문과에 급제하였고, 현종 3년(1012) 동여진이 침입하자 안찰사로서 군대를 이끌고 나가 격퇴하였고 현종 9년(1018) 거란이 침입하자 이를 막아내는데 큰 공을 세우기도 하였다. 과거에 급제한 후 쓰던 모자인 복두에 정장을 하고 홀(笏)을 들고 앉아서 왼쪽을 바라보고 있는 반신상이다. 의자 등받이에 있는 호랑이 가죽은 18세기 ○○화의 특징을 보여준다.","a":"강민첨 초상","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613524.jpg"},{"q":"○○○○○은 내륙지방에서 발견된 최초의 신석기시대 ○○ 유적이며, 우리나라에서 가장 오래된 선사시대의 배와 신석기시대 편물기술을 보여주는 망태기를 비롯하여 대규모 도토리 저장시설 등이 출토되어 신석기시대연구에 중요한 자료로 확인되었다. 배수장 건립 과정에서 발견되어 현재 배수장은 전시관으로 리모델링하고 있다.","a":"창녕 비봉리 패총","c":"사적","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628485.jpg"},{"q":"의자 위에 앉아 오른발을 왼쪽다리 위에 올려 놓고, 오른쪽 팔꿈치를 무릎 위에 올린 채 손가락을 뺨에 댄 모습의 보살상으로 높이는 80㎝이다. 1912년에 일본인이 입수하여 조선총독부에 기증했던 것을 1916년 총독부박물관으로 옮겨졌고, 현재는 국립중앙박물관에서 보관하고 있다. 머리에는 화려한 관(冠)을 쓰고 있으며, 여기에서 나온 2가닥의 장식은 좌우로 어깨까지 늘어져 있다. 네모꼴에 가까운 얼굴은 풍만한 느낌을 주며, 광대뼈를 나오게 하고 입가를 들어가게 하여 미소 띤 얼굴을 만들었다.","a":"금동미륵보살반가사유상(1962-1)","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611483.jpg"},{"q":"○○○은 경주 황남동고분 제155호 무덤으로 1973년 발굴하여 금관, 팔찌 등 많은 귀중한 유품들과 함께 천마 그림이 발견되어 ○○○이라 부르게 되었다. ○○○○○은 ○○○ 안의 널<관(棺)> 머리쪽에 있던 유물 보관함에서 발견된 것으로 큰 새의 날개가 펼쳐 있는 모양이고, 밑은 방패 모양으로 된 장식이 달려있다. 몸체와 좌우의 날개에는 덩굴무늬를 파 놓았는데, 가장자리의 테두리와 줄기부분에는 세밀하게 점선을 찍어, 얇고 긴 금판이 힘을 받도록 했다. 표면 전면에는 지름 0.7㎝정도의 원판을 400여개 정도 금실로 연결하여 매우 화려해 보인다.","a":"천마총 금제 관식(1978-2)","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621294.jpg"},{"q":"○○○○○은 입상의 삼존불상을 배경으로 본존불상 머리 좌우에 가섭존자와 아난존자를 배치시켜 5존도 형식을 취하였다. 삼존불상 가운데 통견(通肩)의 적색 대의(大衣)에 밝은 회청색 내의를 착용한 본존 불상은 머리 높이가 180㎝이고 머리 광배의 폭만도 무려 273㎝에 이르러 10미터가 넘는 화면 전체를 다 차지할 정도로 큼직하게 그려져 있다. 적색 대의에는 봉황문과 화문, 격자문, 연화문 등의 둥근 무늬가 전체에 걸쳐 정연하게 시문되어 있으며, 내의에는 흰색의 연꽃무늬가 장식되어 있다.","a":"예천 용문사 영산회 괘불탱","c":"보물","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622238.jpg"},{"q":"○○ 금성동에 위치한 ○○○의 구릉지대에 자리잡은 유적으로 1996년 국립○○박물관의 발굴조사 결과에 따라 백제시대 국가적 차원의 제의시설로 추정되는 유적이다. ○○○○○에서는 국가의 중요시설에만 사용된 8잎의 연꽃잎이 새겨진 수막새가 발견되었고, 화려한 장식이 부착된 장고형 그릇받침 등 국가 제사와 관련된 유물이 출토되었다. 유적의 입지 방향은 무령왕릉에서 출토된 무령왕과 왕비의 매지권에 기록된 신지(申地), 유지(酉地)의 방향과 일치하고 있어, 일부 학자들은 왕비의 시신이 사후 무령왕릉에 안치되기까지 2~3여 년간 수습되어 보관된 곳일 가능성을 제기하고 있다.","a":"공주 정지산 유적","c":"사적","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626757.jpg"},{"q":"고려의 마지막 왕인 ○○○과 그의 부인 순비 노씨의 무덤이다. ○○○은 이성계 등에 의해서 즉위한 이름뿐인 왕이었다. 조선 건국 직후 원주로 추방 되었다가 태조 3년(1394)에 삼척부에서 두 아들과 함께 살해되었다. 태종 16년(1416)에 ○○○으로 봉하고 ○○현에 무덤을 마련하였다. 왕과 함께 묻힌 왕비는 노신의 딸로 숙녕·정신·경화 세 공주와 창성군을 낳았으나 고려가 멸망한 후 왕과 함께 폐위되었다. 무덤은 쌍능 형식으로 무덤 앞에는 비석과 상석이 하나씩 놓여 있고, 두 무덤 사이에 석등과 돌로 만든 호랑이 상이 있다.","a":"고양 공양왕릉","c":"사적","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625506.jpg"},{"q":"○○○○○는 규모가 큰 ○○○로서 높이와 몸통의 비례가 적당하며 몸통의 둥근 곡선도 매우 부드럽게 이어져 있다. 몸통이 둥글고 큰 양감을 나타내는 반면 입과 굽이 상대적으로 작은 편이어서 단정한 느낌을 준다. 좌우대칭도 완전한 편이고 몸통에 별다른 움직임과 변화가 없으며, 투명한 유약층 밑으로 엷은 유백색을 띠는 태토가 비쳐 보여 전체적으로 평온한 분위기를 주며 보존상태도 우수하다.","a":"백자 달항아리(2005-3)","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614842.jpg"},{"q":"고령상무사는 경북 고령장을 중심으로 하여 인근 상권을 장악했던 조선 ○○○단 지부를 일컫는 이름이다. 좌사계(左社契)는 매년 음력 정월에 총회를 열고 임기 1년의 새로운 반수와 접장을 선출한 뒤, 이미 세상을 떠난 역대 반수와 접장 140명의 위패를 모신 가운데 제상을 마련 대제를 지냈다. 선배 ○○○의 유덕을 기리며 인근 마을의 안녕을 기원하는 지신밟기 등 농악놀이로 축제를 벌였다. 이 지역은 낙동강 유역과 근접된 곳으로 배편을 이용하여 소금, 생선 등의 물자가 교역되었다. 또한 토질이 자기(磁器) 생산의 최적지로 알려져 물량이 많이 생산되었다.","a":"보부상 유품(5)","c":"국가민속문화유산","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634817.jpg"},{"q":"이 불상은 머리만 없어졌을 뿐 불신(佛身), 대좌(臺座), 광배(光背)까지 고스란히 남아 있는 백제의 작품이다. 지금의 머리는 새로 만든 것이며, 불상의 현 신체 높이는 156㎝이다. 당당한 어깨, 균형잡힌 몸매, 넓은 하체 등에서 서툰 듯 하면서도 탄력적이고 우아한 면을 보여주고 있다. 양 어깨를 감싸고 있는 옷자락은 길게 내려져서 사각형의 대좌를 덮고 있는데, 앞자락은 U자형, 좌우로는 Ω형의 주름이 대칭으로 2단씩 표현되어 있다.","a":"익산 연동리 석조여래좌상","c":"보물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618224.jpg"},{"q":"“○○○○○”은 입향조의 8대손이 1779년에 외풍을 막아주고 낙엽 등이 모인다 하여 잘 산다는 의미를 갖고 있는 ‘소쿠리형’(또는 삼태기형) 명형국지(名形局地)의 한 가운데 지은 집으로 옛 모습이 비교적 잘 남아 있다. 사당․사랑채․안채가 유교사상에 입각한 위계질서에 따라 각기의 고유영역을 이루며 배치되고 구조양식도 이 위계에 따라 격조를 조금씩 달리하고 있으며, 쪽마루․수납공간․환기창․고창 등이 발달한 특징을 잘 보여주고 있다.","a":"영주 괴헌고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635687.jpg"},{"q":"○○○의 법당 앞에 세워져 있는 탑으로, 밑부분인 기단(基壇)이 땅속에 거의 파묻힌 채 그 위로 3층의 탑신(塔身)을 쌓아 올렸다. 땅위로 드러난 기단의 맨윗돌은 4장의 돌로 짜여져 있으며 경사져 있다. 탑신은 모두 지붕돌과 몸돌이 각각 한돌로 이루어져 있고, 몸돌에는 모서리마다 기둥모양이 새겨져 있다. 지붕돌 밑면의 받침수는 모두 3단씩이나, 높이의 차가 심해서 형식화된 느낌을 준다. 또한, 지붕돌 네 귀퉁이의 옆면을 급하게 깍아 지붕돌 전체가 무거워 보인다.","a":"순천 동화사 삼층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619413.jpg"},{"q":"○○ 북천가에 있는 신라 제41대 ○○○의 무덤이다. ○○○의 본명은 김언승이며, 조카인 애장왕을 죽이고 왕이 되었다. 재위기간 동안에 농사를 권장하고 당나라와 친밀한 관계를 유지했으나, 김헌창의 난과 김범문의 난이 일어나는 등 국내정세가 혼란스러웠다. 『삼국사기』에 의하면 826년에 왕이 죽자 천림사의 북쪽에 장사지냈다고 한다. 천림사의 위치는 정확히 알 수 없으나 이 왕릉의 남쪽에 절터가 있어 이곳을 천림사 터로 본다. 이 능은 원형 봉토분으로 지름 26m, 높이 6m이다. 봉분 밑의 둘레를 따라 둘레돌을 배치하여 무덤을 보호하도록 하였다.","a":"경주 헌덕왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627595.jpg"},{"q":"○○○ 절벽에 새겨진 마애약사삼존불입상으로 통일신라 애장왕 2년(801)에 만든 것이다. 본존은 왼손에 약그릇을 들고 있어서 약사여래상임을 알 수 있으며 얼굴이 타원형으로 길게 표현되었다. 어깨는 거대한 몸에 비해 좁게 표현되었고, 힘없이 표현된 신체에서는 긴장감을 느낄 수 없다. 이는 불상 양식이 8세기의 긴장감과 활력이 넘치던 이상적 사실주의 양식에서 현실적인 모습으로 변화하고 있음을 보여준다. 양쪽의 협시보살은 모두 본존을 향하여 자연스럽게 서 있다. 왼쪽은 일광보살로 남성적인 강렬한 인상이고, 오른쪽은 월광보살로 눈썹사이에 달무늬가 새겨져 있다.","a":"함안 방어산 마애약사여래삼존입상","c":"보물","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622386.jpg"},{"q":"- 개요 진산지역은 조선조 후기에 이승훈으로부터 세례 받은 윤지충이 가족들에게 ○○○를 전파한 곳으로 한국 ○○○ 역사에서 최초의 박해였던 신해박해(1791년)의 진원지에 해당하는 곳이다. 이후 1887년 신앙의 자유가 허락되어 ○○○인들이 다시 모일 수 있게 되자 공소형태로 종교집회를 가질 수 있게 되었고 민가에서부터 시작된 교회건물이 몇 차례 지어 졌고 1927년에 건립된 성당건물이 현재까지 미사공간으로 사용되고 있다.","a":"천주교 진산성지성당","c":"국가등록문화유산","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017060117355100.JPG"},{"q":"불씨를 손으로 점화·발사하는 유통식화포(有筒式火砲)는 그 크기와 사용되는 화약의 양, 발사거리에 따라 4가지로 분리하여 천자문에서 그 이름을 따 천(天)·지(地)·현(玄)·황(黃)자총통이라 붙인다. 이 것은 그 중 가장 크기가 작은 것으로, 편리한 이동을 위해 만든 것이다. 총구경 4㎝, 전체길이 50.4㎝로, 임진왜란 5년전인 선조 20년(1587)에 만들었다는 기록이 남아 있다. 포 입구에서부터 점차 두터워지고, 몸에는 대나무 모양의 4마디가 표현되어 있다. 포의 끝은 둥글며, 첫째와 둘째마디 사이에는 손잡이가 달려 있다.","a":"황자총통","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614200.jpg"},{"q":"○○○○○은 풍산 유씨의 동족마을로 빼어난 자연경관과 민속·유교 전통을 잘 유지하고 있는 조선시대 양반촌이다. 이 집은 서애 유성룡(1542∼1607) 선생의 맏형인 겸암 유운룡(1539∼1601) 선생이 학문 연구와 제자를 가르치기 위해 세운 것이다. 조선 명종 22년(1567)에 지었다고 하며 부용대 서쪽 높은 절벽 위에 자리잡고 있다. 정사(사랑채)는 ○○○○이 바라다 보이는 남쪽 절벽 위편에 안채는 정사 뒤쪽에 배치하였다. 정사는 2층 누각 형식으로 앞면 4칸·옆면 2칸 크기이다. 가운데에 대청 4칸을 두고 좌우로는 방을 두었다.","a":"안동 하회마을 겸암정사","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635073.jpg"},{"q":"조선시대 학자들의 필독서였던 이 ○○○은 권14말에 세종 18년(1436) 6월에 쓴 김문(金汶)의 발문이 있어 인출연대(印出年代)가 분명하고 또 조선시대를 대표하는 활자(活字)인 초주갑인자(初鑄甲寅字)로 인쇄된 완질본(完帙本)이며 보존상태가 양호하다는 점에서 서지학 및 성리학 연구에 중요한 자료가 된다. 품위 있는 장서인(藏書印)이 4방 찍혀 있어 이 책의 가치를 높여 주고 있다.","a":"근사록(2006)","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614477.jpg"},{"q":"안채·사랑채·광채·문간채·일각대문·사당으로 구성되었다. 안채를 포함하여 모두 20세기 초 이후에 지어진 건물이며, 광채만 18세기 정도로 추정할 수 있는 아주 특이한 건물이다. 광채는 목조 초가지붕집으로 오른쪽의 한 칸만을 외부로 개방하여 헛간으로 쓰고 있을 뿐, 나머지 3칸은 판자벽을 두르고 마루를 깔아서 광으로 쓰고 있다. 이와 같은 건축수법과 구성은 대단히 오래된 기법이다. 안채는 광채의 왼쪽에 남북으로 위치하며, 뒤편 동산의 숲과 잘 이루어져 운치가 있다. 왼쪽부터 건넌방·대청·안방·부엌이 배열되었다. 사당은 부엌 오른쪽에 자리했다.","a":"영동 성장환 고택","c":"국가민속문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634035.jpg"},{"q":"○○○은 조선중기 17세기의 문인ㆍ명필로 본관은 여주(驪州), 자는 하경(夏卿), 호는 매산(梅山)ㆍ육우당(六寓堂)이다. 소릉(少陵) 이상의(李尙毅, 1560~1624)의 손자이며 이지안(李志安, 1601~1657)의 아들이다. 1666년 문과에 급제, 대사간ㆍ대사성ㆍ예문관제학ㆍ병조참판 등을 지냈다. 아들 옥동(玉洞) 이서(李漵, 1662~1723)는 학자ㆍ명필이었고, 이서의 이복동생 성호(星湖) 이익(李瀷, 1681~1763)은 실학자로 유명하다.","a":"이하진 필적 천금물전","c":"보물","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616193.jpg"},{"q":"정토사터에 전하고 있던 비(碑)로, 신라말·고려초의 승려 법경대사를 기리기 위해 세운 것이다. 정토사는 신라말에서 고려초에 창건된 것으로 추정되며, 법경대사가 이 절의 주지가 되어 많은 제자들을 양성하다가 태조 24년(941)에 입적하자, 그의 뒤를 이어 홍법대사가 후학들을 지도하였다. 비는 전체적으로 보존이 잘 되어 있으며, 당시의 양식을 잘 따르고 있어, 비받침에 새겨진 거북조각이나 머릿돌의 용조각이 사실적으로 표현되어 있다. 머릿돌 앞면의 중앙에는 ‘법경대사’라는 비의 명칭이 새겨져 있고, 비의 몸돌에는 대사의 행적이 자세히 새겨져 있다.","a":"충주 정토사지 법경대사탑비","c":"보물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616963.jpg"},{"q":"○○○○○는 경주 미추왕릉 앞에 있는 무덤들 중 C지구 제3호 무덤에서 출토된, 거북 모양의 몸을 하고 있는 높이 15.1㎝, 길이 17.5㎝, 밑지름 5.5㎝의 토기이다. 머리와 꼬리는 용 모양이고, 토기의 받침대 부분은 나팔형인데, 사각형으로 구멍을 뚫어 놓았다. 등뼈에는 2개의 뾰족한 뿔이 달려 있고, 몸체 부분에는 전후에 하나씩, 좌우에 2개씩의 장식을 길게 늘어뜨렸다. 머리는 S자형으로 높이 들고 있고 목덜미에는 등에서와 같은 뿔이 5개 붙어 있다. 눈은 크게 뜨고 아래·위의 입술이 밖으로 말려 있으며, 혀를 길게 내밀고 있다.","a":"도기 서수형 명기","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621318.jpg"},{"q":"개성 부근의 고려 시대 무덤에서 출토되었다고 전하는 ○○○○로 높이 8.5㎝, 지름 8.1㎝이다. 몸체는 전체적으로 둥근 형태로 뚜껑 부분과 향을 피우는 부분으로 되어 있으며 휘어진 토끼 꼬리 모양의 다리 3개가 부착되어 있다. 산을 겹쳐 놓은 모양을 한 반구형 뚜껑의 정상에는 다각형의 큰 구멍이 있으며, 그 밑에 다시 돌아가면서 7개의 구멍을 배치하여 이를 통하여 연기가 발산되도록 하였다. 유약은 청백색의 ○○ 유약을 두껍게 발랐으며, 투명하고 광택이 난다. 이 ○○는 12세기경에 제작된 것으로 추정되지만 국적과 가마터를 가늠하기가 매우 어렵다.","a":"백자 박산형뚜껑 향로","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2024061710084000.jpg"},{"q":"바위면에 고부조(高浮彫)되어 있는 ○○○○○은 공양천인상이 함께 표현된 독특한 도상의 항마촉지인(降魔觸地印) 여래좌상으로 규모가 크고 조각수법도 양감이 있고 유려하여 한국의 마애불상 중에서는 그 예가 매우 드물고 뛰어난 상으로 평가된다. 본존불의 육계(肉髻)가 뚜렷한 머리는 언뜻 머리칼이 없는 민머리(素髮)처럼 보이나 나발의 흔적이 남아 있으며, 이목구비의 표현이 단정한 얼굴은 살이 찌고 둥글넓적하여 원만한 상이다. 그러나 눈 꼬리가 약간 위로 치켜 올라가고 입을 굳게 다물어 근엄한 인상을 풍긴다.","a":"해남 대흥사 북미륵암 마애여래좌상","c":"국보","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612588.jpg"},{"q":"안채에 적힌 상량문에 따르면 고종 29년(1892)에 지어진 집임을 알 수 있다. 안채와 사랑채는 함께 지은 것으로 보이고, 문간채·곳간채·헛간채는 그 뒤에 따로 건축된 것으로 보인다. 넓은 공터를 지나 동쪽문을 들어서면 오른쪽에 바깥대문채, 그 왼쪽에 사랑채가 있다. 사랑채 앞에는 그리 크지 않은 사랑마당이 마련되어 있다. 바깥대문을 들어서면 사랑채와는 직각 축으로 중문채가 자리를 잡고 있다. 중문채와 사랑채의 사이에는 'ㄱ'자로 담이 둘러져 있어 안마당과의 경계가 되고 있다.","a":"보은 최감찰댁","c":"국가민속문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634001.jpg"},{"q":"○○에서 불국사로 가는 길의 북쪽 구릉자락에 위치한 통일신라시대의 무덤이다. 무덤의 형태는 정사각형이고 흙을 덮어 만든 봉분 아래에는 무덤을 보호하는 의미를 갖는 12지신상이 조각된 둘레돌이 배치되어 있다. 둘레돌을 배치하는 것은 삼국시대 이후부터 내려오는 전통인데, 통일신라시대 ○○지방의 왕릉에서는 12지신상을 조각한 둘레돌을 흔히 볼 수 있다. 이 ○○○은 한변의 길이가 9.5m 높이가 2m이다. 무덤 내부에는 봉분의 남쪽으로 치우쳐 직사각형의 상자형으로 축조된 굴식돌방무덤(횡혈식석실분)이 있다. 시체를 모신 널방(현실)의 동쪽 벽에는 널길(연도)이 나 있다.","a":"경주 구정동 방형분","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627585.jpg"},{"q":"○○○는 세조의 큰 아들인 의경세자(懿敬世子)가 20세의 나이로 요절하자 '덕종'으로 추존하고 넋을 위로하고자 1459년(세조 5) 그의 묘(후에 경릉敬陵으로 추존) 근처에 지은 왕실 원찰(願刹)이다. 창건 당시 명칭은 정인사(正因寺)였으나, 1471년(성종 2) 소혜왕후가 중창한 이후 ○○○로 개명하였으며, 조선시대 동안 서오릉(西五陵: 창릉·경릉·명릉·익릉·홍릉)을 관리하고 왕실을 안녕과 무병장수를 기원하는 사찰로서 기능하였다.","a":"서울 수국사 목조아미타여래좌상 및 복장유물","c":"보물","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614916.jpg"},{"q":"1954년 건립 이 건물은 한국 최초의 민립대학인 ○○○○○의 ○○이다. 1947년에 착공된 이후 한국전쟁으로 건립에 어려움을 겪었지만 전 교직원과 학부모 모두가 온갖 어려움을 무릅쓰고 공사를 추진하여 착공한 지 8년 만에 완공하였다. 건립 당시에는 중앙 5개의 박공지붕으로 구성된 건물이었지만 몇 차례 증축을 거치면서 지금은 건물 길이가 약 370m에 이르며 모두 19개의 박공지붕으로 이루어져 있다. 그 독특한 형태로 인하여 ○○를 상징하는 건축물로 평가받고 있다.","a":"광주 조선대학교 본관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667863.jpg"},{"q":"총통은 불씨를 손으로 점화·발사하는 화포(火砲)이다. 천(天)자는 천자문의 첫 자로 만든 순서를 표시하는 기호이다. 총 길이 1.31m, 통신 길이 1.16m, 포구 지름 12.8㎝로써 포 입구 띠를 제외한 마디는 모두 8개이다. 총신 포구 쪽에는 탄약을 장전하는 약실을 향하여 가로로 ‘가정을묘시월천사백구십삼근십냥장양내요동(嘉靖乙卯十月天四百九十三斤十兩匠梁內了同)’이라는 글이 음각 되어 있어, 조선 명종 10년(1555)에 만들었음을 알 수 있다.","a":"천자총통","c":"보물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613552.jpg"},{"q":"「○○○○○」은 ○○ 풍산김씨 11세손 ○○○ 김양진(1467∼1535)의 ○○으로, 1576년(선조 10) 산음현감(山陰縣監)을 지낸 유연당 김대현(1553∼1602)이 ○○ 풍산김씨 영감댁(경상북도 민속문화유산)에서 이곳으로 이전한 것으로 전해지고 있다. 당초 집은 임진왜란 때 소실되었고, 현재 ○○은 김대현의 아들 김봉조(1571∼1630)가 다시 지었으며, 서편의 큰 사랑채는 1614년(광해군 6)에 건립하였다. ○○○이 있는 마을은 태백산의 지맥(地脈)인 동쪽의 아미산과 서쪽의 도인산, 안산(案山)인 남쪽의 검무산, 배산(背山)인 죽자봉의 가운데에 위치한다.","a":"안동 허백당 종택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2673546.jpg"},{"q":"신라 47대 ○○○의 무덤이다. ○○○은 본명이 김의정으로, 45대 신무왕의 이복동생이다. 재위기간 동안 특별한 치적은 없으나 제방을 수리하는 등 농사를 장려하는데 힘썼다. 『삼국사기』에 의하면 861년 1월에 왕이 죽자 시호를 헌안(憲安)이라 하고 공작지(孔雀趾)에 장사지냈다고 하였으나 공작지의 위치는 알 수 없다. 무덤의 형태는 가장 단순한 형식의 무덤으로 높이 4.3m, 지름 15.3m의 원형 봉토분이다. 밑둘레에는 자연석을 이용하여 둘레돌을 둘렀으나, 현재 몇 개만이 남아 있다. 내부는 굴식돌방무덤(횡혈식석실묘)으로 추정된다.","a":"경주 헌안왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627787.jpg"},{"q":"1913년 무렵 건립 이 건물은 현지인을 교회 지도자로 양성하기 위해 미국 남장로교 선교사 프레스턴이 설립한 보통성경학원으로, 현재 1층은 병원으로, 2층은 당시 재정 후원자였던 ○○○○의 ○○○으로 사용되고 있다. 지붕은 박공지붕의 양쪽 끝 부분이 약간 꺾인 맨사드 형태에 지붕창이 전후에 하나씩 나있으며, 외벽 층간에는 돌림띠를 두었다. ○○ 지역의 선교 활동을 위해 지은 건물로 현재까지 거의 완벽하게 건립 당시의 모습을 유지하고 있다.","a":"순천 구 남장로교회 조지와츠 기념관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668928.jpg"},{"q":"조선 전기 청백리로 유명한 고불 맹사성(1360∼1438) 가족이 살던 집으로, 원래 고려 후기에 최영 장군이 지은 집이라고 전하기도 한다. 맹사성은 고려말 · 조선초의 문신으로, 최영 장군의 손주사위이다. 고려 우왕 12년(1386) 문과에 급제하여 춘추관검열, 전의시승 등을 지내고 조선 태조 때에는 예조의랑, 이조참의, 예문관대제학, 우의정의 벼슬을 했다. 사람됨이 소탈하고 조용하며, 효성이 지극하였으나, 조정의 중요한 일을 의논할 때는 과감하게 일을 처리하였다.","a":"아산 맹씨 행단","c":"사적","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626524.jpg"},{"q":"ㅇ○○○○○은 1961년 대건신학교의 본관(사무실, 도서관, 교실) 및 헨리관(기숙사), 식당의 용도로 건립된 시설로서 호주 출신 신부(미상)에 의해 설계되었으며 지하층을 통해 유기적으로 서로 연결되어 있는 것이 특징적이다. 대건신학교는 이후 ‘광주가톨릭대학교’ 및 ‘광주가톨릭대학교 부설 평생교육원’, ‘광주가톨릭평생교육원’을 거쳐 2014년 8월 11일부터 현재까지 ‘○○○○○’으로 사용 중에 있다.","a":"천주교 광주대교구청 식당동","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018121712374800.jpg"},{"q":"1929년 건립한 이 건물은 ○○○ 교인 및 지부의 업무를 총괄 집행하는 곳이다. 일제 강점기 말기에는 공립학교 교실로, 광복 후에는 태극지하종교연합회 사무실로, 한국전쟁 당시에는 인민군 여단사령부로 사용되었다. 중앙 1칸의 한옥 지붕을 가진 현관과 상·중·하인방이 뚜렷이 구분되는 벽면이 특징적이며, 수막새에는 ‘수(水)’자를 형상화하여 조각하였고, 암막새에는 ○○○를 상징하는 ‘궁을도형(弓乙圖形)’ 무늬가 새겨져 있다.","a":"대전 수운교 본부사무실","c":"국가등록문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667987.jpg"},{"q":"충남 ○○○○○에 전해지는 사경(寫經)이다. 사경이란 불경의 내용을 정성스럽게 옮겨 적고, 화려하게 장식하여 꾸민 것을 말한다. 백지에 먹으로 쓴 ‘부모은중경’과 ‘장수멸죄호제동자다라니경’으로 병풍처럼 펼쳐서 볼 수 있는 형태이다. 부모은중경은 부모의 은혜를 크게 10가지로 나누어 설명하고 은혜를 갚기 위해 공양하며 경전을 읽고 외울 것을 권장하고 있다. 다른 경전과 달리 각 내용에 따른 그림이 그려져 있는 것이 특징이다. 장수멸죄호제동자다라니경은 부처의 힘을 빌리거나 수행을 통해 모든 죄악을 없애고 장수하는 법에 대한 가르침이다.","a":"천안 광덕사 조선사경","c":"보물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618017.jpg"},{"q":"1930년대에 건립된 것으로 추정되는 튼 ‘ㅁ’자 평면의 전형적인 경기지방 한옥양식 주택이다. 혜곡(兮谷) ○○○가 1976년부터 1984년까지 거주한 주택으로, 안채는 사랑방, 안방, 대청, 건넌방이 있고, 바깥채는 현재 전시실과 사무실로 쓰이고 있다.","a":"서울 성북동 최순우 가옥","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667070.jpg"},{"q":"○○○○○은 청동 불상 표면에 도금한 높이 38.2㎝의 불상으로 국립중앙박물관에 소장되어 있다. 머리 위에는 작은 소라 모양의 머리칼을 붙여 놓았으며 정수리 부근에는 상투 모양의 머리(육계)가 솟아있다. 얼굴은 원만하고 눈은 감고 입을 오므리면서 미소를 짓고 있는 듯하여 보는 이에게 감동을 준다. 꾸밈없는 미소를 띤 얼굴은 삼국시대 불상양식의 특징을 반영한 것으로 이 불상의 격을 높여주고 있다. 아랫배를 조금 내밀고 서 있는 신체는 부드러우면서도 자유로운 자세를 취하고 있다.","a":"금동여래입상(1963)","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613244.jpg"},{"q":"2단의 기단(基壇)위에 3층의 탑신(塔身)을 올린 석탑으로, 각 부분의 장식이 풍부하다. 아래층 기단의 4면에는 가운데에 기둥 모양의 조각을 하나씩 새기고, 조각에 의해 나누어진 8곳에 비천상(飛天像)을 도드라지게 조각하였다. 위층 기단에도 각 4면의 가운데에 기둥 모양을 새긴 후, 기둥을 중심으로 왼쪽에는 4천왕상(四天王像)을, 오른쪽에는 천부상(天部像)을 배치하였다. 사천왕과 천부상은 모두 부처의 법을 보호하고 지키는 신으로 이들을 이렇게 복합적으로 표현한 것은 보기 드문 모습인데, 이는 통일신라 후기에 가져온 변화인 듯 하다.","a":"의성 관덕리 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620487.jpg"},{"q":"40여 년간 한센인들에 대한 적극적인 의료 봉사활동을 하였던 ○○○○○이 거주했던 벽돌조 주택으로, 한센인들이 겪었던 아픔을 함께 나누었던 ○○○○○의 희생과 봉사의 상징적인 주택으로 역사적 가치가 있음","a":"고흥 소록도 마리안느와 마가렛 사택","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2016101920124300.JPG"},{"q":"○○○○○에 보존되어 있는 그림으로 비로자나불·노사나불·석가모니불 등 삼신불을 그린 탱화이다. 이 ○○○○은 3폭으로 되어 있는데, 중앙의 비로자나불탱을 중심으로 왼쪽에는 노사나불탱, 오른쪽에는 석가모니불탱을 각 한 폭씩 그렸다. 법신(法身)인 비로자나불도는 화면 중앙 상단의 본존불을 중심으로 좌우협시인 문수·보현보살과 8대보살, 4위의 타방불과 6위의 제불, 사자와 코끼리 탈을 쓴 성중(호계대신(護戒大神), 복덕대신(福德大神))들이 에워싸듯 배치되어 대칭을 이루고 있다.","a":"화엄사 대웅전 삼신불탱","c":"보물","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619848.jpg"},{"q":"○○은 ○○ 김씨의 시조인 김알지가 태어난 곳이라는 전설을 간직한 숲이다. 원래 신라를 건국할 때부터 있던 숲으로, 시림(始林)이라고 하던 것을 알지가 태어난 뒤로 ○○이라 하였다. 탈해왕 4년(60)에 왕이 금성 서쪽 시림 숲 사이에서 닭 우는 소리가 들리고 온통 환한 빛으로 가득하여, 날이 밝은 후 신하를 보내어 살피도록 하였다. 신하가 시림에 이르러 보니 금으로 된 조그만 궤짝이 나뭇가지에 걸려있고 흰 닭이 그 아래에 울고 있어 돌아와 고하니, 왕이 즉시 시림으로 가서 궤짝을 열어 보았다.","a":"경주 계림","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627546.jpg"},{"q":"조선 중기의 문신 정온(1569∼1641)이 태어난 집으로, 후손들이 순조 20년(1820)에 다시 짓고 정온의 신위를 사당에 모셔 오늘에 이르고 있다. 솟을대문의 대문간채를 들어서면 'ㄱ'자형의 사랑채가 있고, 사랑채 안쪽으로 '一'자형의 안채가 자리하였다. 안채의 오른쪽에는 뜰아래채가, 왼쪽에는 곳간채가 있다. 안채의 뒷쪽에 따로 담장을 두르고 3문을 설치한 후 사당을 세웠다. 사랑채는 꺾인 부분을 누마루로 꾸미고 눈썹지붕을 설치한 점이 특이하다.","a":"거창 동계종택","c":"국가민속문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635900.jpg"},{"q":"경상북도 ○○군 ○○읍 동본동 3층석탑과 함께 전해오는 통일신라 후기의 불상으로 하나의 돌에 새겨진 전체 높이 3.46m의 거대한 석조불상이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리 부근에는 상투 모양의 머리(육계)가 큼직하게 표현되었다. 원만한 얼굴에는 길다란 눈, 짧은 코, 적당한 입이 적절하게 표현되어 부드러운 곡선의 얼굴과 함께 자비롭고 온화한 미소를 실감나게 나타내고 있다. 큰 얼굴에 비하여 작아진 상체는 굵고 짧은 목과 좁은 어깨, 짧은 팔 등이 평판적인 가슴과 함께 움츠린 듯하여 다소 위축된 느낌을 준다.","a":"예천 동본리 석조여래입상","c":"보물","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620901.jpg"},{"q":"권곤(1427∼1502)의 묘 아래에 있는 재사로, 일명 ‘추원재’라고도 한다. 조선 영조 51년(1775)에 처음 지었고 순조 30년(1830)에 이곳으로 옮겨지었다. 안채의 대들보에 건물의 창건과 이건에 대한 기록이 있어 그 유래를 명확히 알 수 있다. ‘○○○○’라는 집 이름은 이 지역의 지명을 따른 것이다. '一'자형 안채와 'ㄷ'자형 아래채가 마주하여 튼 'ㅁ'자형을 이루었으며 트인 부분은 담장을 쌓아서 연결하였다. 아래채의 왼쪽 끝에는 '주사'라 불리는 '一'자형 건물이 이어져 있다. 안채의 가운데 6칸은 대청이고 양끝 2칸씩은 온돌방이다.","a":"안동 안동권씨 소등재사","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635580.jpg"},{"q":"천등산 기슭에 있는 ○○○는 신문왕 2년(682) 의상대사가 지었다고 한다. 부석사를 세운 의상대사가 부석사에서 종이로 만든 봉황새를 날려 보냈는데, 그 새가 내려앉은 자리에 절을 짓고 ○○○라 이름지었다는 전설이 전한다. 이 건물은 극락전 앞에 동향(東向)으로 서 있으며 원래 불상을 모시는 부속 건물이었을 것으로 생각되지만 지금은 승려가 기거하는 방으로 사용하고 있다. 1969년 해체·복원공사 당시 발견한 기록에 광해군 8년(1616)에 고쳐 지은 것을 알 수 있을 뿐 확실하게 언제 세웠는지 알 수 없다.","a":"안동 봉정사 고금당","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620967.jpg"},{"q":"1931년 건립된 이 건물은 1921년에 개교한 ○○서방공립보통학교 건물로 지어져 지금은 ○○○○○의 ○○으로 사용되고 있다. 1층과 2층 사이 벽체에는 벽돌 쌓기 방법을 달리하여 건물 입면에 변화를 주었고, 지붕에는 채광 및 환기를 위한 지붕창을 설치하여 지붕 뼈대가 썩는 것을 막고 있다. ○○ 지역에서 일제 강점기에 건립된 초등학교 건물 가운데 남아 있는 것이 드물어 보존 가치가 높은 건물이다.","a":"광주 수창초등학교 본관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667865.jpg"},{"q":"○○○○는 순조(純祖)의 3녀로 순조 5년(1822) 6월 10일에 출생하여 헌종 3년(1837) 16세 되던 해 남영위(南寧尉) 윤의선(尹宜善)에게 하가하였다. 헌종 10년(1844) 5월 헌종 계비 간택에 참여하였다가 드신 음식이 잘못되어 당시 수태중이던 아기와 함께 궁중에서 돌아가셨다고 한다. 공주가 생전에 사용하였던 유물들은 윤용구 딸 윤백영(尹佰榮) 여사가 보관해 오다가 1960년대부터 여러 차례로 나누어져 석주선(1911~1996)교수에게 기증하였다. 현재 이 유물은 현재 단국대학교 석주선기념박물관에 소장되어 있다.","a":"덕온공주 의복","c":"국가민속문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633348.jpg"},{"q":"국내에 남아있는 고려시대 종 가운데 가장 큰 종으로서 종의 높이 1.33m, 종의 구경은 입구 0.96m이다. 종 위에는 종의 고리 역할을 하는 용뉴가 여의주를 물고 있는 용의 모습으로 표현되었는데, 신라 종의 용보다 고개를 쳐 들어 올린 모습을 하고 있다. 용뉴 뒤에 붙은 음통은 대나무 모양이며, 편평한 부분인 천판 가장자리에는 연꽃무늬를 돌렸다. 몸체의 아래와 위에는 구슬무늬로 테두리를 한 너비 10㎝ 정도의 띠를 두르고, 꽃과 덩굴로 안을 채워 넣었다.","a":"성거산 천흥사명 동종","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611912.jpg"},{"q":"○○○○○은 아라가야의 전성기인 5~6세기에 축조된 국가적인 중요 시설물로 추정되는 토성과 건물지 등이 분포하는 유적으로, 아라가야 지배층의 실체를 규명할 수 있는 중요한 유적이며, ○○지역 가야의 실체를 밝힐 수 있는 역사적·학술적 가치가 높은 유적임","a":"함안 가야리 유적","c":"사적","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2019102020555300.JPG"},{"q":"남한강의 아름다운 경관과 잘 어우러져 있는 통일신라시대의 석탑으로, 당시에 세워진 석탑 중 가장 규모가 크며, 우리나라의 중앙부에 위치한다고 해서 중앙탑(中央塔)이라고도 부르는 이 탑은 2단의 기단(基壇) 위에 7층의 탑신(塔身)을 올린 모습이다. 높은 탑신을 받치기 위해 넓게 시작되는 기단은 각 면마다 여러 개의 기둥 모양을 새겨 놓았고, 탑신부의 각 층 몸돌 역시 모서리마다 기둥 모양의 조각을 두었다. 몸돌을 덮고 있는 지붕돌은 네 귀퉁이 끝이 경쾌하게 치켜올려 있어 자칫 무겁게 보일 수 있는 탑에 활기를 주고 있으며, 밑면에는 5단씩의 받침을 새겨 놓았다.","a":"충주 탑평리 칠층석탑","c":"국보","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612144.jpg"},{"q":"고려 후기 문신인 ○○○의 ○○화로 가로 42.1㎝, 세로 53.7㎝이다. ○○○은 어릴적부터 원나라에서 살아 원나라 황제의 총애를 받기도 하였으며 고려에 돌아와 여러 왕들의 신임을 받으며 문하시중(門下侍中)까지 올랐다. 이 ○○화는 머리에 평정건을 쓰고 오른쪽을 바라보는 모습으로 안면은 회색빛을 띠며, 눈썹과 모발, 수염은 흑·백의 가는 선을 이용하여 묘사하였다. 눈시울은 붉은색으로 명암을 넣었고, 눈꺼풀은 가는 먹선으로 처리한 후 속눈썹을 일일이 그렸다. 옷은 연보라색 바탕에 보라색 선으로 덩굴무늬가 그려져 있다.","a":"염제신 초상","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619512.jpg"},{"q":"1926년 ○○○○○으로 건립하여 현재 ○○○○○ 본관으로 사용하고 있는 지상 4층(지붕층 포함) 건물로, 1977년 대규모로 개.보수가 있었으나 본래의 의장 특징을 그대로 유지하고 있는 등 원형의 보존 상태가 비교적 양호하다. 실내공간을 밝게하기 위해 창호를 넓게 구성하고 이를 위해 철근콘크리트 상인방(上引防)을 사용하는 등 건립 당시의 건축적 특징을 잘 보여주고 있으며, 과학관과 더불어 우리나라 근대시기 교육시설로서의 보존.활용 가치가 있어 등록하였다.","a":"서울 배화여자고등학교 캠벨기념관","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017010916415900.JPG"},{"q":"○○○ 정상에서 남쪽으로 작은 계곡을 둘러싸고 있는 산성으로 흙과 돌을 사용하여 쌓았으며, ○○○○ 또는 보덕성(報德城)이라고도 한다. 성을 쌓은 시기는 이곳에서 발견되는 유물들을 볼 때 6세기 후반에서 7세기 전반으로 추정하고 있다. 현재는 남문이 있던 자리와 성문 밑으로 개울물이 흐르도록 했던 수구자리, 그리고 건물이 있었던 자리가 남아있다. 전해지는 자료에 의하면, 보덕성이라는 이름은 보덕국(報德國)의 왕 안승(安勝)이 670년 ○○에 자리잡은 뒤 684년까지 세운 보덕국의 소재지였기 때문에 붙여졌다고 하는데 확실한 근거는 없다.","a":"익산 오금산성","c":"사적","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626794.jpg"},{"q":"경기도 ○○시 춘궁동에 있는 5층 석탑으로 2단의 기단(基檀) 위에 5층의 탑신(塔身)을 올린 모습이다. 기단의 네 모서리와 면의 가운데에 기둥 모양을 새겨두었는데, 남쪽 면이 부서져 있어 그 안쪽으로 커다란 기둥돌이 들여다 보인다. 이 탑의 특징은 탑신부에서 드러난다. 첫층 몸돌이 2단인데, 아랫단을 4개의 네모난 돌로 두고, 그 위에 1장의 돌을 얹어놓았다. 이러한 예는 (전)광주 성거사지 ○○○○에서도 볼 수 있는데, 고려시대에 나타난 새로운 양식이다. 지붕돌을 구성하는 돌 역시 1∼3층은 4장, 4층은 2장, 5층은 1장이다.","a":"하남 동사지 오층석탑","c":"보물","nc":"","r":"경기도","s":"하남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615631.jpg"},{"q":"○○○○이란 공이 큰 신하에게 왕의 명을 받아 공신도감에서 발급해주던 문서를 말한다. 이 「○○○○○록권」은 태조 4년(1395)에 이성계의 조선건국에 공로가 있는 ○○○에게 공신도감에서 발급한 ○○○○이다. 문서에 기록된 인원은 총 695명이며, 필사본으로 기재된 이 문서는 1989년 지정된 국보 이원길 ○○○○○록권과 동일한 내용으로 인명의 수와 발급내용이 같다. 다만 국보 이원길 ○○○○○록권은 목판과 활자를 같이 써 간행된 것으로 이원길에게 발급된 것이다. 이 문서에는 한 변의 길이 6.5㎝의 ‘이조지인(吏曹之印)’이라는 도장이 45군데에 찍혀있다.","a":"김천리 개국원종공신녹권","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614469.jpg"},{"q":"○○○는 통일신라 성덕왕 21년(722) 대비화상과 삼법화상이 세워 옥천사라 불렀다고 하며 정강왕(재위 886∼887)이 두 개의 계곡이 만나는 절 주변의 지형을 보고 ○○○로 고쳤다고 한다. 임진왜란 때 절이 불에 탔던 것을 벽암대사가 인조 10년(1632) 다시 고쳐 세워 오늘에 이르고 있다. 절의 중심 법당으로 석가모니 불상을 모신 ○○○은 이 때에 다시 지은 건물로 짐작한다. 규모는 앞면 5칸·옆면 3칸이고 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위뿐만 아니라 기둥 사이에도 있다.","a":"하동 쌍계사 대웅전","c":"보물","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622737.jpg"},{"q":"불상이 앉아있는 대좌(臺座)와 몸 전체에서 나오는 빛을 형상화한 광배(光背)가 모두 갖춰진 완전한 형태의 불상으로, 진리의 세계를 두루 통솔한다는 의미를 지닌 비로자나불을 표현한 것이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위의 상투 모양 머리(육계)는 펑퍼짐하여 구분하기 어렵다. 오른쪽 어깨를 드러내고 왼쪽 어깨에만 걸쳐 입은 옷에는 옷주름이 간략하게 표현되었는데, 특히 다리부분의 옷주름이 극단적으로 형식화되었다. 이런 표현은 얼굴모습과 함께 장곡사 철조비로자나불좌상(보물)과 직결되는 것이다.","a":"괴산 각연사 석조비로자나불좌상","c":"보물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617036.jpg"},{"q":"조선후기 문신인 근암 ○○의 영정으로 사모(紗帽)와 흑단령(黑團領)을 착용하고 표피를 깐 교의자(交椅子)에 반우향(半右向)으로 앉은 뒤 공수(拱手)하고 있는 전신상이다. 쌍학흉배(雙鶴胸背)와 서대(犀帶)를 하고 있는 점을 고려할 때, ○○이 판의금부사(判義禁府事)를 지내 1품에 오른 영조 38년(1762)의 66세 무렵에 그린 것으로 생각된다. 그런데 오세창의 『근역서화징(槿域書畵徵)』에 변상벽(卞相璧)이 ○○의 ○○화를 그렸다는 “화재화정(和齋畵幀)”의 기록이 인용되고 있어, 동 ○○이 당대 최고의 어진화사(御眞畵師)였던 변상벽이 그린 것임을 짐작할 수 있다.","a":"윤급 초상","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614880.jpg"},{"q":"속리산 기슭에 있는 ○○○는 신라 진흥왕 14년(553)에 처음 지었고, 혜공왕 12년(776)에 다시 지었다. 임진왜란으로 모두 불탄 것을 인조 2년(1624)에 벽암이 다시 지었으며 그 뒤 여러 차례 수리를 거쳐 오늘에 이르고 있다. 대웅전은 앞면 7칸·옆면 4칸 규모의 2층 건물로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식이다.","a":"보은 법주사 대웅보전","c":"보물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617131.jpg"},{"q":"○○○○○에 있는 높이 40ｍ의 단독 원형 구릉 정상부에 있는 3개의 무덤이다. 1951년 동검, 말방울을 비롯한 철제품이 수습·보고된 후, 1982년 국립○○박물관에서 발굴하였다. 내부시설은 구덩이를 파 그 안에 나무널을 넣은 덧널시설이 있는 덧널무덤(토광목곽묘)이다. 제1무덤은 구릉경사면에 있으며, 제2무덤과 제3무덤은 구릉정상부에 있는 부부 합장무덤으로 추정된다. 제1무덤에서는 와질토기와 도질토기가 출토되었다. 길이 6ｍ, 너비 1.2ｍ의 제2무덤은 화로형토기와 대형철투겁창(철모)25점, 도질토기가 나왔다.","a":"경주 구정동 고분군","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627931.jpg"},{"q":"○○는 조선왕조 역대 임금의 신위를 모신 곳으로, ○○은 ○○의 중심 건물로 영녕전과 구분하여 태묘(太廟)라 부르기도 한다. ○○은 조선시대 초 태조 이성계의 4대조(목조, 익조, 도조, 환조) 신위를 모셨으나, 그 후 당시 재위하던 왕의 4대조(고조, 증조, 조부, 부)와 조선시대 역대 왕 가운데 공덕이 있는 왕과 왕비의 신주를 모시고 제사하는 곳이 되었다. ○○는 토지와 곡식의 신에게 제사지내는 사직단과 함께 국가에서 가장 중요시한 제례 공간으로, 그 건축 양식은 최고의 격식을 갖춘다.","a":"종묘 정전","c":"국보","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611766.jpg"},{"q":"공주시 ○○○릉 왕비의 나무널(목관)내 왼쪽 팔 부근에서 발견된 한 쌍의 은제 팔찌로, 바깥지름 8㎝, 고리지름 1.1㎝이다. 팔목이 닿는 안쪽에는 톱니 모양을 촘촘히 새겼고, 둥근 바깥면에는 발이 셋 달린 2마리의 용을 새겼다. 팔찌의 외관을 깜싸고 있는 용의 조각은 세밀하지는 않으나 힘이 넘치게 표현되어 있다. 한 개의 팔찌 안쪽에 새긴 명문에 의하면 왕비가 죽기 6년 전에 만들어진 것으로 보이며, 만든 사람의 이름과 무게 등이 기록되어 가치가 높다.","a":"무령왕비 은팔찌","c":"국보","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612283.jpg"},{"q":"○○은 물·술·간장·오줌 따위를 담는 그릇의 하나로, 크기가 작은 것은 물이나 술 따위를 넣고 큰 것에는 오줌을 담아 지게로 운반할 때 사용하였다. 길이 34.5㎝, 측면 지름 15.4㎝, 아가리 지름 5.3㎝로 비교적 큰 크기의 ○○이다. 긴 타원형 몸통에 한쪽 면은 둥글고, 다른 면은 편평하다. 몸통 윗면 중앙에 작은 아가리를 달았는데 손상이 많다. 전면에 두터운 백토 칠을 고르게 한 뒤, 음각으로 선무늬를 나타내는 조화기법과 무늬의 배경을 긁어내 무늬만을 남게 하는 박지기법으로 장식하였다. 아가리 주위에는 좌우 사각형 안에 큼직한 꽃잎무늬를 한 개씩 넣었다.","a":"분청사기 박지모란문 장군","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614453.jpg"},{"q":"○○○은 1867년 ○○○을 다시 지으면서 자미당 터에 고종의 양어머니인 조대비(신정왕후)를 위해 지은 대비전으로서 중건 이후 화재로 소실됨에 따라서 고종 25년(1888)에 다시 지어 오늘에 이른다. ○○○은 대비가 일상생활을 하는 침전 건물로, 총 44칸 규모이다. 겨울에 따뜻하게 지낼 수 있도록 서북쪽에 복안당이라는 침실을 두고 중앙에는 중심 건물인 ○○○을 두었다. 또, 동남쪽에는 다락집인 청연루를 두어 여름을 시원하게 보낼 수 있도록 하였다. 주변에는 수십 개의 집과 담장, 문들이 있었으나 일제강점기를 거치면서 대부분 없어졌다.","a":"경복궁 자경전","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613927.jpg"},{"q":"○○○는 통일신라 경덕왕 10년(751) 김대성의 발원에 의해 창건된 사찰로, 과거·현재·미래의 부처가 사는 정토(淨土), 즉 이상향을 구현하고자 했던 신라인들의 정신세계가 잘 드러나 있는 곳이다. 『삼국유사』에는 김대성이 전생의 부모를 위해서 석굴암을, 현생의 부모를 위해서 ○○○를 지었다고 전해진다. 그러나 혜공왕 10년(774) 12월 그가 목숨을 다할 때까지 짓지 못하여, 그 후 나라에서 완성한 후 나라의 복을 비는 절로 삼게 되었다. ○○○○○과 ○○○○○ 다보탑(국보)은 절의 대웅전 앞 뜰 동서쪽에 각각 세워져 있는데, 서쪽탑이 ○○○○이다.","a":"경주 불국사 삼층석탑","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612682.jpg"},{"q":"이 시설물은 경원선을 운행하던 증기기관차에 물을 공급하기 위해 설치한 ○○○으로, 현재 상자형과 원통형 2기가 남아 있다. 상자형 ○○○은 콘크리트조로 기단, 벽체부, 지붕부 3단으로 입면을 형성하였으며, 아치형 출입구를 두었고, 외관에 줄눈을 그려 조적조인 것처럼 구성하였다. 원통형 ○○○에는 급수관 3개와 기계장치가 양호하게 보존되어 있고, 탑 외부에는 한국전쟁 당시의 총탄 흔적이 남아 있다. 1950년대 디젤기관차가 등장하여 제 기능을 다하고 사라졌지만, 근대화 과정에서 중요한 역할을 한 증기기관차 관련 철도 시설물로 가치가 높다.","a":"연천역 급수탑","c":"국가등록문화유산","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668053.jpg"},{"q":"○○ 보문단지 ○○월드 맞은편 논 한가운데 있으며, 보물로 지정된 통일신라시대의 3층석탑 2기가 서 있다. 절의 이름과 처음 지어진 연대는 알 수 없으나 석탑이 신라의 전형적인 양식을 따르고 있으므로 통일신라시대의 사찰로 추정하고 있다. 2기의 탑은 규모와 형식이 같으며, 서쪽에 있는 탑의 보존상태가 좀 더 양호하다. 발굴결과 확인이 된 건물자리는 금당(법당)·강당·중문 들이며, 기둥과 기둥사이를 1칸으로 볼 때 금당은 앞면·옆면 모두 5칸, 강당은 앞면 8칸·옆면 3칸, 중문은 앞면 3칸·옆면 2칸의 건물이었음이 밝혀졌다.","a":"경주 천군동 사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627695.jpg"},{"q":"○○○○○유적은 마한의 도읍지설, 백제 무왕의 천도설이나 별도설, 안승의 보덕국설, 후백제 견훤의 도읍설이 전해지는 유적이다. 발굴조사 결과, 이 유적은 적어도 세 시기(백제 후기~통일신라 후기)를 지나면서 만들어진 것으로 생각하고 있다. 석탑 동쪽으로 30m 지점에서 통일신라시대 것으로 보이는 기와 가마 2기를 발견했다. 특히 탑을 에워싼 주변의 구릉지를 중심으로 직사각형 모양의 석축 유물을 찾았다. 이 지역 안에는 고려시대에 조성된 사찰의 유물인 ○○○ 5층 석탑이 있다. ※(○○○○○ → ○○○○○)으로 명칭변경 되었습니다.(2011.07.28 고시)","a":"익산 왕궁리 유적","c":"사적","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626968.jpg"},{"q":"감은사터 넓은 앞뜰에 나란히 서 있는 쌍탑이다. 2단의 기단(基壇)위에 3층 탑신(塔身)을 올린 모습으로, 서로 같은 규모와 양식을 하고 있으며, 옛신라의 1탑 중심에서 삼국통일 직후 석탑으로 조성된 쌍탑가람으로는 최초의 배치를 보이고 있다. 감은사는 삼국을 통일한 문무왕이 새 나라의 위엄을 세우고, 당시 틈만 나면 동해로 쳐들어 오던 왜구를 부처의 힘으로 막아내어 나라의 안정을 도모하고자 세운 절로, 동해 바닷가인 이 곳에 터를 잡았다. 문무왕은 생전에 절이 완성되는 것을 보지 못하고, 그 아들인 신문왕이 아버지의 뜻을 이어받아 즉위 이듬해인 682년에 완공하였다.","a":"경주 감은사지 동·서 삼층석탑","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612826.jpg"},{"q":"고려시대 만들어진 종으로 1967년 경기도 ○○군 금사면 상품리에서 우연히 발견된 것으로, 크기는 길이 84㎝, 입지름 55㎝이다. 종을 매다는 고리인 용뉴는 한마리의 용이 고개를 들고 있는 모습이며, 소리의 울림을 돕는 용통은 6단의 마디로 구획하였고, 용통의 각 부분마다 덩굴무늬를 양각하였다. 종의 상단과 하단, 9개의 돌출된 모양의 연뢰를 둘러싼 사각형의 연곽에는 가늘게 연이은 구슬 모양의 띠를 돌리고, 그 내부에 모란 덩굴무늬를 장식하였다. 연곽내의 연뢰는 꽃으로 도드라지게 표현하였다.","a":"여주 출토 동종","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614649.jpg"},{"q":"○○ 전동성당 건축에 참여했던 ○○○ 벽돌공들이 정착하는 과정에서 지은 비단을 팔던 상점 건축으로 1920년대에 건축되었다. 상점 2개가 연속된 형태이며, 각각의 상점 출입구 상부에는 형태가 같은 작은 삼각형 박공을 두어 정면성을 강조하는 등 중국 상해의 전통적인 비단상점 형태를 따라 지었다.","a":"전주 다가동 구 중국인 포목상점","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668715.jpg"},{"q":"○○○○○는 개항기에서 일제강점기 동안 ○○항에서 조운업(하역업)을 하던 하역회사 ○○○ 건물로 근대 일본 점포겸용주택의 하나인 정가(町家, 마찌야) 유형의 건물이다. ○○ 일본조계지에 현존하는 유일한 정가 양식 건물로써 건축사적인 가치가 높을 뿐 아니라, 일제강점기 하역노동자의 노동력착취의 현장으로써 역사적 가치가 크다.","a":"인천 구 대화조 사무소","c":"국가등록문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667845.jpg"},{"q":"○○시로 진입하는 옛도로의 북쪽에 동·서로 서 있는 한 쌍의 돌장승이다. 이 지역에서는 장승을 ○○라고 부르는데, 좌수영 시절(조선시대 수군이 주둔하여 있던 때) 서문으로 통하는 길목에 위치하는 것으로 보아 마을의 수호신 역할을 한 듯 하다. 서로 마주하고 있는 동쪽 ○○에는 ‘남정중(南正重)’, 서쪽 ○○에는 ‘화정려(火正黎)’라는 글씨가 있다. 동쪽에 있는 남자○○는 모자를 쓰고 위로 올라간 눈썹에 달걀형의 눈과 길고 큰 자루병코를 가지고 있다.","a":"여수 연등동 벅수","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634709.jpg"},{"q":"작은 초가집으로 대문을 들어서면 북쪽으로 안채가 있고 서쪽으로 돼지막이 있다. 안채는 온돌방 2개와 큰 부엌으로 구성되어 있는 남향집이다. 방문은 큰방·작은방의 크기가 다르며, 큰방의 문 옆에는 머릿창이 하나 더 달려있다. 이것은 남해안 지방에서 자주 볼 수 있는 구조이다. 방문 앞에는 크기나 형태가 맞지 않는 미묘한 모습의 뜰마루가 있다. 부엌은 뒷벽을 뒤 퇴칸의 기둥을 따라 쳤기 때문에 한결 넓어졌다. 그리고 벽의 윗부분에 뚫어 놓은 살창으로 빛이 들어와 비교적 밝은 편이다. 부엌의 동쪽 마당에는 장독대가 있고 나머지의 넓은 터는 채소밭이다.","a":"순천 낙안읍성 들마루집","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634580.jpg"},{"q":"○○ 나성과 능산리 무덤들 사이 절터 서쪽의 한 구덩이에서 450여점의 유물과 함께 발견된 ○○의 향로이다. 높이 64㎝, 무게 11.8㎏이나 되는 대형 향로로, 크게 몸체와 뚜껑으로 구분되며 위에 부착한 봉황과 받침대를 포함하면 4부분으로 구성된다. 뚜껑에는 23개의 산들이 4∼5겹으로 첩첩산중을 이루는 풍경을 보여주고 있다. 피리와 소비파, 현금, 북들을 연주하는 5인의 악사와 각종 무인상, 기마수렵상 등 16인의 인물상과 봉황, 용을 비롯한 상상의 날짐승, 호랑이, 사슴 등 39마리의 현실 세계 동물들이 표현되어 있다.","a":"백제 금동대향로","c":"국보","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612303.jpg"},{"q":"나즈막한 동산이 둘러있는 명당 터에 남북으로 길게 자리잡고 있는 큰집이다. 솟을대문에 적힌 기록에는 \"고종 24년(1887)에 문을 세웠다\"고 적혀 있으나, 안채와 사랑채는 이 문보다 약 50년 전에 지은 것으로 추정된다. 대문은 정면으로 내지않고 북쪽측면으로 내어 언뜻보면 집이 커보이지 않지만 실제로는 50칸이 넘는 큰 규모이다. 대문을 들어서면 바로 사랑마당이며, 마당의 왼쪽으로 길게 줄행랑채가 뻗어있고 오른쪽으로 사랑채가 자리한다. 사랑채 맞은편의 마당끝에는 안채로 통하는 중대문이 있다.","a":"화성 정시영 고택","c":"국가민속문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633718.jpg"},{"q":"○○○○는 전체 25권으로 추정되는데 ○○○○○이 새로 지정됨으로써 현재 18권이 확인된 셈이다. 이 책은 석보상절과 함께 한글창제와 밀접한 관련을 맺고 있고 우리나라 최초의 찬불가(讚佛歌)이며 국역대장경(國譯大藏經)이라 할 정도로 조선 초기 불교경전 연구와 한글 연구의 귀중한 자료이다. 이 책은 현재까지 발견된 「○○○○」 전 25권 중에 아직까지 복본이 없는 유일본이라는 의미를 지니고 있다.","a":"월인석보 권20","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613799.jpg"},{"q":"이 훈련소는 한국전쟁기에 해병 3기생들이 훈련을 받고 해병 4기생과 함께 인천상륙작전에 참전한 역사적인 군사 유적지이다. 병사(兵舍)와 함께 세면장이 남아 있어 당시의 훈련 상황을 이해하는데 중요한 자료적 가치가 있으며, 한국전쟁의 대표적인 상징물로서의 의미가 매우 크다.","a":"제주 구 해병훈련시설","c":"국가등록문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669614.jpg"},{"q":"이 ○○은 조선시대 사육신*의 한 분인 성삼문과 관련된 집으로 성삼문의 외손자인 엄찬이 살았던 집으로 1676년 전까지 성삼문의 위패를 모시고 제사를 지냈다고 전해진다. 병자사화** 당시 성삼문 집안의 남자들이 모두 처형되어 성삼문의 둘째딸(효옥)이 이곳으로 와 부친의 제사를 지내며 일생을 보냈다고 한다. 약간 높은 대지에 경사진 지형을 활용하여 서쪽을 바라보도록 하였는데, 안채를 ’⊓‘자로 놓고, 그 앞에 행랑채를 ’−‘자로 놓아 전체적으로 ’ㅁ‘자형의 모습을 하고 있다.","a":"홍성 노은리 고택","c":"국가민속문화유산","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634418.jpg"},{"q":"1760년(영조 36) 1월부터 1910년(융희 4) 8월까지 조선후기 151년간의 국정에 관한 제반 사항들이 기록되어 있는 일기체의 연대기이다. 『○○○』의 모태가 된 것은 정조(正祖)가 세손(世孫) 시절부터 직접 자신의 언행과 학문을 기록한 일기인 『존현각일기』였다. 정조는 『논어(論語)』에서 증자(曾子)가 말한 “나는 날마다 세 가지 기준을 가지고 스스로에 대해 반성한다”에 깊은 감명을 받아 일찍부터 자신을 반성하는 자료로 삼기 위해 일기를 작성하였다.","a":"일성록","c":"국보","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611615.jpg"},{"q":"조선시대 만들어진 ○○○○○로 높이 23.4㎝, 아가리 지름 10.8㎝, 밑지름 12.3㎝이다. ○○○는 아가리부분을 둥글게 말아 붙였으며, 어깨 부위가 급격히 벌어졌다가 서서히 좁아진 형태이다. 높이에 비해 몸통이 넓어 양감이 느껴진다. 뚜껑은 꽃봉오리 모양의 꼭지에 낮게 층진 모양을 하고 있고, 아가리부분이 도톰하게 되어있다. 전면에 ○○○약을 발랐는데, 고르지 않아 색이 약간 얼룩져있다. 이 ○○○○○는 ○○○나 뚜껑의 형태가 조선 전기의 백자 ○○○와 같다.","a":"청자 유개항아리","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614455.jpg"},{"q":"모악산에 자리한 ○○○는 백제 법왕 2년(600)에 지은 절로 신라 혜공왕 2년(766)에 진표율사가 다시 지었다. ○○○은 정유재란 때 불탄 것을 조선 인조 13년(1635)에 다시 지은 뒤 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 거대한 미륵존불을 모신 법당으로 용화전·산호전·장륙전이라고도 한다. 1층에는 ‘대자보전(大慈寶殿)’, 2층에는 ‘용화지회(龍華之會)’, 3층에는 ‘○○○’이라는 현판이 걸려있다 1층과 2층은 앞면 5칸·옆면 4칸이고, 3층은 앞면 3칸·옆면 2칸 크기로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"김제 금산사 미륵전","c":"국보","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612350.jpg"},{"q":"○○○은 마을을 지키는 수호신으로 ‘당산’ 혹은 ‘벅수’라고도 한다. ○○○○○은 거대한 사각의 자연석 한 면을 장승의 모습으로 다듬었다. 머리는 왼쪽으로 경사지도록 깎여 있고, 다른 장승과는 달리 눈이 작게 조각되어 있다. 세모난 콧날은 끝이 뭉툭하게 잘려져 있는데, 이는 장승의 코가 아들을 낳는데 효험이 있다는 민간신앙에 따라 아들 낳기를 원하는 마을 아낙들이 떼어간 것으로 보인다. 이마와 양 볼에 혹이 불거져 나왔는데, 이마에 새겨진 혹은 불상의 눈썹사이에 있는 백호(白毫)를 연상시킨다. 웃는 듯한 입 사이로 내민 혀의 모습이 소박하고 친근감을 느끼게 해준다.","a":"순창 충신리 석장승","c":"국가민속문화유산","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634528.jpg"},{"q":"삼국시대에 처음 쌓았고, 조선 태종 9년(1409)에 고쳐 쌓은 후 광해군 2년(1610)에 보수공사를 하면서 내성도 함께 만들었다. 광해군 14년(1622)에는 내성 안에 관청을 건립하고 효종 4년(1653)에 성 위의 작은 담(여장)을 수리하면서, 전반적으로 성의 면모를 갖추게 되었다. 외성은 2㎞, 내성은 700ｍ 길이에 돌로 쌓은 산성이다. 동학운동(1894) 때 건물이 많이 불타 없어지고 현재는 동·서·남·북문의 터가 남아 있다. 내성 앞에는 국문영 장군의 비석이 남아 있다.","a":"담양 금성산성","c":"사적","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627159.jpg"},{"q":"이 부도는 ○○○ 입구에 자리한 부도전 내에 있던 것을 ○○○ 진입로에 위치한 ○○○ 박물관으로 이전한 상태이며, ○○○ 주지를 역임한 소요대사(1562∼1649)의 묘탑이다. 화강암으로 만들어진 높이 156cm 규모의 탑으로, 기단부·탑신부·상륜부로 구성되어 있다. 기단부는 8각형으로, 각 면에는 초화무늬가 조각되었는데, 1면에만 거북 동물이 양각되어 있다. 상면에는 아래로 향한 연꽃무늬가 새겨져 있으며, 그 위에는 각형 1단이 탑신부를 받고 있다. 탑신부는 종모양으로 전체적으로는 전통적인 범종의 모습과 같이 하대·유곽·상대·용뉴를 표현하고 있다.","a":"장성 백양사 소요대사탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619806.jpg"},{"q":"○○○○○유물은 통일신라시대의 ○○ 빗장 1점, ○○ 문고리 1점, ○○ 못 2점으로 구성된 출토품이다. 빗장의 길이는 26cm, 문고리 길이 10.5㎝, 못 길이 4.9㎝의 크기이다. ○○ 빗장은 보존 상태가 양호하고 도금도 잘 남아있는데, 이처럼 ○○ 빗장과 문고리 등이 함께 출토된 예는 극히 드문 편으로, 탑과 부도에 새겨진 문짝 장식에서만 볼 수 있었던 통일신라시대의 문짝 형식을 새롭게 밝혀준 귀중한 자료이다. 빗장은 왼쪽 부분에서 분리 접합할 수 있도록 만들었고, 열쇠구멍도 왼쪽 옆에 뚫려 있다. 문고리는 둥글고 고리판 역시 둥글게 만들어져 있다.","a":"금동 자물쇠 일괄","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613901.jpg"},{"q":"○○○○○은 경전을 읽으면서 죄를 참회하는 불교의식집을 말하며, 이를 수행하면 영험을 받을 수 있어 죄가 없어지고 복이 생긴다고 한다. 나아가 죽은 사람의 영혼을 구제하여 극락으로 인도함으로써 고통으로부터 벗어나려는 공덕 기원의 뜻을 담고 있다. 이 책은『○○○○○』이 후대로 내려오면서 착오가 생기고 잘못 전해지자 여러 고승들이 다시 바르게 교정한 것으로, 10권 가운데 권 제9와 10이다. 나무에 새겨 찍어낸 목판본으로 2권이 한 책으로 되어 있다.","a":"상교정본자비도량참법 권9~10(1997)","c":"보물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619571.jpg"},{"q":"낙동강 하류의 넓은 평야를 한눈에 볼 수 있는 분산의 정상에 둘레 약 900m에 걸쳐 돌로 쌓은 산성이다. 처음 쌓은 연대는 확실하지 않으나, 삼국시대였을 것으로 추정된다. 조선 전기에 왜구의 침입을 막기 위하여 박위(朴蔿)가 수리하여 쌓은 뒤, 임진왜란(1592) 때 무너진 것을 고종 8년(1871)에 다시 쌓아 오늘에 이르고 있다. 산 위의 평탄한 지형을 둘러서 그 주위에 남북으로 긴 타원형을 이루도록 쌓았다. 서남부는 험준한 천연 암벽을 그대로 이용하였으며 현재 성벽이 부분적으로 남아있다.","a":"김해 분산성","c":"사적","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628133.jpg"},{"q":"○○○ 전대통령이 살았던 집으로, 고종 7년(1870)에 건립되어 ○○○ 전대통령의 부친 치소(致昭)공이 1910년경 매입한 것이다. ○○○ 전대통령은 7∼8세경에 이곳에 살기 시작하였으며 대통령으로 재직할 당시에도 청와대가 아닌 이곳에서 집무를 하였다. 이 집은 1910년 이후에 박영효 선생이 일본에서 귀국하여 잠시 머물기도 하였다. 서울의 상류민가로서 비교적 넓은 대지 안에 바깥사랑채, 안사랑채, 안채, 대문 및 행랑채, 창고 등을 갖추고 있다. 각 건물은 외형상으로는 한옥같이 보이나 세부적인 것은 중국 청나라 말기 수법을 보인다.","a":"안국동 윤보선가","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625018.jpg"},{"q":"○○○ 법당 뒷마당에 서 있는 석탑으로, 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 아래·위층 기단은 네 귀퉁이와 각 면의 중앙에 기둥 모양을 새기고, 각 기단의 윗면에는 2단의 괴임을 두어 윗돌을 받치도록 하였다. 탑신은 몸돌과 지붕돌을 각각 하나의 돌로 만들었다. 층마다 네 모서리에 기둥 모양이 새겨져있을 뿐 다른 꾸밈은 없다. 지붕돌은 밑면에 4단의 받침을 두고 있으며, 네 귀퉁이에서 살짝 치켜올려져 있다. 꼭대기에는 둥근 돌을 차례로 얹어 놓았는데, 훗날 보충해 놓은 것이어서 탑과는 잘 어울리지 않는 모습이다.","a":"영덕 유금사 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621405.jpg"},{"q":"이 책은 원나라 호정방이 편찬한 중국 태고부터 오대(五代)에 이르기까지의 17정사(正史)를 간추려 모은 책이다. 태종 3년(1403)에 주조한 계미자(字)를 사용하여 태종 12년(1412)에 인쇄, 발행한 것으로 추정된다. 구성을 보면 1책으로 1∼33장으로 구성되었으나 11장과 34장 이하는 빠져있다. 책의 상태를 보면 마모가 심하여 29장에서 33장까지 책의 앞머리가 보이지 않는다. 원표지 위에 황색 표지를 입히고 붉은 면으로 보강하였다. 책의 크기는 가로 18.7㎝, 세로 25.6㎝이다.","a":"십칠사찬고금통요 권17","c":"국보","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611608.jpg"},{"q":"○○선생이 사용하던 사인(私印)으로 [○○]·[○○○○]·[○○] 3과로 구성되는 낙관(落款) 한 조로서 각각 두인(頭印), 성명인(姓名印), 아호인(雅號印)이다. 검은 옥석(玉石)에 연잎무늬가 새겨져 있고 ‘惺齋作’, ‘丙戌仲春惺齋仿古’라는 측관(側款, ○○의 옆면에 새긴 문자)이 있어 근대기의 유명한 전각가 성재(惺齋) 김태석(金台錫, 1875～1953)이 1946년 봄에 새긴 것임을 알 수 있으며, ○○ 선생이 주로 글씨를 쓸 때 사용했던 것으로 1945년 11월 중국에서 귀국한 이후에 쓴 유묵(遺墨)의 대부분에 이 ○○이 찍혀 있어 자료적 가치가 크다.","a":"백범 김구 인장 寬和, 金九之印, 白凡","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667277.jpg"},{"q":"전북특별자치도 ○○군 ○○○ 칠목재 구릉 중턱에 있는 백제무덤들이다. 1986년 이 마을의 한 고등학생이 칡을 캐다가 금동제 모자 등을 발견·신고하여 알게되었다. 긴급발굴을 하여 8기의 무덤을 확인하였는데, 1호를 제외하고는 파손이 심하였다. 1호 무덤은 널방(현실)과 널길(연도)을 갖춘 굴식돌방무덤(횡혈식석실묘) 이다. 또한 천장은 네 벽을 맞추어 쌓아 올리면서 마지막 4장을 덮은 활천장(궁륭식천장)을 이루었다. 출토된 유물로는 토기류·금동모자와 금귀고리, 유리구슬 등의 장신구류·말갖춤(마구)·철기 등 백제 중요 유물이 수습되었다.","a":"익산 입점리 고분","c":"사적","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626927.jpg"},{"q":"신라 때 돌로 쌓은 산성으로 능선을 따라 5각형에 가까운 형태를 띠고 있다. 현재 성 안의 특별한 시설물들은 확인되지 않고 있으며 성의 내력에 대해서는 『○○군읍지』가 유일한 자료이다. 이 기록과 성의 위치 및 규모로 보아 신라가 군사적 목적으로 쌓은 것으로 보인다. 최근에는 5세기 전반 고구려 광개토왕이 신라를 거쳐 왜군을 토벌하면서 남하했을 때 쌓은 고구려 계통의 성으로 보는 의견도 제시되고 있다. 성벽은 네모나게 다듬은 돌과 자연석을 사용하여 견고하게 쌓았다.","a":"하동 고소성","c":"사적","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628251.jpg"},{"q":"○○○에 소장된 조선 16세기 후반에 만들어진 종이다. 맨 위에는 대롱 형태로 솟은 음통과 종의 고리 역할을 하는 용뉴가 두 다리로 천판을 누르고 있는 모습으로 조각되었다. 그리고 어깨위를 돌아가며 입화장식과 그 아래로 연꽃무늬가 돌려 있고, 그 밑에 넓은 띠에는 방형 속에 연꽃무늬를, 아래에는 작은 원 속에 범자를 새겨 넣었다. 넓은 몸체에는 네군데에 사각형의 연곽이 있는데 그 주위는 당초문으로 장식을 하고 그 안에 9개의 연뢰를 나즈막하게 돌출표현하였다. 몸체의 하대는 종구에서 조금 올라와 배치되었는데, 상대와 마찬가지로 연꽃무늬와 당초문을 새겨 넣었다.","a":"곡성 태안사 동종","c":"보물","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619845.jpg"},{"q":"『○○○○○』은 조선 태조에서부터 조선 철종 때까지 25대 472년간(1392∼1863)의 역사를 편년체(編年體: 역사적 사실을 일어난 순서대로 기술하는 역사서술의 한 방식)로 기록한 책이다. ○○○○○는 1606년(선조 39) 경에 설치되었다. 임진왜란으로 전주○○○을 제외한 나머지 실록들이 모두 소실되자 조선정부는 1603년(선조 36) 7월부터 1606년 3월까지 전주○○○을 바탕으로 태조부터 명종까지의 실록 4부를 재간행했다. 그리고 강화·태백산·묘향산·○○○ 등지에 사고를 새로 건축하여 서울의 춘추관사고와 함께 5곳의 사고에 실록을 보관하였다.","a":"조선왕조실록 오대산사고본","c":"국보","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2021042814545900.jpg"},{"q":"이 사경은 고려후기 14세기 중기에 상지에 은니로 사성한 화엄경 80권 가운데 ○○에 해당되는 잔권1첩이다. 권수에 변상도는 없으나 표지는 연화문으로 장엄되어 있으며, 본문의 글씨는 해서체로 매우 정성껏 필사되어 있고 원형이 거의 온전하게 잘 보존되어 상태도 양호하다. 상지에 은니로 쓴 사경은 국내에 모두 10여점이 전존되고 있으며, 이 중 화엄경은 2점이 지정되어 기림사와 국립중앙박물관에 수장되어 있는 실정이다.","a":"상지은니 대방광불화엄경 주본 권4","c":"보물","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614981.jpg"},{"q":"이 왕지는 조선 태조 7년(1398) 제1차 왕자의 난에 공을 세운 ○○에게 공전(功田)을 내린 문서이다. ○○은 조선을 건국하는데에도 공을 세워 개국공신 2등에 임명되었고, 제2차 왕자의 난때도 이방간의 군사를 몰아낸 공을 인정받아 좌명공신 4등에 올랐다. 제 1차 왕자의 난은 왕위계승권을 둘러싸고 이방원이 그의 이복동생인 이방석의 일파와 싸운 사건이다. 이 때 이방석의 일파를 제거하는데 공을 세운 사람은 모두 29명으로, 이들은 두 등급으로 나누어 포상되었다. 1등 공신 12명, 2등 공신 17명인데 ○○은 2등급에 올랐다.","a":"조온 사패왕지","c":"보물","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615999.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하며, 부처가 되는 길이 누구에게나 열려 있다는 것을 중요사상으로 하고있다. 천태종의 근본 경전으로 화엄경과 함께 한국 불교사상 확립에 크게 영향을 끼친 경전이다. 이 책은 구마라습이 한문으로 번역하고, 계환(戒環)의 풀이와 일여(一如)의 주석모음이 붙은 법화경을, 세조 9년(1463)에 본문과 계환의 풀이부분만 한글로 번역한 것이다. 세조 7년(1461) 불경을 한글로 풀이하여 간행하기 위해 설치한 간경도감(刊經都監)에서 목판에 새겨 닥종이에 찍어낸 것으로, 상(82장)·하(82-202장) 2책으로 되어있다.","a":"묘법연화경(언해) 권3","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614615.jpg"},{"q":"이 책은 임진왜란(1592∼1598) 때에 ○○○이 친필로 작성한 일기로 연도별로 7권이다. ○○○은 28살되던 해에 무인 선발시험인 훈련원별과에 응시했으나, 불행하게도 달리던 말이 거꾸러지는 바람에 실격하였고, 4년 뒤 무과에 급제하여 권지훈련원봉사로 처음 벼슬을 시작했다. 사대부가의 전통인 충효와 문학에 있어서 뛰어났을 뿐 아니라 시(詩)를 짓는데도 특출하였다. 전라좌도 수군절도사를 지내던 때 곧 왜적의 침입이 있을 것에 대비하여 여수를 중심으로 배를 만들고 군비를 늘리는 등 일본의 침략에 대처하였다.","a":"이순신 난중일기 및 서간첩 임진장초","c":"국보","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612255.jpg"},{"q":"○○○○○에 대한 기록은 거의 남아있지 않으며, 1995년도에 발간된 『○○군사료집』에 의해서 처음 알려지게 되었다. 그 후 1995년부터 2003년사이 지표조사 및 발굴조사가 이루어지면서 고구려토기 일부가 발견되는 등 고구려를 중심으로 한 삼국시대 성으로 추측된다. ○○○○은 한탄강 장진천의 합류지점에 형성된 삼각형의 하안단구 위에 축조된 성으로 한탄강과 합류하는 곳이 삼각형의 꼭지점을 이루고 이곳에서 동쪽으로 가면서 점차 넓어지는 형태이다. 남벽과 북벽은 각각 단애를 활용하여 성벽을 축조하였지만 동벽은 동쪽에 형성된 개활지를 가로질러 축조되었다.","a":"연천 은대리성","c":"사적","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626021.jpg"},{"q":"○○○○○은 ○○시 ○○○ 일대의 토지구획정리사업이 진행되던 당시에 발견된 선사시대 유적이다. 1997년 4월부터 1999년 7월에 걸쳐 ○○대학교 박물관에서 발굴조사를 실시한 결과 청동기-초기철기시대를 전후한 시기의 집터 200여 곳을 비롯하여 돌을 쌓아 만든 담장, 쓰레기를 버리던 폐기장, 마을의 외곽을 두르고 있던 도랑 자리가 있는 큰 규모의 마을 유적이 확인되었다.","a":"제주 삼양동 유적","c":"사적","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628611.jpg"},{"q":"경상북도 ○○ 굴불사터에 있는 이 불상은 바위의 서쪽에는 아미타여래불, 동쪽에는 약사여래불, 북쪽에는 미륵불, 남쪽에는 석가모니불을 각각 새긴 사방불(四方佛) 형태이다. 『삼국유사』 에 의하면 신라 경덕왕이 백률사를 찾았을 때 땅속에서 염불 소리가 들려왔다고 한다. 땅을 파 보니 이 바위가 나와서 바위의 사방에 불상을 새기고 절을 지어 굴불사라 하였다고 전한다. 이 기록만으로는 분명하지 않지만, 여러 가지 여건으로 보아 이때쯤 불상이 만들어졌을 것으로 추정된다.","a":"경주 굴불사지 석조사면불상","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620257.jpg"},{"q":"팔만대장경이 보관되어 있는 호국신앙의 요람인 ○○○의 ○○○ 안에 있는 다층(多層) 석탑이다. 탑신(塔身)을 점판암으로 만든 청석탑(靑石塔)으로, 점판암은 벼루를 만드는데 주로 사용되는 석재이다. 땅과 맞닿아 탑의 토대가 되는 바닥돌은 화강암을 이용하여 3단으로 쌓았으며, 그 위에 탑신을 받치는 기단(基壇)과 지붕돌은 점판암으로 구성하였다. 기단은 1단으로 밑면에는 돌아가며 연꽃무늬를 장식하였고, 윗면은 네 모서리에 대리석 돌기둥을 세웠으며, 맨윗돌에는 연꽃무늬를 새겼다. 탑신의 몸돌은 남아있지 않고 지붕돌만 10층이 쌓여 있다.","a":"합천 해인사 원당암 다층석탑 및 석등","c":"보물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622750.jpg"},{"q":"조선 후기의 실학자인 다산 ○○○ 선생이 유배되어 11년간 머물면서 많은 책을 저술했던 곳이다. ○○○은 여유당(與猶堂) 등의 여러 호를 가지고 있으며, 천주교 이름으로는 요한(Johan)이라 하였다. 정조의 총애를 한 몸에 받았으며, 유형원과 함께 수원성을 설계하고 거중기 등의 신기재를 이용하여 수원 화성을 쌓기도 했다. 정조가 죽자 신하들의 모함을 받아 투옥되어 유배되었고, 그 후 18년 간의 유배생활 동안 그는 많은 저서를 남겼다. ○○○의 사상은 한국사상의 원형과 직결된다고 할 수 있다.","a":"강진 정약용 유적","c":"사적","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627050.jpg"},{"q":"○○○○○는 조선시대 측우기를 올려 놓고 강우량을 측정하던 것으로 지금은 대석(臺石)만 남아 있다. 측우기는 세종 23년(1441) 세계 최초로 발명되어 이듬해 전국적으로 강우량 측정이 시작되었는데, 이것은 그 전에 땅 속에 스며든 비의 양은 잴 수 없던 비합리적 방법에서 벗어난 15세기의 획기적 발명품이었다. 철로 만든 원통형 의 측우기는 돌 위에 올려 놓고 사용했는데 높이 87.6㎝, 세로 59.7㎝, 가로 94.5㎝의 직육면체의 화강암으로, 가운데에 직경 16.5㎝, 깊이 4.7㎝로 구멍을 뚫어 세웠다.","a":"관상감 측우대","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614073.jpg"},{"q":"○○○○○은 고려 시대의 만들어진 ○○ 상감 ○○으로 높이 41.5㎝, 아가리 지름 7.5㎝, 밑지름 15.8㎝의 크기로 ○○ 가운데 드물게 보이는 큰 작품이다. 술병으로 보이는 ○○은 고려의 세련미를 보이며 매우 활발하게 제작되었다. 이 때의 ○○과 비교해보면 다리가 길어지고 아가리가 커졌으며, 정선되지 않은 바탕흙, 깨끗하게 마무리 되지 않는 굽다리들로 전성기가 지난 시기에 만든 것으로 짐작된다. 어깨부분에는 비교적 큰 꽃무늬를 상감하였고, 넓은 몸통에는 덩굴 포도잎과 열매로 가득 채웠다.","a":"청자 상감포도동자문 매병","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613247.jpg"},{"q":"ㅇ ○○○○○는 고려 명종 3년(1173년) 국난(김보당의 난) 극복을 위해 조응대선사(祖膺大禪師)가 발원하고 조성한 것으로, 고대 건축물로는 매우 드물게 발원자와 건립시기, 건립목적이 분명하게(重修龍門寺記/1185년) 드러나 있다. 대장전은 일반적으로 불교경전을 보관하는 건물인데, ○○○ 대장전은 ○○○를 보관하고 있는 국내 유일의 경장건축이라는 데서 독특한 가치가 있다. ㅇ ○○○는 불교 경전을 보관하는 회전식 경장(經藏)으로 한쌍으로된 ○○○는 동아시아에서도 그 사례가 없고 국내 유일이라는 절대적 희소성과 상징성이 있다.","a":"예천 용문사 대장전과 윤장대","c":"국보","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2019120211000800.jpg"},{"q":"가옥 1927년, ○○ 1930년 건립 이 건물들은 일제 강점기 영산강 중천포 나루터 근처에 지은 일본인 지주의 집과 ○○이다. 곡물 수송에 아주 편리한 위치에 있었기 때문에 ○○의 기능이 강조되었으며, 지금도 잘 남아 있어 당시 이곳의 번화하였던 상황을 짐작하게 해준다. 일제강점기에 전형적인 ○○○ 건축 기법으로 지은 건물로서 과거 일본 지주의 주거 공간 구성을 잘 보여 준다.","a":"함평 월호리 일본식 가옥과 창고","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668906.jpg"},{"q":"고려 태조 4년(921)에 창건되었던 천흥사의 ○○○○로 현재 ○○시 천흥리 마을의 가운데에 자리잡고 있다. 절에서는 의식이 있을 때 절의 입구에 당(幢)이라는 깃발을 달아두는데, 깃발을 달아두는 장대를 당간(幢竿)이라 하며, 이 당간을 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라고 한다. 동·서로 서있는 두 지주는 60㎝의 간격을 두고 있으며, 2단의 기단(基壇) 위에 세워졌다. 기단은 흩어져 있던 것을 복원하였는데 기단 주위에 안상(眼象)을 새겨넣어 ○○○○의 장식화된 측면을 보이고 있다. 동·서 지주 사이로 깃대를 직접 받치던 받침은 남아있지 않다.","a":"천안 천흥사지 당간지주","c":"보물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617449.jpg"},{"q":"신라 종 양식을 보이는 고려시대 초기에 만들어진 대형의 범종으로, 높이1.44m, 입지름 0.87m, 무게 1.5톤이다. 종 맨 위에는 소리의 울림을 도와 주는 용통이 있고, 고리 역할을 하는 용뉴는 용이 여의주를 물고 두 발로 힘차게 몸을 들어 올리는 형상을 하고 있다. 윗 문양띠(上帶)에는 구슬무늬로 테두리를 하고 있는데, 아래 위 서로 어긋나게 반원을 그리고 그 안에 꽃과 구슬무늬을 새긴 넓은 띠를 두르고 있다. 이 띠는 사각형 모양의 연곽과 한 면이 붙어 있다. 4곳의 연곽 안에는 9개의 돌출된 연꽃 모양의 연뢰가 있는데, 남아 있는 것은 1곳 뿐이다.","a":"용주사 동종","c":"국보","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612039.jpg"},{"q":"○○○ 종손가에 소장되어 있는 2점의 왕지이다. ○○○는 조선 전기 지방관을 지냈다. 「○○○통정대부지울주사왕지」는 정종 1년(1399) 1월 26일에 ○○○에게 관직을 제수하는 사령왕지이다. 이 사령왕지는 총 4행으로 초서체로 쓰여졌고, 년월 위에 ‘조선왕보’라고 도장이 찍혀 있다. 이 문서는 조선 전기의 관제 및 인사행정의 변천을 살필 수 있는 자료이다. 「○○무과급제왕지」는 세종 17년(1435)에 ○○○의 손자 ○○에게 발급된 무과급제를 인정하는 홍패왕지이다. 총 5행에 걸쳐 초서체로 쓰여졌고, 년월 위에 ‘국왕신보’라고 도장이 찍혀있다.","a":"이종주 고신왕지 및 이임 무과홍패","c":"보물","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621991.jpg"},{"q":"○○○의 예배공간인 대웅전과 극락전에 오르는 길은 동쪽의 ○○○와 ○○○, 서쪽의 연화교와 칠보교가 있다. ○○○와 ○○○는 대웅전을 향하는 자하문과 연결된 다리를 말하는데, 다리 아래의 일반인의 세계와 다리 위로의 부처의 세계를 이어주는 상징적인 의미를 지닌다. 전체 34계단으로 되어 있는 위로는 16단의 ○○○가 있고 아래로는 18단의 ○○○가 있다. ○○○를 푸른 청년의 모습으로, ○○○를 흰머리 노인의 모습으로 빗대어 놓아 인생을 상징하기도 한다. 계단을 다리형식으로 정교하게 다듬어 만든 특이한 구조를 하고있다.","a":"경주 불국사 청운교 및 백운교","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612696.jpg"},{"q":"<○○○○○>은 조선의 문신이며 학자였던 ○○○의 상반신을 그린 ○○화로 가로 62.5㎝, 세로 134㎝ 크기이다. ○○○은 중종 38년(1543) 우리나라 최초의 서원인 백운동서원(후의 소수서원)을 세워 학문진흥에 힘썼다. 이 ○○화는 사모관대의 정장 관복을 차려입고 왼쪽을 바라보고 있는 모습을 그렸다. 얼굴은 간략한 선으로 묘사하고, 넉넉한 몸체에 목은 거의 표현하지 않아 권위적인 기품이 엿보인다. 옷의 깃을 낮게 표현한 것은 다른 ○○화에도 나타나는 것으로 당시 유행하던 양식으로 생각된다.","a":"주세붕 초상","c":"보물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621496.jpg"},{"q":"2005년과 2013년 두 차례의 정밀지표조사를 시행하여 ○○ 영원면 일대의 반경 2km내 구역에는 275여 기의 백제고분이 분포하고 있음을 확인하였으며, 그 중 영원면 ○○○○ 덕천면 ○○○에 집중적으로 분포하고 있는 백제 횡혈식 석실분 56기를 대상으로 사적으로 지정하였다. 「○○○○○」은 전북특별자치도의 백제고분으로는 지금까지 발견된 최대 규모이다. 횡혈식 석실은 백제 무덤의 대표적인 양식으로 이곳의 ○○○은 이 지역에서 백제의 영역 확장을 잘 보여주고 있다.","a":"정읍 은선리와 도계리 고분군","c":"사적","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2018051818023000.JPG"},{"q":"○○○의 ○○는 배산구조와 안산, ○○ 배치와 진입로 구조가 시각적으로 뚜렷한 축을 형성하여 한양의 광화문-경복궁-백악산의 축과 매우 흡사한 시각 이미지를 형성하고 있는 곳이다. 현존하는 ○○ 건물인 기성관은 ○○○의 객사로 중심적 역할을 하던 곳으로 단청이 화려하고 웅대한 누의 모습을 보여주고 있으며, 비록 동헌 건물이 헐리고 그 자리에 면사무소가 들어서 있지만 부속 건물이었던 질청이 남아있고 당시 고지도 등의 관련 자료가 많아 당시 읍치 모습을 찾아 볼 수 있는 유적중의 하나이다.","a":"거제현 관아","c":"사적","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628477.jpg"},{"q":"<○○○○○>은 헌종(재위 1834∼1849)이 효정왕후와 혼인할 때의 모습을 그린 ○○으로 크기는 각 폭 가로 115㎝, 세로 51㎝이며 비단에 채색 되었다. 헌종의 첫 왕비인 효현왕후 김씨가 헌종 9년(1843)에 죽고 이듬해 10월 효정왕후와 가례를 올렸는데 이 때 그려진 것으로 모두 8폭으로 이루어져 있다. 제1폭은 예식을 맡아보던 예문제장 조병구가 쓴 축하의 글이 실려 있고 제8폭에는 선전관청에 있는 사람들의 관등·성명·본관 등을 기록한 글이 있다.","a":"헌종가례진하도 병풍(1982)","c":"보물","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615099.jpg"},{"q":"안채·바깥채·헛간·광이 울안에 자리하고 있는 초가집이다. 안채의 상량문에 의하면 조선 고종 25년(1888)에 지어진 것으로 되어있다. 집 뒤로는 얕은 산이 둘러져 있고 앞으로는 조그마한 개울이 흐른다. 주변에 오랜 한옥이 많고 감나무가 있어 옛스러운 맛을 지니고 있다. 안채는 평범한 'ㄱ'자형으로 부엌·대청·안방·건넌방으로 되어있다. 초가인 지붕은 두께가 대단히 두껍다. 동편의 끝칸이 부엌이고 이어 안방이 있다. 바깥채와 안채는 안마당을 사이에 두고 'ㅁ'자형으로 배치되었다.","a":"수원 광주이씨 고택","c":"국가민속문화유산","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633714.jpg"},{"q":"조선 17대 효종(재위 1649∼1659)의 후궁 안빈 이씨(1622~1693)의 무덤이다. 안빈 이씨는 병자호란때 봉림대군(효종)이 청에 볼모로 가자 심양까지 따라가 봉림대군을 모셨다고 한다. 효종이 왕위에 오른 후 후궁이 되었으며, 1686년(숙종 12)에 안빈에 책봉되었다. 효종 사이에서 숙녕옹주를 낳았다. 묘소에는 문석인, 망주석, 장명등, 상석, 묘표석 등이 있으며, 묘표석 앞면에는 ‘조선국안빈경주이씨지묘(朝鮮國安嬪慶州李氏之墓)’라 새겨져 있다. ※ ○○○○○는 사적지 원형 보존과 훼손 방지를 위하여 비공개로 관리중입니다.","a":"남양주 안빈묘","c":"사적","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020081309484100.jpg"},{"q":"충남 ○○군 ○○○에 있는 백제의 토기 및 기와를 굽던 가마터로, 1941년 5월에 ○○ 시가지 계획도로 공사 중에 발견되었다. 발견 당시 가마는 땅에 묻힌 상태여서 분명하진 않지만, 길이 약 4m, 폭 135㎝, 높이 90㎝ 정도의 크기였다. 굴뚝 부분에서 아래로 3㎝ 정도가 남아 있고 아궁이 부분은 밝혀지지 않았다고 한다. 현재 가마터 앞쪽으로 도로가 완성되면서 가마의 앞부분이 잘리게 되었으며, 현재 가마터는 시멘트로 석실을 만들어 보호하고 있다.","a":"부여 쌍북리 요지","c":"사적","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626511.jpg"},{"q":"○○○ 절터에 남아있는 통일신라시대의 탑이다. 절터에 남아있는 많은 유물들로 보아 이전에는 이곳이 상당히 큰 규모의 사찰이었을 것으로 여겨지지만, 절의 이름은 전해지지 않고 있다. 탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올려 세운 모습이다. 위·아래층 기단의 각 면에는 모서리와 가운데에 하나씩의 기둥 모양을 새겨 두었다. 탑신은 몸돌과 지붕돌이 각각 하나의 돌로 이루어져 있으며, 몸돌에는 모서리마다 기둥 모양이 새겨져 있다. 지붕돌은 밑면의 받침이 1·2층은 5단이나, 3층은 4단으로 줄어들었다.","a":"홍천 물걸리 삼층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616706.jpg"},{"q":"영남지방과 서울간의 ○○이자 군사적 요새지이다. 이곳은 고려 초부터 ○○이라 불리면서 중요한 교통로로 자리잡았다. 조선 선조 2년(1592) 임진왜란 때 왜장 고니시 유끼나가가 경주에서 북상해오는 카토오 키요마시의 군사와 합류했을 정도로 군사적으로 중요한 지점이었다. 이 때 조정에서는 이곳을 지킬 것이라 생각했지만 신립장군은 ○○에서 왜군을 막지 못하고 충주 탄금대에서 왜병을 맞서 싸우다가 패하고 말았다. 그 뒤 조정에서는 이 실책을 크게 후회해 ○○에 대대적으로 ○○을 설치할 것을 꾸준히 논의하다가 숙종 34년(1708)에 이르러서야 3개의 ○○을 완성했다.","a":"문경 조령 관문","c":"사적","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627718.jpg"},{"q":"쇠부리 마을 가운데에 자리잡은 기와집으로 1918년에 지었다. 동향한 넓은 터에 북향 대문을 들어서면 정면에 'T'자형의 사랑채가 있고, 오른쪽으로는 바깥행랑채가 있다. 사랑채 안쪽에는 'ㄱ'자형의 안채와 '一'자형의 안행랑채, 그리고 곳간이 있어 전체적으로 튼 'ㅁ'자형을 이루고 있다. 이 집은 안채, 특히 부엌이 주택전체의 중심을 잡고 있는 집이다. 안채는 'ㄱ'자형의 꺾인 부분을 한번 접은 모양이고 꺾인 좌우가 거의 대등한 규모이다. 그 중앙에 부엌이 있는데, 부엌은 거의 정사각형으로 내부에는 기둥이 두 개만 서 있어 넓게 보인다.","a":"함양 허삼둘 고택","c":"국가민속문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635924.jpg"},{"q":"○○은 조선 4대 세종(재위 1418∼1450)과 부인 소헌왕후 심씨(1395∼1446)의 무덤이다. 세종은 정치·경제·사회·역사·문화 등 각 분야에서 조선시대 문화의 황금기를 이룩한 왕이다. 세종 28년(1446)에 소헌왕후가 죽자 헌릉 서쪽 산줄기에 쌍실 무덤인 ○○을 만들었다. 동쪽 방은 왕후의 무덤으로 삼고, 서쪽 방은 왕이 살아 있을 때 미리 마련한 무덤으로 문종 즉위년(1450)에 왕이 죽자 합장하였다. 조선왕릉 중 최초로 한 봉우리에 서로 다른 방을 갖추고 있는 합장무덤을 하고 있다.","a":"여주 영릉과 영릉","c":"사적","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625543.jpg"},{"q":"고려말의 승려 일연(一然)이 1281년(고려 충렬왕 7)에 지은 삼국시대의 역사서이다. 체재는 5권 2책으로 되어 있으며, 내용은「왕력(王歷)」, 「기이(紀異)」,「흥법(興法)」,「탑상(塔像)」,「의해(義解)」,「신주(神呪)」,「감통(感通)」,「피은(避隱)」,「효선(孝善)」등 9편으로 구성되어 있다. 주요 내용을 살펴보면, 「왕력」은 삼국과 가락국·후고구려·후백제 등의 간략한 연표이고, 「기이」는 고조선으로부터 후삼국까지의 단편적인 역사를 서술한 것으로 첫 머리에 이 편을 설정하게 된 이유를 밝힌 서문이 있다.","a":"삼국유사","c":"국보","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611952.jpg"},{"q":"낙안성 남문을 통해 들어간 남내리의 길가에 위치한 초가집이다. 대문을 들어서면 바로 안마당이고, 마당 깊숙한 곳에 안채가 동남향으로 자리잡고 있다. 안채의 앞쪽으로는 헛간채가 있고 서남쪽의 담 모서리에 화장실이 있다. 안채는 부엌·큰방·작은방 순으로 배열되어 있다. 서쪽과 뒷쪽의 벽을 맞담으로 쌓았을 뿐 앞면은 완전히 개방되어 있다. 방 앞에는 툇마루를 달았고 후대에 작은방의 옆으로 헛간을 추가로 설치하였다. 부엌에는 부엌신인 조왕신이 모셔져 있고 부엌과 헛간채의 사이에는 잘 정돈된 장독대가 있다. 토담집 특유의 수수하고 소박함을 보여주는 집이다.","a":"순천 낙안읍성 뙤창집","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634584.jpg"},{"q":"이곳은 14세기 말부터 15세기에 걸쳐 사용된 가마터이다. 이 곳에서 출토되는 대접이나 접시, 사발 등의 파편들을 미루어 추정해 보면 상감청자, 분청사기 등을 만들던 곳으로 여겨진다. 『세종실록, 世宗實錄』지리지(地理志)에 실린 전국의 324개 가마 중에서도 가장 좋은 상품의 자기를 만들기로 이름난 곳의 하나이다. 현재 남아있는 “○○인수부(高靈仁壽府) ○○장흥고 (高靈長興庫)”라고 새긴 그릇들을 만들었던 곳으로 보여진다. 이 곳에서 생산된 제품은 대접과 접시가 대부분을 차지하는데, 대체로 그릇벽은 두껍고 무늬 모양은 국화무늬, 구름무늬, 소용돌이 무늬가 많다.","a":"고령 사부동과 기산동 요지","c":"사적","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628075.jpg"},{"q":"1950년대에 건립된 소규모 관공서 건물로 지붕의 목조트러스 구조가 원형의 모습을 잘 유지하고 있고, 주출입구 부분을 조형적으로 처리한 독특한 입면구성을 보이는 등 지역을 대표하는 근현대건축유산으로서 보존 가치가 충분하다.","a":"광양 구 진월면사무소","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018121110231400.jpg"},{"q":"조선시대 한양도성의 정문으로 남쪽에 있다고 해서 남대문이라고도 불렀다. 현재 ○○에 남아 있는 목조 건물 중 가장 오래된 것으로 태조 5년(1396)에 짓기 시작하여 태조 7년(1398)에 완성하였다. 이 건물은 세종 30년(1448)에 고쳐 지은 것인데 1961∼1963년 해체·수리 때 성종 10년(1479)에도 큰 공사가 있었다는 사실이 밝혀졌다. 이후, 2008년 2월 10일 ○○○ 방화 화재로 누각 2층 지붕이 붕괴되고 1층 지붕도 일부 소실되는 등 큰 피해를 입었으며, 5년 2개월에 걸친 복원공사 끝에 2013년 5월 4일 준공되어 일반에 공개되고 있다.","a":"서울 숭례문","c":"국보","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2685609.jpg"},{"q":"1678년에 전국에 분포하는 목장을 그린 필사본 채색지도첩이다. 1권 42면으로 구성된 이 지도첩은 모두 3장으로 구성되었다. 첫 장에는 진헌마정색도(進獻馬正色圖), 두 번째 장에는 도군별 목장상황을 담은 회화식 지도, 세 번째 장에는 이 지도첩의 제작 동기와 시기를 알려주는 허목(許穆)의 기문(記文)이 실려 있다. 허목은 당시 사복시의 제조였는데, 그 이전에 작성되었던 ○○○○를 수정편찬하여 ○○○○를 제작하게 하였다. 회화식 지도부분에는 전국의 목장 소재지를 지도에 그려넣고 소와 말, 목자(牧子)의 통계와 목장의 면적, 폐장된 목장의 상황 등을 기재하였다.","a":"목장지도(2008-1)","c":"보물","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614936.jpg"},{"q":"○○○○○의 삼존○○ 등 판○○ 10점은 조각수법이 우수하고 상들의 표현이 사실적이며 입체감이 두드러진다. 양식적으로는 7세기 말 통일신라와 중국, 일본을 포함한 국제적인 조각양식의 특징을 잘 보여준다. 특히, 도상이나 양식면에서 일본 법륭사 헌납보물에 있는 판불들이나 법륭사 금당 서벽 아미타정토의 본존○○과도 비교된다. 둥글고 통통한 얼굴과 자연스러운 옷주름 처리에 보이는 조각의 사실적인 표현은 중국 당(唐)시대 전성기 ○○양식을 반영하면서도 7세기 후반 통일신라 불교조각의 뛰어난 표현력을 잘 대변해준다.","a":"안압지 출토 금동판 불상 일괄","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622242.jpg"},{"q":"1890년대 건립된 이 가옥은 일제 강점기에 민족 독립을 위하여 노력하였으며, 대한민국 수립 이후 의회정치 지도자로서 나라 발전에 공헌한 ○○○의 생가로 역사적 가치가 높은 곳이다. 현재 안채는 주초석 일부만이 남아 있고 사랑채, 문간채, 고방이 보존되어 있으며 생가 가까운 곳에 ○○이 있다.","a":"정읍 나용균 생가와 사당","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668789.jpg"},{"q":"850년에서 900년 사이에 집중적으로 만들어진 비로자나불 가운데 하나로 통일신라시대 불상양식의 현실적이고 사실적인 특성을 보여주는 작품이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리 부분에 있는 상투 모양의 머리(육계)는 크고 펑퍼짐하다. 원만한 얼굴에는 눈·코·입 등이 알맞은 크기와 모습으로 배치되었다. 귀는 짧고 목에 있는 3개의 주름인 삼도(三道)는 분명하게 표시되어 있다. 양 어깨에 걸쳐 입은 옷은 불상 전체에 걸쳐져 있고 옷주름은 다리까지 부드러운 곡선을 이루며 흐르고 있다.","a":"창원 불곡사 석조비로자나불좌상","c":"보물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622645.jpg"},{"q":"이 건물은 ○○○○으로 지어져 광양의 행정 중심지 역할을 해온 역사적인 곳이다. 공간 구성이 단순하며 정면 중앙부에 현관 포치(porch)가 돌출되어 있는 등 건립 당시의 전형적인 군청건물의 평면 형태와 외관을 갖추고 있다.","a":"구 광양군청","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669041.jpg"},{"q":"탑의 전면에는 한천이 흐르고 있으며, 뒷면에는 흑응산이 위치하고 있다. 이곳은 탑과 불상이 남아있는 것으로 보아 절터였음이 분명하지만, 절 이름은 알 수 없다. 기단부(基壇部)는 윗층 기단 아래가 파묻혀 있어서, 원래 기단이 2층인지 1층이었는지 분명하지 않다. 현재는 윗면에 경사진 돌이 있고, 기단의 가운데돌을 그 위로 얹고 있다. 가운데돌은 4장의 널돌로 짰는데 각 면의 모서리마다 기둥모양을 새기고, 그 사이에 사천왕상(四天王像)을 조각해 놓았다. 사천왕은 불법을 수호하는 부처의 네 신을 뜻한다.","a":"예천 동본리 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620886.jpg"},{"q":"‘○○○○○’은 연희전문학교 시절 윤동주시인 등과 함께 근현대사 속 인물들이 생활했던 기숙사 건물이라는 역사적 의미와 함께, 동시대 건립된 학교 기숙사건물이 대부분 사라진 상황 속에서 건축형태 및 구조, 생활환경 등을 간접적으로 엿볼 수 있다는 측면에서 가치가 있다.","a":"서울 연세대학교 핀슨관","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019123016113000.jpg"},{"q":"○○시내를 남동에서 북서쪽으로 가로질러 흐르는 무심천 서북쪽 기슭의 동쪽 비탈진 곳에 분포하고 있다. 107기의 고분이 조사되었는데 106기는 흙을 판 후 무덤을 쓴 널무덤(토광묘)이고, 1기는 널방과 널길을 가진 굴식돌방무덤(횡혈식석실분)이다. 널무덤은 야산 전체에 걸쳐 분포하며, 봉분은 거의 깎여 나가 남아있지 않다. 출토 유물로는 여러가지 토기류·옥과 같은 장신구류·철로 만든 칼이나 도끼같은 무기류·말갖춤(마구류)과 그 밖의 숟가락 등이 나왔다. 90-1호 널무덤에서는 갑옷이 출토되어 백제철갑의 실물을 볼 수 있어 주목되고 있다.","a":"청주 신봉동 고분군","c":"사적","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626267.jpg"},{"q":"공주에서 ○○쪽으로 23㎞ 떨어진 벌판 가운데에 서 있는 탑으로, 부근에 고려시대 백곡사(白谷寺)라는 절이 있었다고 하나 주위에 기와조각 등이 흩어져 있을 뿐 다른 유물들은 찾아볼 수 없다. 탑은 2단의 기단 위에 9층의 탑신을 올린 모습이다. 아래층 기단에는 안상(眼象)을 돌려 새겼는데, 바닥선이 꽃모양으로 솟아올라 있어 고려시대의 양식상 특징을 드러낸다. 윗층 기단에는 네 모서리와 면의 가운데에 기둥 모양을 새겼으며, 그 위로 알맞은 두께의 돌을 덮어 안정된 모양새를 띠고 있다.","a":"청양 서정리 구층석탑","c":"보물","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617405.jpg"},{"q":"○○의 서쪽 주산에 쌓은 가야의 산성이며, 이산성(耳山城)이라고도 한다. 산성의 남쪽 산등성이에는 대가야 무덤들이 분포되어 있어 산성과의 연관성을 보여주고 있다. 산의 가장 높은 곳과 동쪽의 능선을 따라 둥글게 흙으로 쌓은 내성과, 내성의 동쪽과 서쪽 끝에서 시작하여 타원형으로 돌을 쌓은 둘레 약 700m의 외성으로 된 2중 성벽을 가지고 있다. 성벽은 대부분 무너졌으나, 계곡쪽으로는 견고하게 쌓은 성벽이 남아 있다. 현재 외성은 대나무숲이 우거져 있어 먼곳에서 전체 윤곽을 파악하기 힘들며, 성 안에 우물터와 건물터로 보이는 곳이 남아 있다.","a":"고령 주산성","c":"사적","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627672.jpg"},{"q":"등받이가 높다란 의자에 우향하여 앉아 있는 좌안칠분면(左顔七分面)의 의좌상(椅坐像)으로 신발을 벗은 채 의자에 발을 올려 결가부좌하고 앉아 손에는 불자(拂子)를 들고 있다. 가는 선으로 윤곽을 짓고 이목구비를 표현하여 백묘법(白描法)을 보여주는 얼굴은 적당히 크고 길죽한 타원형으로 온화한 모습이나, 머리를 뒤로 약간 젖혀 내려보는 듯한 날카로운 눈매를 하여 의승병 대장으로서의 기상이 넘쳐난다. 건장한 어깨와 가슴 아래까지 길게 내려온 턱수염은 승병대장 다운 기백을 강조해주는데, 다른 ○○○ 영정들에 비해 길어진 수염이 특징적이다.","a":"대구 동화사 사명당 유정 진영","c":"보물","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615303.jpg"},{"q":"「○○○○○」은 통일신라시대부터 조선시대의 생활유구가 전 지역에 분포하고 있어 ○○시 고대도시의 성격을 파악할 수 있으며 서민생활상을 복원, 연구하는데 역사적 가치가 있는 매우 중요한 생활유적이다. ○○○○○지는 2004년 대한주택공사 등에서 택지개발하기 위하여 발굴조사를 실시한 결과, 통일신라시대부터 조선시대의 건물지, 연못, 수혈유구(竪穴遺構), 구상유구(溝狀遺構) 등과 도기류, 와·전류, 자기류 등 많은 유물이 출토되었다.","a":"상주 복룡동 유적","c":"사적","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628025.jpg"},{"q":"1920년대말 경성전기주식회사 ○○으로 ○○도심부에 세워진 본격적인 사무실 건물이다. 해방후 2개층이 증축되어 현재 ‘한국전력○○’으로 사용되고 있다. 최초의 내화·내진설계와 엘리베이터설비, 유리블록 등이 건축재료로 사용되었다.","a":"서울 남대문로 한국전력공사 사옥","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666866.jpg"},{"q":"과거 ○○읍성의 중심부에 1930년 건축된 ○○○○으로 지역에서 드물게 현존하는 근대문화유산이며 보존상태도 양호하다. 총 4채의 건물(안채, 사랑채, 대문간채, 창고 겸 화장실)로 구성되었으며, 전통주택 양식을 기반으로 근대적 생활양식과 주거기능의 수용에 따라 평면 및 실 구성, 공간구조가 변화되었던 ○○○○의 건축기법을 예시하고 있다.","a":"태안 동문리 근대한옥","c":"국가등록문화유산","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017121111234300.jpg"},{"q":"「○○○○○」은 중수기와 중건기 그리고 상량문 등에 담긴 내용으로 건립에서부터 현재에 이르기까지 건축 내력을 비교적 충실하게 추적할 수 있을 뿐만 아니라 후대 이루어진 보수공사를 통해 몇몇 부재들이 교체되기는 하였지만, 기둥 상부에 결구된 이익공 포작과 충량의 결구 및 가구형식 등 전체적인 건축 수법이 대체로 조선 후기의 양식을 따르고 있고 1788년 정자가 중건될 당시의 모습을 잘 유지한 채 보존상태도 양호하여 역사적, 예술적, 학술적 의미가 있음.","a":"김천 방초정","c":"보물","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019122715045100.JPG"},{"q":"○○읍에서 순창 가는 길을 따라 1㎞쯤 가다 보면 넓은 평지가 전개되는데 절터의 흔적은 없고 들 가운데에 이 석탑만이 서있다. 탑은 1층의 기단(基壇) 위에 5층의 탑신(塔身)을 올린 모습이며, 머리장식은 모두 없어졌다. 기단은 다른 탑에 비하여 높이가 매우 낮아 특이하고, 기단 맨윗돌의 너비가 1층 지붕돌의 너비보다 좁은 것 또한 특이한 양식이다. 탑신은 알맞게 체감되어 안정된 느낌이며, 2층 이상부터는 몸돌을 받치는 두툼한 괴임을 새겨 고려시대 석탑의 특색을 보여주고 있다. 지붕돌은 두껍고 처마는 경사졌으며 네 귀퉁이는 가볍게 들려있다.","a":"담양 남산리 오층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619227.jpg"}]);